INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡店", "is_correct": true, "explanation": "符合语境：咖啡店就是卖咖啡和点心的店，与「那家」搭配。"}, {"text": "药店", "is_correct": false, "explanation": "语义：药店不卖咖啡和点心，与句中的商品不符。"}, {"text": "修车店", "is_correct": false, "explanation": "语义：修车店不卖咖啡和点心，与句中的商品不符。"}, {"text": "咖啡杯", "is_correct": false, "explanation": "搭配：量词“家”用于店铺，不能修饰“咖啡杯”。"}], "explanations": {"咖啡店": "符合语境：咖啡店就是卖咖啡和点心的店，与「那家」搭配。", "药店": "语义：药店不卖咖啡和点心，与句中的商品不符。", "修车店": "语义：修车店不卖咖啡和点心，与句中的商品不符。", "咖啡杯": "搭配：量词“家”用于店铺，不能修饰“咖啡杯”。"}, "sentence_index": 0, "correct_answer": "咖啡店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下班后，我们去喝咖啡店。", "explanation": "这里应该用〈咖啡〉。咖啡店是可以坐下来的地方，不能当饮品说“喝”。"}, {"text": "下班后，我们去咖啡店打篮球。", "explanation": "这里应该用〈篮球场〉。咖啡店卖咖啡和点心，打篮球要去篮球场。"}, {"text": "下班后，我们去咖啡店修电脑。", "explanation": "这里应该用〈电脑店〉。咖啡店卖咖啡和点心，修电脑要去电脑店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咖啡店", "is_correct": true, "explanation": "符合语境：咖啡店安静，适合坐下来写作业。"}, {"text": "同学", "is_correct": false, "explanation": "配价：“在”后面要接处所，“同学”是人，不能作写作业的地点。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场很吵，与“安静”的描述相矛盾。"}, {"text": "篮球场", "is_correct": false, "explanation": "语义：篮球场是打球的地方，不是安静写作业的地方，与句意不符。"}], "explanations": {"咖啡店": "符合语境：咖啡店安静，适合坐下来写作业。", "同学": "配价：“在”后面要接处所，“同学”是人，不能作写作业的地点。", "菜市场": "语义：菜市场很吵，与“安静”的描述相矛盾。", "篮球场": "语义：篮球场是打球的地方，不是安静写作业的地方，与句意不符。"}, "sentence_index": 6, "correct_answer": "咖啡店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下午去咖啡店剪了头发。", "explanation": "这里应该用〈理发店〉。咖啡店卖咖啡和点心，剪头发要去理发店。"}, {"text": "我感冒了，去咖啡店买了点药。", "explanation": "这里应该用〈药店〉。咖啡店卖咖啡和点心，买药要去药店。"}, {"text": "我们在咖啡店游了一个小时泳。", "explanation": "这里应该用〈游泳池〉。咖啡店卖咖啡和点心，不能用来游泳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条咖啡店的点心很甜。", "corrected_sentence": "那家咖啡店的点心很甜。", "error_description": "量词错误：「咖啡店」是店铺，应搭配量词「家」；「条」用于细长的东西，不能用于店铺。正确说法为「那家咖啡店」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街上有两咖啡店。", "corrected_sentence": "这条街上有两家咖啡店。", "error_description": "错误形式：“两咖啡店”，数词后缺少量词；正确形式：“两家咖啡店”。店铺用量词“家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批发", "is_correct": true, "explanation": "反义：批发指成批卖给商户，与零售（卖给个人买家）相对，是该义项的反义词。"}, {"text": "生产", "is_correct": false, "explanation": "生产指制造东西，与“零售”的卖给买家在任何义项上都不构成近义或反义关系。"}, {"text": "种植", "is_correct": false, "explanation": "种植指栽培植物，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指修复损坏的物品，与“零售”在任何义项上都不构成近义或反义关系。"}], "correct_answer": "批发", "explanations": {"批发": "反义：批发指成批卖给商户，与零售（卖给个人买家）相对，是该义项的反义词。", "生产": "生产指制造东西，与“零售”的卖给买家在任何义项上都不构成近义或反义关系。", "种植": "种植指栽培植物，与“零售”在任何义项上都不构成近义或反义关系。", "修理": "修理指修复损坏的物品，与“零售”在任何义项上都不构成近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "批发", "is_correct": true, "explanation": "反义：批发指成批卖给商户，与零售（卖给个人买家）相对，是该义项的反义词。"}, {"text": "维修", "is_correct": false, "explanation": "维修指修理设备，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "播种", "is_correct": false, "explanation": "播种指撒种子，与“零售”在任何义项上都不构成近义或反义关系。"}, {"text": "储存", "is_correct": false, "explanation": "储存指保存物品，与“零售”在任何义项上都不构成近义或反义关系。"}], "correct_answer": "批发", "explanations": {"批发": "反义：批发指成批卖给商户，与零售（卖给个人买家）相对，是该义项的反义词。", "维修": "维修指修理设备，与“零售”在任何义项上都不构成近义或反义关系。", "播种": "播种指撒种子，与“零售”在任何义项上都不构成近义或反义关系。", "储存": "储存指保存物品，与“零售”在任何义项上都不构成近义或反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西卖给需要的人。", "primary_collocate": null, "pronunciation": "líng shòu", "ipa": "liŋ˧˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店既批发也零售各种水果。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们只批发，不零售。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂也开始零售自己做的面包了。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的小店主要零售日用品。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市零售米、油和盐等食品。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在网上零售手机。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算在门口零售新鲜的牛奶。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把自己种的菜直接零售给邻居。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店不零售，只卖给大公司。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在街边零售报纸和杂志。", "target_word": "零售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "零售了", "label": "完成体"}, {"form": "零售过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "零售：动词，一件一件地把东西卖给需要的人，与批发相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零售", "is_correct": true, "explanation": "零售指把东西一件件卖给个人买家，与前一分句的“批发”相对，句意相符。"}, {"text": "出租", "is_correct": false, "explanation": "语义：出租是把物品租给别人使用，水果不能出租，句意应是卖出。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”不能带“水果”作宾语表示卖出，这一搭配不成立。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理用于损坏的物品，与卖水果无关，句意不通。"}], "explanations": {"零售": "零售指把东西一件件卖给个人买家，与前一分句的“批发”相对，句意相符。", "出租": "语义：出租是把物品租给别人使用，水果不能出租，句意应是卖出。", "欣赏": "搭配：“欣赏”不能带“水果”作宾语表示卖出，这一搭配不成立。", "修理": "语义：修理用于损坏的物品，与卖水果无关，句意不通。"}, "sentence_index": 0, "correct_answer": "零售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂主要零售给超市。", "explanation": "这里应该用〈批发〉。零售是卖给个人买家，卖给超市这类商户要说批发。"}, {"text": "他把房子零售给别人，每个月收房租。", "explanation": "这里应该用〈出租〉。零售是把东西卖给需要的人，收房租说明房子没有卖出，要说出租。"}, {"text": "这家店每天零售二十吨大米给各个食堂。", "explanation": "这里应该用〈批发〉。零售面向个人买家，二十吨大米大批供给食堂要说批发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "零售", "is_correct": true, "explanation": "零售指把东西一件件卖给买家，句中指老板在门口卖牛奶，句意相符。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修指装饰房屋，不能用于卖牛奶，句意不通。"}, {"text": "放映", "is_correct": false, "explanation": "语义：放映指播放影片或幻灯片，与卖牛奶无关。"}, {"text": "检阅", "is_correct": false, "explanation": "搭配：检阅多用于队伍、部队，不能用于牛奶这类商品。"}], "explanations": {"零售": "零售指把东西一件件卖给买家，句中指老板在门口卖牛奶，句意相符。", "装修": "语义：装修指装饰房屋，不能用于卖牛奶，句意不通。", "放映": "语义：放映指播放影片或幻灯片，与卖牛奶无关。", "检阅": "搭配：检阅多用于队伍、部队，不能用于牛奶这类商品。"}, "sentence_index": 6, "correct_answer": "零售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂从外地零售回了一批钢材。", "explanation": "这里应该用〈采购〉。零售是把东西卖给需要的人，不能指买进钢材，买进要说采购。"}, {"text": "快递员每天把包裹零售给收件人。", "explanation": "这里应该用〈派送〉。零售是卖东西给需要的人，快递员送包裹给收件人并没有买卖，要说派送。"}, {"text": "他零售一笔钱给朋友。", "explanation": "这里应该用〈借给〉。零售的对象是货物，钱不能拿来卖，借钱给朋友要说借给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经把报纸零售了完。", "corrected_sentence": "他已经把报纸零售完了。", "error_description": "结果补语“完”应紧接动词，之后才加“了”，应说“零售完了”。错误句把“了”放在“完”之前，说成“零售了完”，不符合汉语语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一个小时就零售了完所有的水果。", "corrected_sentence": "她一个小时就零售完了所有的水果。", "error_description": "结果补语“完”应紧接动词，之后才加“了”，应说“零售完了”。错误句把“了”放在“完”之前，说成“零售了完”，不符合汉语语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
