INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21642, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "把粉放进水里，很快就没有了，变成可以喝的东西。", "primary_collocate": null, "pronunciation": "sù róng", "ipa": "su˥˩ ɻʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这包粉是速溶的，倒进热水就行。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速溶豆浆粉很快就化在水里了。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了速溶麦片。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种速溶奶粉不用煮。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速溶的饮料粉，一冲就能喝。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把速溶咖啡倒进了杯子里。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速溶茶粉遇到热水马上化开。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢速溶的，因为不用等。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盒速溶果汁粉很好喝。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加一勺速溶粉，再倒点热水。", "target_word": "速溶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "速溶咖啡", "label": "复合词"}, {"form": "速溶茶", "label": "复合词"}], "register": "通用", "sense_fingerprint": "速溶：粉末放进水里很快化开，变成能喝的饮品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "速溶", "is_correct": true, "explanation": "正确：「这包粉是速溶的，倒进热水就行」中，「速溶」说明粉末能迅速溶于水，符合句意。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：粉末不说「透明」，与「这包粉」的外观描述不符。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：「冰冷」与「倒进热水就行」矛盾。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：「易燃」是危险属性，与「倒进热水就行」的用途矛盾。"}], "explanations": {"速溶": "正确：「这包粉是速溶的，倒进热水就行」中，「速溶」说明粉末能迅速溶于水，符合句意。", "透明": "体貌：粉末不说「透明」，与「这包粉」的外观描述不符。", "冰冷": "语义：「冰冷」与「倒进热水就行」矛盾。", "易燃": "语义：「易燃」是危险属性，与「倒进热水就行」的用途矛盾。"}, "sentence_index": 0, "correct_answer": "速溶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药很速溶，吃下去十分钟就能见效。", "explanation": "这里应该用〈速效〉。「速溶」指粉末放进水里很快溶解，药效快慢应说「速效」。"}, {"text": "速溶面不用煮，泡一下就能吃。", "explanation": "这里应该用〈速食〉。「速溶」指粉末放入水中很快溶解，面条不溶解，应说「速食面」。"}, {"text": "速溶饺子放进锅里煮十分钟就能吃。", "explanation": "这里应该用〈速冻〉。「速溶」指粉末溶于水，饺子不能溶解；「速冻」指快速冷冻保存的食品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "速溶", "is_correct": true, "explanation": "正确：「速溶茶粉遇到热水马上化开」中，「速溶」说明茶粉能迅速溶解，与「马上化开」吻合。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：坚硬的东西不会「马上化开」，与句中的化开过程矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：「沉重」说的是重量，与粉末遇水化开的性质不符。"}, {"text": "皱巴巴", "is_correct": false, "explanation": "体貌：「皱巴巴」描述褶皱的外观，茶粉不这样形容。"}], "explanations": {"速溶": "正确：「速溶茶粉遇到热水马上化开」中，「速溶」说明茶粉能迅速溶解，与「马上化开」吻合。", "坚硬": "语义：坚硬的东西不会「马上化开」，与句中的化开过程矛盾。", "沉重": "语义：「沉重」说的是重量，与粉末遇水化开的性质不符。", "皱巴巴": "体貌：「皱巴巴」描述褶皱的外观，茶粉不这样形容。"}, "sentence_index": 6, "correct_answer": "速溶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门速溶课只要两周就能学完。", "explanation": "这里应该用〈速成〉。「速溶」指粉末放入水中很快溶解，课程不能溶解；「速成」指很快学会。"}, {"text": "这件衣服很速溶，洗完很快就能穿。", "explanation": "这里应该用〈速干〉。「速溶」指粉末溶于水，衣服不会溶解；「速干」才指很快干。"}, {"text": "这家餐厅上菜很速溶，五分钟就好了。", "explanation": "这里应该用〈快〉。「速溶」指粉末放进水里很快溶解，上菜快慢不能用速溶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这包粉是速溶地，一倒进热水就化开了。", "corrected_sentence": "这包粉是速溶的，一倒进热水就化开了。", "error_description": "结构助词错误：「是」之后作谓语的形容词应用「的」，不用「地」（「地」用于状语）。正确句为「这包粉是速溶的，一倒进热水就化开了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这杯咖啡是速溶地。", "corrected_sentence": "这杯咖啡是速溶的。", "error_description": "结构助词错误：「是」之后作谓语的形容词应用「的」，不用「地」。正确句为「这杯咖啡是速溶的。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
