INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找出事情从哪里开始。", "primary_collocate": null, "pronunciation": "sù yuán", "ipa": "su˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "警察正在溯源，想知道谣言是谁先说的。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是怎么开始的？我们来溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要解决问题，先要溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想溯源，找出这个习惯从哪里来的。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们一直在溯源，想知道这种语言怎么来的。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起溯源，看看错误出在哪一步。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事很有意思，值得溯源一下。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食品出了问题，公司马上开始溯源。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们溯源了三天，终于找到了原因。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢溯源，每个词都想弄清来历。", "target_word": "溯源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "溯源了", "label": "体标"}, {"form": "溯源过", "label": "体标"}, {"form": "追根溯源", "label": "复合"}], "register": "书面", "sense_fingerprint": "找出事情从哪里开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溯源", "is_correct": true, "explanation": "正确：溯源指追查事情从哪里开始，此处指追查谣言的源头。"}, {"text": "休息", "is_correct": false, "explanation": "语义：休息是停止活动，与「想知道谣言是谁先说的」的追查意图完全不符。"}, {"text": "宣传", "is_correct": false, "explanation": "语义：宣传是扩散信息，与追查谣言源头的动机相矛盾。"}, {"text": "散布", "is_correct": false, "explanation": "配价：散布是及物动词，需要带宾语，不能单独用在「正在」之后。"}], "explanations": {"溯源": "正确：溯源指追查事情从哪里开始，此处指追查谣言的源头。", "休息": "语义：休息是停止活动，与「想知道谣言是谁先说的」的追查意图完全不符。", "宣传": "语义：宣传是扩散信息，与追查谣言源头的动机相矛盾。", "散布": "配价：散布是及物动词，需要带宾语，不能单独用在「正在」之后。"}, "sentence_index": 0, "correct_answer": "溯源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗看见猫，就开始溯源它。", "explanation": "这里应该用〈追逐〉。溯源指找出事情的起点，不用于追赶动物。"}, {"text": "他弄丢了钥匙，在房间里溯源钥匙。", "explanation": "这里应该用〈寻找〉。溯源指找出事情从哪里开始，找丢失的东西要用寻找。"}, {"text": "他在厨房里一口气溯源了三碗面。", "explanation": "这里应该用〈吃〉。溯源指找出事情的起点，表示快速吃东西要用吃，不能用溯源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溯源", "is_correct": true, "explanation": "正确：「值得溯源一下」指值得追查这个故事的来历，与「有意思」相合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记与故事「有意思」、值得追究的评价相矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除与故事值得追查的评价相矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「很有意思」是正面评价，「值得拒绝一下」与之矛盾。"}], "explanations": {"溯源": "正确：「值得溯源一下」指值得追查这个故事的来历，与「有意思」相合。", "忘记": "语义：忘记与故事「有意思」、值得追究的评价相矛盾。", "删除": "语义：删除与故事值得追查的评价相矛盾。", "拒绝": "语义：「很有意思」是正面评价，「值得拒绝一下」与之矛盾。"}, "sentence_index": 6, "correct_answer": "溯源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天溯源两小时的电视。", "explanation": "这里应该用〈看〉。溯源指找出事情的起点，看电视是消遣，不能用溯源。"}, {"text": "我们在操场上溯源了三圈。", "explanation": "溯源指找出事情的起点，不表示跑步，表示跑圈这一动作应改用〈跑步〉。"}, {"text": "妈妈在厨房里溯源碗筷。", "explanation": "这里应该用〈洗〉。溯源指找出事情的起点，清洗碗筷要用洗，不能用溯源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校正在一步步的溯源，找出错误的原因。", "corrected_sentence": "学校正在一步步地溯源，找出错误的原因。", "error_description": "结构助词错误：「正在」后接的动词短语中，修饰「溯源」的状语应用「地」，不用「的」，说「一步步地溯源」。正确句为「学校正在一步步地溯源，找出错误的原因。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21644, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经溯源把这个问题的起点。", "corrected_sentence": "他已经溯源到这个问题的起点。", "error_description": "补语错误：表示追溯终点的结果补语「到」应紧跟动词「溯源」，不能用介词「把」代替。正确句为「他已经溯源到这个问题的起点。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
