INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种子是能长出植物的东西。", "primary_collocate": null, "pronunciation": "zhǒng zi", "ipa": "ʈʂʊŋ˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "春天到了，农民开始买种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗种子很小，可是能长成大树。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把种子放在土里，每天给它浇水。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟吃了树上的种子，又飞走了。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花的种子是爷爷从老家带来的。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子需要水和阳光才能发芽。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有很多花的种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在花盆里撒了一把种子。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜的种子是黑色的。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把种子收好，明年春天再种。", "target_word": "种子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗种子", "label": "量词（颗）"}, {"form": "一粒种子", "label": "量词（粒）"}], "register": "中性", "sense_fingerprint": "种子-植物的种子，能发芽长成植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '892e6a23-674a-4223-9c9c-54e9c0f9d361') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "种子", "is_correct": true, "explanation": "种子（zhǒng zi）：能长出植物的东西。"}, {"text": "粽子", "is_correct": false, "explanation": "粽子（zòng zi）与种子（zhǒng zi）声母不同（z 与 zh），声调也不同，意思是粽子。"}, {"text": "虫子", "is_correct": false, "explanation": "虫子（chóng zi）与种子（zhǒng zi）声母不同（ch 与 zh），声调也不同，意思是小虫。"}, {"text": "长子", "is_correct": false, "explanation": "长子（zhǎng zi）与种子（zhǒng zi）韵母不同（ang 与 ong），意思是家中的大儿子。"}], "explanations": {"种子": "种子（zhǒng zi）：能长出植物的东西。", "粽子": "粽子（zòng zi）与种子（zhǒng zi）声母不同（z 与 zh），声调也不同，意思是粽子。", "虫子": "虫子（chóng zi）与种子（zhǒng zi）声母不同（ch 与 zh），声调也不同，意思是小虫。", "长子": "长子（zhǎng zi）与种子（zhǒng zi）韵母不同（ang 与 ong），意思是家中的大儿子。"}, "sentence_index": null, "correct_answer": "种子"}, "level_3": {"options": [{"text": "阳光", "is_correct": false, "explanation": "搭配：阳光不能买，“买阳光”不成立。"}, {"text": "种子", "is_correct": true, "explanation": "“买种子”是农民春天播种前常做的事，符合语境。"}, {"text": "春风", "is_correct": false, "explanation": "搭配：“买”要求可以购买的东西，“春风”不能买。"}, {"text": "雪花", "is_correct": false, "explanation": "语义：春天一般不下雪，“雪花”与“春天到了”的语境不符。"}], "explanations": {"阳光": "搭配：阳光不能买，“买阳光”不成立。", "种子": "“买种子”是农民春天播种前常做的事，符合语境。", "春风": "搭配：“买”要求可以购买的东西，“春风”不能买。", "雪花": "语义：春天一般不下雪，“雪花”与“春天到了”的语境不符。"}, "sentence_index": 0, "correct_answer": "种子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在阳台上唱种子。", "explanation": "这里应该用〈歌〉。“唱”的对象是歌曲，种子不能被唱。"}, {"text": "他每天喝了很多种子。", "explanation": "这里应该用〈牛奶〉。能喝的是饮料，种子不能用来喝。"}, {"text": "他轻轻迈开种子。", "explanation": "这里应该用〈脚步〉。“迈开”的对象是脚步，种子不能被迈开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌声", "is_correct": false, "explanation": "语义：“花的歌声”不成立，花不会唱歌。"}, {"text": "种子", "is_correct": true, "explanation": "“超市里有很多花的种子”指超市里出售各种花的种子，符合语境。"}, {"text": "零件", "is_correct": false, "explanation": "搭配：“花的零件”不成立；零件是机器的组成部分，与超市里的花类商品不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“花的天气”不成立，超市里也不会有天气。"}], "explanations": {"歌声": "语义：“花的歌声”不成立，花不会唱歌。", "种子": "“超市里有很多花的种子”指超市里出售各种花的种子，符合语境。", "零件": "搭配：“花的零件”不成立；零件是机器的组成部分，与超市里的花类商品不符。", "天气": "语义：“花的天气”不成立，超市里也不会有天气。"}, "sentence_index": 6, "correct_answer": "种子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他仔细听着远处的种子。", "explanation": "这里应该用〈钟声〉。“听”的对象是声音，种子不能被听。"}, {"text": "他讲了一个种子。", "explanation": "这里应该用〈笑话〉。“讲”的对象是故事或话语，种子不能讲。"}, {"text": "他很会弹种子。", "explanation": "这里应该用〈吉他〉。“弹”的对象是乐器，种子不能被弹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把一只种子放进了仓库里。", "corrected_sentence": "农民把一包种子放进了仓库里。", "error_description": "量词用错。种子的量词应为“包、袋、粒”等，“只”用于动物，不能修饰种子，所以不能说“一只种子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21646, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在花盆里撒了一只种子。", "corrected_sentence": "她在花盆里撒了一粒种子。", "error_description": "量词用错。种子的量词应为“粒、颗”，“只”用于动物，不能说“一只种子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cae14e5c-e07c-4bf1-9912-b238114359dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
