INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "运动就是让身体动起来，比如跑步、跳高。", "primary_collocate": null, "pronunciation": "yùn dòng", "ipa": "yn˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我每天都做运动。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "跑步是我最爱的运动。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多做运动对身体好。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你喜欢什么运动？", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个周末都去公园做运动。", "target_word": "运动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳是一种很好的运动。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这项运动不太难。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们喜欢在学校做运动。", "target_word": "运动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说老人要多做运动。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "打球是他最喜欢的运动。", "target_word": "运动", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项运动", "label": "量词"}, {"form": "一种运动", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，指跑步、游泳等锻炼身体的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "搭配：“做”不接自然现象，不说“做天气”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是可以去“做”的活动，“我每天都做河流”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以去“做”的事情，句子说不通。"}, {"text": "运动", "is_correct": true, "explanation": "运动：指锻炼身体的活动，与“做”搭配，符合句意。"}], "explanations": {"天气": "搭配：“做”不接自然现象，不说“做天气”。", "河流": "语义：河流不是可以去“做”的活动，“我每天都做河流”说不通。", "天空": "语义：天空不是可以去“做”的事情，句子说不通。", "运动": "运动：指锻炼身体的活动，与“做”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "运动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把运动放在书桌上。", "explanation": "这里应该用〈运动鞋〉。运动指体育锻炼或身体活动，不是可以放在桌上的物品；指鞋要说“运动鞋”。"}, {"text": "他是我们学校的运动。", "explanation": "这里应该用〈运动员〉。运动是动作或项目，不指人；指参加比赛的人要用“运动员”。"}, {"text": "他去超市买了两斤运动。", "explanation": "这里应该用〈水果〉。运动是锻炼身体的活动，不能用“斤”来买；买吃的要说“水果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": false, "explanation": "搭配：“项”多用于活动、任务，不说“这项蔬菜”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“项”用于活动、任务，不说“这项房子”，句子说不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是可以“难”或“不难”的事项，句子说不通。"}, {"text": "运动", "is_correct": true, "explanation": "运动：指锻炼身体的活动，可以用“这项”指代，与“不太难”相符。"}], "explanations": {"蔬菜": "搭配：“项”多用于活动、任务，不说“这项蔬菜”。", "房子": "搭配：“项”用于活动、任务，不说“这项房子”，句子说不通。", "星星": "语义：星星不是可以“难”或“不难”的事项，句子说不通。", "运动": "运动：指锻炼身体的活动，可以用“这项”指代，与“不太难”相符。"}, "sentence_index": 6, "correct_answer": "运动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件运动很漂亮。", "explanation": "这里应该用〈运动服〉。运动是锻炼身体的活动，不是衣服；“这件”要接“运动服”。"}, {"text": "这碗运动很好吃。", "explanation": "这里应该用〈饭〉。运动是活动，不能用来形容食物；指吃的东西要用“饭”。"}, {"text": "他用运动写字。", "explanation": "这里应该用〈铅笔〉。运动是锻炼身体的活动，不是写字的工具；写字要用“铅笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一只运动。", "corrected_sentence": "我想学一项运动。", "error_description": "错误：量词“只”不能搭配“运动”，应说“一项运动”或“一种运动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我周末常常打运动。", "corrected_sentence": "我周末常常做运动。", "error_description": "错误：“运动”和动词“做”搭配，不说“打运动”，应说“我周末常常做运动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "忽视指不重视、不留心，与“关注”构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中运动，与“关注”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步指慢慢地走路，与“关注”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡指清洁身体，与“关注”没有反义关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "忽视指不重视、不留心，与“关注”构成反义关系。", "游泳": "游泳指在水中运动，与“关注”没有反义关系。", "散步": "散步指慢慢地走路，与“关注”没有反义关系。", "洗澡": "洗澡指清洁身体，与“关注”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "忽视指不重视、不留心，与“关注”构成反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指用声音表演曲调，与“关注”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步指快速地跑，与“关注”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉指闭眼休息，与“关注”没有反义关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "忽视指不重视、不留心，与“关注”构成反义关系。", "唱歌": "唱歌指用声音表演曲调，与“关注”没有反义关系。", "跑步": "跑步指快速地跑，与“关注”没有反义关系。", "睡觉": "睡觉指闭眼休息，与“关注”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留心并放在心上；重视某人或某事。", "primary_collocate": null, "pronunciation": "guān zhù", "ipa": "kwan˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "大家都很关注这个消息。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近一直关注这件事。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很关注每个学生的学习。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关注着天气的变化。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人关注过这个问题。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈特别关注孩子的健康。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天都关注新闻。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家多关注身边的小事。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们关注环境问题已经很久了。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不太关注别人怎么说。", "target_word": "关注", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "关注着", "label": "体标（着）"}, {"form": "关注了", "label": "体标（了）"}, {"form": "关注过", "label": "体标（过）"}, {"form": "關注", "label": "繁体"}], "register": "中性", "sense_fingerprint": "留心看着并放在心上，重视某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "关注", "is_correct": true, "explanation": "正确答案。关注（guān zhù）意思是留心并放在心上。"}, {"text": "管住", "is_correct": false, "explanation": "guǎn（第三声）与 guān（第一声）声调不同，管住意思是控制住、约束住。"}, {"text": "灌注", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，灌注意思是注入、灌进。"}, {"text": "贯注", "is_correct": false, "explanation": "guàn（第四声）与 guān（第一声）声调不同，贯注意思是（精神）集中在某处。"}], "explanations": {"关注": "正确答案。关注（guān zhù）意思是留心并放在心上。", "管住": "guǎn（第三声）与 guān（第一声）声调不同，管住意思是控制住、约束住。", "灌注": "guàn（第四声）与 guān（第一声）声调不同，灌注意思是注入、灌进。", "贯注": "guàn（第四声）与 guān（第一声）声调不同，贯注意思是（精神）集中在某处。"}, "sentence_index": null, "correct_answer": "关注"}, "level_3": {"options": [{"text": "关注", "is_correct": true, "explanation": "“关注”表示留心、放在心上，与“这个消息”搭配，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“消息”作宾语。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理、修补，与“消息”不搭。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”一般不能带“消息”作宾语。"}], "explanations": {"关注": "“关注”表示留心、放在心上，与“这个消息”搭配，句意通顺。", "吃": "搭配：“吃”不能带“消息”作宾语。", "修": "语义：“修”指修理、修补，与“消息”不搭。", "洗": "搭配：“洗”一般不能带“消息”作宾语。"}, "sentence_index": 0, "correct_answer": "关注"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他关注了一碗米饭。", "explanation": "这里应该用〈吃〉。关注指留心某事，不能用来表示吃饭。"}, {"text": "我每周都去医院关注生病的奶奶。", "explanation": "这里应该用〈看望〉。看望指去探视某人，关注只表示留心，不能表示去医院探视病人。"}, {"text": "我刚才关注了一眼手机。", "explanation": "这里应该用〈看〉。关注指持续地放在心上，只看一眼要用看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关注", "is_correct": true, "explanation": "“关注”表示留心、放在心上，与“新闻”搭配，句意通顺。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”不能带“新闻”作宾语。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”不能带“新闻”作宾语。"}, {"text": "来", "is_correct": false, "explanation": "配价：“来”是不及物动词，不能带宾语“新闻”。"}], "explanations": {"关注": "“关注”表示留心、放在心上，与“新闻”搭配，句意通顺。", "煮": "搭配：“煮”不能带“新闻”作宾语。", "切": "搭配：“切”不能带“新闻”作宾语。", "来": "配价：“来”是不及物动词，不能带宾语“新闻”。"}, "sentence_index": 6, "correct_answer": "关注"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在公园关注风景。", "explanation": "这里应该用〈欣赏〉。欣赏指喜爱地观赏美好的景物，关注指留心某事，不能用来表示观赏风景。"}, {"text": "我把钥匙关注在桌子上。", "explanation": "这里应该用〈放〉。关注指留心某事，不能表示把东西放在某处。"}, {"text": "他轻轻关注了小狗的头。", "explanation": "这里应该用〈摸〉。摸指用手轻轻触碰，关注指留心某事，不能表示用手触碰小狗的头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一直关注了着我的成绩。", "corrected_sentence": "妈妈一直关注着我的成绩。", "error_description": "错误在于“关注”后面同时用了“了”和“着”两个动态助词。正确形式是“关注着”，表示持续的关注状态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直关注了这件事。", "corrected_sentence": "她一直关注着这件事。", "error_description": "错误在于体标。“一直”表示持续的状态，“关注”后面应该用“着”，不能用表示完成的“了”。正确形式是“一直关注着这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
