INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21652, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "讲给别人听的一些事情，可能是真的，也可能是假的。", "primary_collocate": null, "pronunciation": "gù shi", "ipa": "ku˥˩ ʂʅ", "syllable_count": 2, "sentences": [{"text": "我小时候最喜欢听奶奶讲故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是真的还是假的？", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事把大家都逗笑了。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你给我们讲一个短故事吧。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事我听过很多次了。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的主人公是一只小熊。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥编了一个关于月亮的故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上，每个人都要讲一个故事。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，故事讲完就要睡觉了。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事告诉我们要诚实。", "target_word": "故事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个故事", "label": "量词"}, {"form": "一则故事", "label": "量词"}, {"form": "故事书", "label": "复合"}], "register": "中性", "sense_fingerprint": "讲给别人听的事情，可真可假；日常口头讲述", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "故事", "is_correct": true, "explanation": "正确答案：听到的是“故事”（gù shi），指讲给别人听的事情。"}, {"text": "股市", "is_correct": false, "explanation": "股市（gǔshì）与故事（gù shi）声调不同，意思是股票市场。"}, {"text": "古时", "is_correct": false, "explanation": "古时（gǔshí）与故事（gù shi）声调不同，意思是古代。"}, {"text": "古史", "is_correct": false, "explanation": "古史（gǔshǐ）与故事（gù shi）声调不同，意思是古代的历史。"}], "explanations": {"故事": "正确答案：听到的是“故事”（gù shi），指讲给别人听的事情。", "股市": "股市（gǔshì）与故事（gù shi）声调不同，意思是股票市场。", "古时": "古时（gǔshí）与故事（gù shi）声调不同，意思是古代。", "古史": "古史（gǔshǐ）与故事（gù shi）声调不同，意思是古代的历史。"}, "sentence_index": null, "correct_answer": "故事"}, "level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具是实物，不是可以讲给别人听的事情。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“讲”用于故事、道理，唱歌要说“唱”，不说“讲歌”。"}, {"text": "故事", "is_correct": true, "explanation": "正确：“故事”与“讲”搭配，指讲给别人听的事情，符合句意。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜是食物，不是可以讲述的内容。"}], "explanations": {"玩具": "语义：玩具是实物，不是可以讲给别人听的事情。", "歌": "搭配：“讲”用于故事、道理，唱歌要说“唱”，不说“讲歌”。", "故事": "正确：“故事”与“讲”搭配，指讲给别人听的事情，符合句意。", "菜": "语义：菜是食物，不是可以讲述的内容。"}, "sentence_index": 0, "correct_answer": "故事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这个故事送进了医院。", "explanation": "这里应该用〈病人〉。“送进医院”针对需要治疗的人，故事是讲述的内容，不能送进医院。"}, {"text": "我戴上了这个故事。", "explanation": "这里应该用〈眼镜〉。“戴”用于眼镜、帽子等穿戴物，故事是讲述的内容，不能戴。"}, {"text": "他每月的故事很稳定。", "explanation": "这里应该用〈收入〉。“稳定”可以形容收入，故事不能说稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21652, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "故事", "is_correct": true, "explanation": "正确答案：听到的是“故事”（gù shi），指讲给别人听的事情。"}, {"text": "护士", "is_correct": false, "explanation": "护士（hùshi）与故事（gù shi）声母不同（h 与 g），意思是护理病人的人。"}, {"text": "古诗", "is_correct": false, "explanation": "古诗（gǔshī）与故事（gù shi）声调不同，意思是古代的诗。"}, {"text": "古式", "is_correct": false, "explanation": "古式（gǔshì）与故事（gù shi）声调不同，意思是古代的样式。"}], "explanations": {"故事": "正确答案：听到的是“故事”（gù shi），指讲给别人听的事情。", "护士": "护士（hùshi）与故事（gù shi）声母不同（h 与 g），意思是护理病人的人。", "古诗": "古诗（gǔshī）与故事（gù shi）声调不同，意思是古代的诗。", "古式": "古式（gǔshì）与故事（gù shi）声调不同，意思是古代的样式。"}, "sentence_index": null, "correct_answer": "故事"}, "level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "语义：雨是自然现象，不能被编出来。"}, {"text": "故事", "is_correct": true, "explanation": "正确：“编故事”搭配自然，“关于月亮的故事”符合句意。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“编”不能用于照片，照片应说“拍”。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是器物，不能编出来。"}], "explanations": {"雨": "语义：雨是自然现象，不能被编出来。", "故事": "正确：“编故事”搭配自然，“关于月亮的故事”符合句意。", "照片": "搭配：“编”不能用于照片，照片应说“拍”。", "盘子": "语义：盘子是器物，不能编出来。"}, "sentence_index": 6, "correct_answer": "故事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校有严格的故事。", "explanation": "这里应该用〈规定〉。“严格”形容规定、纪律，故事是讲述的事，不能说严格。"}, {"text": "我们扫了这个故事。", "explanation": "这里应该用〈地〉。“扫”的对象是地面或垃圾，故事是讲述的内容，不能扫。"}, {"text": "这个故事很咸。", "explanation": "这里应该用〈菜〉。“咸”形容食物的味道，故事是讲述的内容，没有咸淡，不能说咸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每晚都给我讲一首新故事。", "corrected_sentence": "妈妈每晚都给我讲一个新故事。", "error_description": "错误在量词。“故事”的量词应为“个”或“则”，“首”用于诗歌，不能用于故事。应说“一个新故事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些故事们是大人和孩子都爱听的。", "corrected_sentence": "这些故事是大人和孩子都爱听的。", "error_description": "错误在“故事”后加了“们”。“故事”是名词，“们”只用于指人的名词，这里不能加。应说“这些故事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
