INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21656, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "理念就是一个人心里认为很重要的想法。", "primary_collocate": null, "pronunciation": "lǐ niàn", "ipa": "li˨˩˦ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家学校的理念是让每个孩子快乐。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有自己的教育理念。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的理念是客人第一。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的理念要用行动来表现。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的理念不同，常常吵架。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的生活理念很简单：每天都要快乐。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个店的理念是只卖好东西。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把新理念带进了课堂。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保的理念，现在很多人都接受。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的理念是：对人要好，做事要认真。", "target_word": "理念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种理念", "label": "量词"}, {"form": "新理念", "label": "复合"}], "register": "书面", "sense_fingerprint": "人或机构心中认为重要的想法和原则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "理念", "is_correct": true, "explanation": "正确答案：理念，指人或机构心中认为重要的想法和原则。"}, {"text": "例年", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，nián（第二声）与 niàn（第四声）声调不同，意思是往年、每年。"}, {"text": "留念", "is_correct": false, "explanation": "liú（第二声）与 lǐ（第三声）韵母与声调不同，niàn 相同，意思是留作纪念。"}, {"text": "里面", "is_correct": false, "explanation": "miàn（第四声）与 niàn（第四声）声母不同（m 与 n），意思是里头、内部。"}], "explanations": {"理念": "正确答案：理念，指人或机构心中认为重要的想法和原则。", "例年": "lì（第四声）与 lǐ（第三声）声调不同，nián（第二声）与 niàn（第四声）声调不同，意思是往年、每年。", "留念": "liú（第二声）与 lǐ（第三声）韵母与声调不同，niàn 相同，意思是留作纪念。", "里面": "miàn（第四声）与 niàn（第四声）声母不同（m 与 n），意思是里头、内部。"}, "sentence_index": null, "correct_answer": "理念"}, "level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "正确：“理念”指学校心中认为重要的想法和原则，与句子语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，学校的颜色不能是“让每个孩子快乐”。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”多用于食物，不搭配“学校”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，与“让每个孩子快乐”的内容无关。"}], "explanations": {"理念": "正确：“理念”指学校心中认为重要的想法和原则，与句子语境相符。", "颜色": "语义：“颜色”指色彩，学校的颜色不能是“让每个孩子快乐”。", "口味": "搭配：“口味”多用于食物，不搭配“学校”。", "温度": "语义：“温度”指冷热程度，与“让每个孩子快乐”的内容无关。"}, "sentence_index": 0, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到的理念很充分。", "explanation": "这里应该用〈理由〉。理念指想法和原则，解释迟到的原因要用理由。"}, {"text": "她的理念很开朗。", "explanation": "这里应该用〈性格〉。理念指心里认为重要的想法，形容人的为人、脾气要用性格，理念不能这样形容。"}, {"text": "这盆花的理念有三十厘米。", "explanation": "这里应该用〈高度〉。理念是抽象的想法，不能量出厘米数，花的高矮要说高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理念", "is_correct": true, "explanation": "正确：“理念”指经营者心中的根本想法，与“只卖好东西”相符。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，不能指经营的原则。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”要说多少钱，不能说“只卖好东西”。"}, {"text": "规模", "is_correct": false, "explanation": "语义：“规模”指范围的大小，与“只卖好东西”的经营原则无关。"}], "explanations": {"理念": "正确：“理念”指经营者心中的根本想法，与“只卖好东西”相符。", "面积": "语义：“面积”指平面的大小，不能指经营的原则。", "价格": "搭配：“价格”要说多少钱，不能说“只卖好东西”。", "规模": "语义：“规模”指范围的大小，与“只卖好东西”的经营原则无关。"}, "sentence_index": 6, "correct_answer": "理念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个店的理念一斤三十块。", "explanation": "这里应该用〈价格〉。理念是抽象的想法，不能按斤计价，说东西卖多少钱要用价格。"}, {"text": "这把椅子的理念很结实。", "explanation": "这里应该用〈结构〉。理念是抽象的想法，不能形容椅子结不结实，要说结构。"}, {"text": "这杯理念很热。", "explanation": "这里应该用〈水〉。理念是抽象的想法，不能用“杯”盛装，也不能说热，这里应该说水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一本很好的理念。", "corrected_sentence": "他有一种很好的理念。", "error_description": "“理念”的量词应用“种”，应写作“一种很好的理念”；“本”用于书籍等，不能修饰“理念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们理念是服务客户。", "corrected_sentence": "我们的理念是服务客户。", "error_description": "“我们”修饰“理念”时要加“的”，应写作“我们的理念”；“我们理念”缺少定语标记“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
