INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21658, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西的方法。", "primary_collocate": null, "pronunciation": "chǔ lǐ gōng yì", "ipa": "ʈʂʰu˨˩˦ li˨˩˦ kʊŋ˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "这家工厂的处理工艺很先进。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶的处理工艺决定了茶的味道。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅向我们介绍了皮革的处理工艺。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的处理工艺让成本低了很多。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果干的处理工艺并不复杂。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布的处理工艺要用到热水。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种处理工艺各有优缺点。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这里的处理工艺很感兴趣。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把传统处理工艺保留了下来。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公开了新产品的处理工艺。", "target_word": "处理工艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种处理工艺", "label": "量词"}, {"form": "一套处理工艺", "label": "量词"}], "register": "书面", "sense_fingerprint": "做东西、加工东西的方法；工厂和手工制作中的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情是人的感受，不能用“先进”形容，句意不通。"}, {"text": "规模", "is_correct": false, "explanation": "语义：规模只说大小，不说先进。"}, {"text": "处理工艺", "is_correct": true, "explanation": "正确：“处理工艺”是做东西的方法，可以说先进，符合句意。"}, {"text": "门道", "is_correct": false, "explanation": "语域：“门道”口语化，与这里的书面表述不符。"}], "explanations": {"心情": "语义：心情是人的感受，不能用“先进”形容，句意不通。", "规模": "语义：规模只说大小，不说先进。", "处理工艺": "正确：“处理工艺”是做东西的方法，可以说先进，符合句意。", "门道": "语域：“门道”口语化，与这里的书面表述不符。"}, "sentence_index": 0, "correct_answer": "处理工艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的处理工艺长高了很多。", "explanation": "这里应该用〈身高〉。“长高”说的是人或植物的身高增长，处理工艺是做东西的方法，不能长高。"}, {"text": "他们修理了这个处理工艺。", "explanation": "这里应该用〈机器〉。“修理”的对象是机器等实物，处理工艺是做东西的方法，不能修理。"}, {"text": "今天的处理工艺很冷。", "explanation": "这里应该用〈天气〉。“冷”是天气的状况，处理工艺是做东西的方法，不能说冷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：噪音是声响，不是可以比较优缺点的做法，句意不通。"}, {"text": "处理工艺", "is_correct": true, "explanation": "正确：“处理工艺”各有优缺点，符合句意。"}, {"text": "病", "is_correct": false, "explanation": "语义：病不能说各有优缺点，语境也不符。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：叹息是情绪的表达，不能说有优缺点。"}], "explanations": {"噪音": "语义：噪音是声响，不是可以比较优缺点的做法，句意不通。", "处理工艺": "正确：“处理工艺”各有优缺点，符合句意。", "病": "语义：病不能说各有优缺点，语境也不符。", "叹息": "语义：叹息是情绪的表达，不能说有优缺点。"}, "sentence_index": 6, "correct_answer": "处理工艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们打了处理工艺给老师。", "explanation": "这里应该用〈电话〉。“打”的对象是电话，处理工艺不能被拨打。"}, {"text": "他的处理工艺很高兴。", "explanation": "这里应该用〈心情〉。“高兴”形容人的心情，处理工艺是做东西的方法，不能说高兴。"}, {"text": "这些处理工艺很好吃。", "explanation": "这里应该用〈饭菜〉。“好吃”形容食物，处理工艺是做东西的方法，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司换了一台新的处理工艺。", "corrected_sentence": "这家公司换了一套新的处理工艺。", "error_description": "错误在量词。“处理工艺”的量词应为“套”或“种”，“台”用于机器，不能用于工艺。应说“一套新的处理工艺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些处理工艺们各有特点。", "corrected_sentence": "这些处理工艺各有特点。", "error_description": "错误在“处理工艺”后加了“们”。“们”只用于指人的名词，“处理工艺”不能加。应说“这些处理工艺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
