INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来判断事情对不对、好不好，或者合不合要求的东西。", "primary_collocate": null, "pronunciation": "biāo zhǔn", "ipa": "pjɑʊ˥ ʈʂuən˨˩", "syllable_count": 2, "sentences": [{"text": "这家餐厅的卫生标准很高。", "target_word": "标准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师按照什么标准给我们打分？", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选工作时，每个人的标准都不一样。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的尺码不符合国家标准。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的标准放得太高了。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛要达到一定的标准。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司定了新的安全标准，大家都要学习。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你心目中好老师的标准是什么？", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的质量必须达到饮用标准。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "判断一个人好不好，不能只用一个标准。", "target_word": "标准", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个标准", "label": "量词"}, {"form": "一项标准", "label": "量词"}, {"form": "標準", "label": "繁体"}], "register": "中性", "sense_fingerprint": "判断好坏、对错或是否合格的依据；名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "标准", "is_correct": true, "explanation": "正确答案：标准（biāo zhǔn），指判断好坏、对错的依据。"}, {"text": "标注", "is_correct": false, "explanation": "zhǔn（第三声）与 zhù（第四声）韵母与声调不同，「标注」意思是做记号、注明。"}, {"text": "保准", "is_correct": false, "explanation": "biāo（第一声）与 bǎo（第三声）韵母与声调不同，「保准」意思是一定、保证。"}, {"text": "包准", "is_correct": false, "explanation": "biāo 与 bāo 韵母不同（少了 i），「包准」意思是保证，口语中常用。"}], "explanations": {"标准": "正确答案：标准（biāo zhǔn），指判断好坏、对错的依据。", "标注": "zhǔn（第三声）与 zhù（第四声）韵母与声调不同，「标注」意思是做记号、注明。", "保准": "biāo（第一声）与 bǎo（第三声）韵母与声调不同，「保准」意思是一定、保证。", "包准": "biāo 与 bāo 韵母不同（少了 i），「包准」意思是保证，口语中常用。"}, "sentence_index": null, "correct_answer": "标准"}, "level_3": {"options": [{"text": "标准", "is_correct": true, "explanation": "正确：「卫生标准」指卫生的判断依据，「卫生标准很高」说得通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「卫生体重」说不通，体重不属于卫生的判断依据。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能作为「卫生」的衡量对象，「卫生年龄」不通。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：「很高」不修饰「距离」，应说「很远」。"}], "explanations": {"标准": "正确：「卫生标准」指卫生的判断依据，「卫生标准很高」说得通。", "体重": "语义：「卫生体重」说不通，体重不属于卫生的判断依据。", "年龄": "语义：年龄不能作为「卫生」的衡量对象，「卫生年龄」不通。", "距离": "搭配：「很高」不修饰「距离」，应说「很远」。"}, "sentence_index": 0, "correct_answer": "标准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的标准很便宜。", "explanation": "这里应该用〈价格〉。标准指判断好坏的依据，说价钱要用〈价格〉。"}, {"text": "他的数学标准考了九十分。", "explanation": "这里应该用〈成绩〉。标准是衡量的依据，不能说考了多少分，考试结果要用〈成绩〉。"}, {"text": "这块牛肉的标准很足。", "explanation": "这里应该用〈分量〉。标准指判断事情的依据，牛肉的多少要用〈分量〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "标准", "is_correct": true, "explanation": "正确：「安全标准」是可以由公司制定、大家要学习的规定，说得通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「安全」不修饰「工资」，「安全工资」不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能由公司制定，也不是大家要学习的安全规定。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：「餐厅」是场所，不能作为公司定下的、需要学习的安全规定。"}], "explanations": {"标准": "正确：「安全标准」是可以由公司制定、大家要学习的规定，说得通。", "工资": "搭配：「安全」不修饰「工资」，「安全工资」不通。", "天气": "语义：天气不能由公司制定，也不是大家要学习的安全规定。", "餐厅": "语义：「餐厅」是场所，不能作为公司定下的、需要学习的安全规定。"}, "sentence_index": 6, "correct_answer": "标准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的标准很漂亮。", "explanation": "这里应该用〈颜色〉。标准指判断依据，形容衣服外观要用〈颜色〉或〈款式〉。"}, {"text": "这篇文章的标准有五千。", "explanation": "这里应该用〈字数〉。标准不能指字数，表示篇幅要用〈字数〉。"}, {"text": "这辆车的标准很快。", "explanation": "这里应该用〈速度〉。标准指判断依据，车辆的快慢要用〈速度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校定了一只严格的标准。", "corrected_sentence": "这所学校定了一套严格的标准。", "error_description": "量词错误：「只」用于动物或成对物中的一个，「标准」应用「套」、「个」或「项」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都要遵守统一地标准。", "corrected_sentence": "大家都要遵守统一的标准。", "error_description": "结构助词错误：「统一」修饰名词「标准」时应用「的」，写作「统一的标准」；错句误用「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
