INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好、更厉害。", "primary_collocate": null, "pronunciation": "shēng jí", "ipa": "ʂɤŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我想把旧电脑升级一下。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸请人升级了家里的网络。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司打算升级这套旧系统。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想升级教室里的设备。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅升级了菜单和服务。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每个月都花钱升级手机里的软件。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买了新机器，升级了生产线。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们升级了酒店的房间，住着更舒服。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先升级你的手机，再下载这个软件。", "target_word": "升级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校升级了图书馆的电脑。", "target_word": "升级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "升级了", "label": "体标（了）"}, {"form": "升级过", "label": "体标（过）"}, {"form": "升级版", "label": "复合"}, {"form": "升級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人使某物变得更好（及物）：升级电脑、升级系统、升级设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：让东西变得更好、更厉害。"}, {"text": "生计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。"}, {"text": "省级", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。"}, {"text": "生机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}], "explanations": {"升级": "正确答案。升级：让东西变得更好、更厉害。", "生计": "jì（第四声）与 jí（第二声）声调不同，生计指谋生的办法。", "省级": "shěng（第三声）与 shēng（第一声）声调不同，省级指省一级的层次。", "生机": "jī（第一声）与 jí（第二声）声调不同，生机指生命力。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“把旧电脑升级一下”表示让旧电脑变得更好。"}, {"text": "唱", "is_correct": false, "explanation": "语义：电脑不能“唱”，句意不通。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是植物或土地，不能说“浇电脑”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”只用于人或动物，电脑不能“吃”。"}], "explanations": {"升级": "正确答案。“把旧电脑升级一下”表示让旧电脑变得更好。", "唱": "语义：电脑不能“唱”，句意不通。", "浇": "搭配：“浇”的对象是植物或土地，不能说“浇电脑”。", "吃": "语义：“吃”只用于人或动物，电脑不能“吃”。"}, "sentence_index": 0, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生升级了很多病人。", "explanation": "这里应该用〈治疗〉。升级用于使器物、系统等变得更好，治疗病人要用治疗。"}, {"text": "工厂升级了产量。", "explanation": "这里应该用〈增加〉。升级指使器物或系统变得更好，数量增长要用增加。"}, {"text": "妈妈给我升级了一杯热水。", "explanation": "这里应该用〈倒〉。升级用于使器物、系统等变得更好，给人倒水要用倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。升级：让东西变得更好、更厉害。"}, {"text": "盛极", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，盛极指发展到顶点。"}, {"text": "生肌", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，生肌指促进新组织长出。"}, {"text": "省际", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}], "explanations": {"升级": "正确答案。升级：让东西变得更好、更厉害。", "盛极": "shèng（第四声）与 shēng（第一声）声调不同，盛极指发展到顶点。", "生肌": "jī（第一声）与 jí（第二声）声调不同，生肌指促进新组织长出。", "省际": "shěng（第三声）与 shēng（第一声）声调不同，jì（第四声）与 jí（第二声）声调也不同，省际指各省之间。"}, "sentence_index": null, "correct_answer": "升级"}, "level_3": {"options": [{"text": "升级", "is_correct": true, "explanation": "正确答案。“工厂买了新机器，升级了生产线”表示让生产线变得更好。"}, {"text": "骑", "is_correct": false, "explanation": "语义：“骑”不能用于生产线，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：生产线不能“喝”，句子说不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”用于动植物，不能说“养生产线”。"}], "explanations": {"升级": "正确答案。“工厂买了新机器，升级了生产线”表示让生产线变得更好。", "骑": "语义：“骑”不能用于生产线，句意不通。", "喝": "语义：生产线不能“喝”，句子说不通。", "养": "搭配：“养”用于动植物，不能说“养生产线”。"}, "sentence_index": 6, "correct_answer": "升级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "志愿者升级了贫困学生。", "explanation": "这里应该用〈帮助〉。升级用于使物品或系统变得更好，帮助人要用帮助。"}, {"text": "学校升级了浪费。", "explanation": "这里应该用〈减少〉。升级指使器物或系统变得更好，数量或浪费的下降要用减少。"}, {"text": "同学们升级了邮票。", "explanation": "这里应该用〈收集〉。升级指使物品变得更好，收集物品要用收集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把旧手机的升级一下。", "corrected_sentence": "我想把旧手机升级一下。", "error_description": "多加“的”：“升级”是动词，不能被“的”修饰，写成“的升级”变成名词短语，与后面的“一下”不搭配。正确形式为“把旧手机升级一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把图书馆的电脑升级。", "corrected_sentence": "学校把图书馆的电脑升级了。", "error_description": "“把”字句缺少成分：“把”字句中动词后要带“了”或其他成分，写成“把图书馆的电脑升级”语气未完。正确形式为“学校把图书馆的电脑升级了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
