INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个地方的人直接做买卖，不找别人帮忙。", "primary_collocate": null, "pronunciation": "zhí jiē mào yì", "ipa": "ʈʂʅ˧˥ tɕjɛ˥ maʊ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "山里的农民和城里的商店做直接贸易。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不找中间人，只做直接贸易。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "直接贸易让农民多赚了一些钱。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个小镇一直有直接贸易。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司想和国外的茶农做直接贸易。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做直接贸易时，双方要先说好价格。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直接贸易不需要别人帮忙。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年轻时，和邻村人做过直接贸易。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的直接贸易越来越方便了。", "target_word": "直接贸易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板说，直接贸易比找中间人更便宜。", "target_word": "直接贸易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直接貿易", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两地的人不找中间人、直接买卖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接贸易", "is_correct": true, "explanation": "“做直接贸易”指两地的人不找中间人直接买卖，与句中的语境相符。"}, {"text": "山区", "is_correct": false, "explanation": "语义：“做山区”不成立，山区不是可以去做的买卖。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：“做寒假”没有意义，与买卖无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“做”不搭配“天气”，句意不通。"}], "explanations": {"直接贸易": "“做直接贸易”指两地的人不找中间人直接买卖，与句中的语境相符。", "山区": "语义：“做山区”不成立，山区不是可以去做的买卖。", "寒假": "语义：“做寒假”没有意义，与买卖无关。", "天气": "搭配：“做”不搭配“天气”，句意不通。"}, "sentence_index": 0, "correct_answer": "直接贸易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货经香港直接贸易到城里。", "explanation": "这里应该用〈转口贸易〉。直接贸易不找中间人，货物经香港转手应说转口贸易。"}, {"text": "两国通过第三国做直接贸易，货物要先运到第三国。", "explanation": "这里应该用〈间接贸易〉。直接贸易不经过别人，句中通过第三国转手，应说间接贸易。"}, {"text": "这两个小镇一直做直接贸易，中间要找人帮忙。", "explanation": "这里应该用〈间接贸易〉。直接贸易不找别人帮忙，句中说“中间要找人帮忙”，应说间接贸易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接贸易", "is_correct": true, "explanation": "“直接贸易不需要别人帮忙”符合定义，两地的人直接买卖无需中间人。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米不会“需要别人帮忙”，主语应是人或行为。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜不是能提出需求的主体，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“不需要别人帮忙”需要人或机构作主语，天空不能搭配这种表述。"}], "explanations": {"直接贸易": "“直接贸易不需要别人帮忙”符合定义，两地的人直接买卖无需中间人。", "大米": "语义：大米不会“需要别人帮忙”，主语应是人或行为。", "眼镜": "语义：眼镜不是能提出需求的主体，句意不通。", "天空": "搭配：“不需要别人帮忙”需要人或机构作主语，天空不能搭配这种表述。"}, "sentence_index": 6, "correct_answer": "直接贸易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈请朋友帮忙做直接贸易，从海外买了一件衣服。", "explanation": "这里应该用〈代购〉。代购是请人代为购买，直接贸易不找别人帮忙，句中“请朋友帮忙”应说代购。"}, {"text": "这家公司做直接贸易，货物都要先经过中间商转手。", "explanation": "这里应该用〈经销〉。经销是经销商进货再卖出，货物经中间商转手；直接贸易不找中间人，句中说经中间商转手，应说经销。"}, {"text": "我们做直接贸易，但是货物要经过三次中间环节。", "explanation": "这里应该用〈间接贸易〉。间接贸易要经过中间环节，直接贸易不找中间人，句中说要经过三次中间环节，应说间接贸易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个小镇的农民去年做了一只直接贸易。", "corrected_sentence": "这两个小镇的农民去年做了一笔直接贸易。", "error_description": "量词错误：「只」用于动物等，贸易应用「笔」，正确说法是「做了一笔直接贸易」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个小镇的直接贸易越来越方便过。", "corrected_sentence": "这两个小镇的直接贸易越来越方便了。", "error_description": "体标错误：表示变化的结果应用「了」，「越来越方便过」不成立，正确说法是「越来越方便了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
