INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21672, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要做成某件事，设法去做（多含尝试之意）。", "primary_collocate": null, "pronunciation": "shì tú", "ipa": "ʂɨ˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "小偷试图从后门逃走。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试图说服妈妈同意这件事。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生试图用新办法解决问题。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试图忘记那段不开心的事。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人试图打开别人的车门。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们试图找到丢失的小狗。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他试图解释，但是没有人听。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司试图降低价格留住客人。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟试图爬上高高的树。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她试图把话说清楚，可是太紧张了。", "target_word": "试图", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "想要做成某事并作出尝试，后面接动词短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试图", "is_correct": true, "explanation": "正确。“小偷试图从后门逃走”中，“试图”表示想做成并尝试逃走，符合句意。"}, {"text": "帮助", "is_correct": false, "explanation": "配价：“帮助”需要带被帮助的对象，句中没有，“帮助从后门逃走”不成立。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：小偷还没逃走，谈不上“后悔”，与句中正在设法逃走的意图不符。"}, {"text": "门口", "is_correct": false, "explanation": "词性：“门口”是名词，不能带动词短语“从后门逃走”，句子不成立。"}], "explanations": {"试图": "正确。“小偷试图从后门逃走”中，“试图”表示想做成并尝试逃走，符合句意。", "帮助": "配价：“帮助”需要带被帮助的对象，句中没有，“帮助从后门逃走”不成立。", "后悔": "语义：小偷还没逃走，谈不上“后悔”，与句中正在设法逃走的意图不符。", "门口": "词性：“门口”是名词，不能带动词短语“从后门逃走”，句子不成立。"}, "sentence_index": 0, "correct_answer": "试图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我们试图下雨。", "explanation": "这里应该用〈希望〉。试图指人有意识地去做事，不能用于无法控制的天气。"}, {"text": "这块石头试图滚下山。", "explanation": "这里应该用〈滚〉。试图需要有意图的主体，石头没有意图，不能用“试图”描述它。"}, {"text": "太阳试图从西边升起。", "explanation": "这里应该用〈升起〉。试图指有意去做，太阳没有意图，不能用“试图”描述它的运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试图", "is_correct": true, "explanation": "正确。“他试图解释，但是没有人听”中，“试图”表示尝试解释，符合句意。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再尝试，与“但是没有人听”所说的已经开口解释相矛盾。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”需要带被原谅的对象，句中没有，“原谅解释”不成立。"}, {"text": "打扰", "is_correct": false, "explanation": "配价：“打扰”需要带被打扰的对象，句中没有，“打扰解释”不成立。"}], "explanations": {"试图": "正确。“他试图解释，但是没有人听”中，“试图”表示尝试解释，符合句意。", "放弃": "语义：“放弃”表示不再尝试，与“但是没有人听”所说的已经开口解释相矛盾。", "原谅": "配价：“原谅”需要带被原谅的对象，句中没有，“原谅解释”不成立。", "打扰": "配价：“打扰”需要带被打扰的对象，句中没有，“打扰解释”不成立。"}, "sentence_index": 6, "correct_answer": "试图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我试图突然摔倒。", "explanation": "这里应该用〈突然〉或〈不由自主〉。试图表示有意去做，摔倒是不由自主的动作，不能用“试图”。"}, {"text": "他不小心试图摔碎了杯子。", "explanation": "试图表示有意去做，与“不小心”的意思矛盾，两者不能搭配。"}, {"text": "我试图每个月都生病一次。", "explanation": "这里应该用〈经常〉。试图指有意去做，生病不能有意为之，不能用“试图”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他试图了找出问题的原因。", "corrected_sentence": "他试图找出问题的原因。", "error_description": "“了”不能直接放在“试图”后面：“试图”表示尚未实现的意图，不能与表示完成的“了”连用，这里应去掉“了”，说“试图找出问题的原因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他试图的说服老板提高工资。", "corrected_sentence": "他试图说服老板提高工资。", "error_description": "错误：“试图”后多加了结构助词“的”。“试图”是动词，后面直接接动词短语，不能加“的”。正确：“他试图说服老板提高工资”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "对抗", "is_correct": true, "explanation": "反义：“合作”指共同做事，“对抗”指相互抵抗，二者在此义上相对。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清洁，与“合作”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指悠闲地走路，与“合作”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”指进食，与“合作”没有反义关系。"}], "correct_answer": "对抗", "explanations": {"对抗": "反义：“合作”指共同做事，“对抗”指相互抵抗，二者在此义上相对。", "打扫": "无关：“打扫”指清洁，与“合作”没有反义关系。", "散步": "无关：“散步”指悠闲地走路，与“合作”没有反义关系。", "吃饭": "无关：“吃饭”指进食，与“合作”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "对抗", "is_correct": true, "explanation": "反义：“合作”指共同做事，“对抗”指相互抵抗，二者在此义上相对。"}, {"text": "洗澡", "is_correct": false, "explanation": "无关：“洗澡”指清洁身体，与“合作”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”指发出乐音，与“合作”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "无关：“写字”指书写文字，与“合作”没有反义关系。"}], "correct_answer": "对抗", "explanations": {"对抗": "反义：“合作”指共同做事，“对抗”指相互抵抗，二者在此义上相对。", "洗澡": "无关：“洗澡”指清洁身体，与“合作”没有反义关系。", "唱歌": "无关：“唱歌”指发出乐音，与“合作”没有反义关系。", "写字": "无关：“写字”指书写文字，与“合作”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或很多人一起做一件事。", "primary_collocate": null, "pronunciation": "hé zuò", "ipa": "xɤ˧˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "我们两家公司合作了三年。", "target_word": "合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和我合作得很好。", "target_word": "合作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家一起合作，工作做得快。", "target_word": "合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你和我们合作。", "target_word": "合作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个国家想在科学上合作。", "target_word": "合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们合作做了一张画。", "target_word": "合作", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想和他合作。", "target_word": "合作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两个人合作比一个人快。", "target_word": "合作", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们合作过很多次。", "target_word": "合作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们分组合作。", "target_word": "合作", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "合作了", "label": "体标"}, {"form": "合作过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，指几个人或单位为了同一个目的一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合作", "is_correct": true, "explanation": "正确。“合作”指两家公司一起做事，与“三年”搭配，符合句意。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只用于生命体，公司不能出生。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：公司不会逃跑，这与句子的意思相冲突。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“结婚”限于人之间，不能用于两家公司。"}], "explanations": {"合作": "正确。“合作”指两家公司一起做事，与“三年”搭配，符合句意。", "出生": "语义：“出生”只用于生命体，公司不能出生。", "逃跑": "语义：公司不会逃跑，这与句子的意思相冲突。", "结婚": "搭配：“结婚”限于人之间，不能用于两家公司。"}, "sentence_index": 0, "correct_answer": "合作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人合作完成了这份报告。", "explanation": "语义：“合作”要求两人或多人一起做事，“一个人”不能合作，这里应该用〈独自〉。"}, {"text": "他这次考试合作了。", "explanation": "这里应该用〈合格〉。“合作”指共同做事，考试通过、达到标准要说〈合格〉。"}, {"text": "这件衣服很合作，穿着不舒服。", "explanation": "这里应该用〈合适〉。“合作”形容人的配合态度，衣服的大小、款式是否适宜要说〈合适〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合作", "is_correct": true, "explanation": "正确。“不想和他合作”表示不愿与他一起做事，符合句意。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能和某人一起进行。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”是植物的变化，不能和他一起做。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”是物态变化，不能和他进行。"}], "explanations": {"合作": "正确。“不想和他合作”表示不愿与他一起做事，符合句意。", "下雨": "语义：“下雨”是天气现象，不能和某人一起进行。", "发芽": "语义：“发芽”是植物的变化，不能和他一起做。", "结冰": "语义：“结冰”是物态变化，不能和他进行。"}, "sentence_index": 6, "correct_answer": "合作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把两块布合作在一起。", "explanation": "语义：“合作”指人共同做事，布不能合作，这里应该用〈拼合〉。"}, {"text": "这两扇门合作得严丝合缝。", "explanation": "语义：这里应该用〈合拢〉。门不能合作，只能说门“合拢”。"}, {"text": "他一个人合作搬完了所有的书。", "explanation": "语义：“合作”要求两人或多人一起做事，“一个人”不能合作，这里应该用〈独自〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和同事合作过完成了这份报告。", "corrected_sentence": "我和同事合作完成了这份报告。", "error_description": "错误：“过”表示经历，不能放在“合作”后、紧接另一个动词“完成”之前。应说“我和同事合作完成了这份报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她和我们合作很得愉快。", "corrected_sentence": "她和我们合作得很愉快。", "error_description": "错误：“得”应紧跟在动词“合作”后面，再接“很愉快”作补语。“合作很得愉快”语序错误，应说“她和我们合作得很愉快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
