INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产者是制造东西的人或公司。", "primary_collocate": null, "pronunciation": "shēng chǎn zhě", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家公司是有名的玩具生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要直接向生产者买东西。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者把新的电视机送到了店里。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位生产者做的鞋子又好又便宜。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生产者不会用坏材料。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的生产者在上面写了名字。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店老板想找一位可靠的生产者。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产者每天要做很多面包。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国是世界上最大的茶叶生产者之一。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从生产者那里买了很多布。", "target_word": "生产者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "生产者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "生产者：制造东西的人或公司，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”指制造东西的公司，句中说的是这家公司制造玩具，句意相符。"}, {"text": "消费者", "is_correct": false, "explanation": "语义：“消费者”指购买东西的人，与“制造玩具的公司”不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：公司不能是病人，句意不通。"}, {"text": "翻译员", "is_correct": false, "explanation": "搭配：“翻译员”不能用来指称玩具的制造方，这一搭配不成立。"}], "explanations": {"生产者": "“生产者”指制造东西的公司，句中说的是这家公司制造玩具，句意相符。", "消费者": "语义：“消费者”指购买东西的人，与“制造玩具的公司”不符。", "病人": "语义：公司不能是病人，句意不通。", "翻译员": "搭配：“翻译员”不能用来指称玩具的制造方，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台新机器是这家工厂的生产者，每天能做很多双鞋。", "explanation": "这里应该用〈生产设备〉。生产者是制造东西的人或公司，机器应说〈生产设备〉。"}, {"text": "这家商店是这双鞋的生产者，每天都在卖。", "explanation": "这里应该用〈销售者〉。生产者是制造东西的人或公司，只卖东西的商店应说〈销售者〉。"}, {"text": "这个创意是这双鞋的生产者。", "explanation": "这里应该用〈灵感来源〉。生产者是制造东西的人或公司，创意不是制造者，应说〈灵感来源〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产者", "is_correct": true, "explanation": "“生产者”指提供货物的制造方，与小店老板找货源的语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“可靠”多修饰能提供货物或服务的人，“乘客”与之不搭配。"}, {"text": "邮票", "is_correct": false, "explanation": "搭配：“位”用于人，不能说“一位邮票”，句意也不通。"}, {"text": "司令", "is_correct": false, "explanation": "语义：司令指军队的指挥员，与小店找货无关。"}], "explanations": {"生产者": "“生产者”指提供货物的制造方，与小店老板找货源的语境相符。", "乘客": "搭配：“可靠”多修饰能提供货物或服务的人，“乘客”与之不搭配。", "邮票": "搭配：“位”用于人，不能说“一位邮票”，句意也不通。", "司令": "语义：司令指军队的指挥员，与小店找货无关。"}, "sentence_index": 6, "correct_answer": "生产者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家银行是这家布厂的生产者。", "explanation": "这里应该用〈投资者〉。生产者是制造东西的人或公司，银行只出资，不制造布料，应说〈投资者〉。"}, {"text": "他是这些布的生产者，每天从工厂进货再转卖。", "explanation": "这里应该用〈批发商〉。生产者是制造东西的人或公司，从工厂进货再转卖的人应说〈批发商〉。"}, {"text": "这批布是这家工厂的生产者。", "explanation": "这里应该用〈产品〉。生产者是制造东西的人或公司，布是产品，不是制造者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两只生产者都在城西建了新厂。", "corrected_sentence": "那两家生产者都在城西建了新厂。", "error_description": "“生产者”指公司时量词应用“家”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家纺织厂是本市最大的一只布料生产者。", "corrected_sentence": "这家纺织厂是本市最大的一家布料生产者。", "error_description": "量词错误：“生产者”指公司时应用“家”，“只”不能用于公司，应改为“一家布料生产者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示比以前更多或更厉害。", "primary_collocate": null, "pronunciation": "yù fā", "ipa": "y˥˩ fa˥", "syllable_count": 2, "sentences": [{"text": "他生病以后，脸色愈发白了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一关，房间里愈发黑了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间越久，我愈发想念朋友。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风越来越大，天气愈发冷了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情变得复杂，他愈发着急。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说到这里，老人愈发伤心。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读的书越多，愈发觉得自己知道得少。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山越往上走，空气愈发冷。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸了他，他愈发努力。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，愈发懂事了。", "target_word": "愈发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示比以前更多或更厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d8d8829-6187-4938-b5a2-6292d29cf1be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发表示比以前程度更厉害，与“生病以后”的变化相合。"}, {"text": "毫不", "is_correct": false, "explanation": "搭配：毫不用于否定，不能修饰「白了」这种状态变化。"}, {"text": "从来", "is_correct": false, "explanation": "语义：从来表示一向如此，与“生病以后”带来的变化不符。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：白白表示徒然，不能修饰“白了”这类状态变化。"}], "explanations": {"愈发": "正确：愈发表示比以前程度更厉害，与“生病以后”的变化相合。", "毫不": "搭配：毫不用于否定，不能修饰「白了」这种状态变化。", "从来": "语义：从来表示一向如此，与“生病以后”带来的变化不符。", "白白": "搭配：白白表示徒然，不能修饰“白了”这类状态变化。"}, "sentence_index": 0, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天愈发买了一本词典。", "explanation": "这里应该用〈终于〉。愈发表示程度逐渐加深，不能修饰一次性的购买动作。"}, {"text": "他愈发是我的弟弟。", "explanation": "这里应该用〈确实〉。愈发表示程度加深，不能修饰判断，强调判断要用确实。"}, {"text": "桌子上愈发放着一本书。", "explanation": "这里应该用〈仍〉。愈发表示程度加深，不表示状态持续，表示状态一直保持要用仍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愈发", "is_correct": true, "explanation": "正确：愈发表示程度加深，与“书越多”的递进关系相合。"}, {"text": "毫不", "is_correct": false, "explanation": "语义：毫不表示完全否定，与「书越多」带来的程度加深相矛盾。"}, {"text": "从不", "is_correct": false, "explanation": "语义：从不与“书越多”的递进关系相反，不合句意。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「越…，…」递进句式不用「非常」，且「非常觉得」不自然。"}], "explanations": {"愈发": "正确：愈发表示程度加深，与“书越多”的递进关系相合。", "毫不": "语义：毫不表示完全否定，与「书越多」带来的程度加深相矛盾。", "从不": "语义：从不与“书越多”的递进关系相反，不合句意。", "非常": "搭配：「越…，…」递进句式不用「非常」，且「非常觉得」不自然。"}, "sentence_index": 6, "correct_answer": "愈发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色愈发一直没变。", "explanation": "这里应该用〈始终〉。愈发表示程度逐步加深，与“没变”的含义相矛盾，表示一直不变要用始终。"}, {"text": "妈妈把书愈发收好了。", "explanation": "这里应该用〈全部〉。愈发表示程度逐步加深，不能用于表示全部完成的把字句，表示全部完成要用全部。"}, {"text": "孩子刚起床就愈发去玩了。", "explanation": "这里应该用〈马上〉。愈发表示程度逐步加深，不能修饰刚起床就去玩这样的瞬间动作，表示立即行动要用马上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事越闹越大，妈妈很愈发担心了。", "corrected_sentence": "这件事越闹越大，妈妈愈发担心了。", "error_description": "错误形式：很愈发担心；正确形式：愈发担心。“愈发”已表示程度加深，不能再与“很”并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他愈发得喜欢这本书了。", "corrected_sentence": "他愈发喜欢这本书了。", "error_description": "错误形式：愈发得喜欢；正确形式：愈发喜欢。“愈发”是状语，后面不能加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f25b6bce-9e2e-4255-bc73-14e924f0b6f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "“降低”指使数量或水平变低，与“提高”构成反义，符合“提高工作效率”的对立面。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指使事物维持原样，不与“提高”构成反义。"}, {"text": "努力", "is_correct": false, "explanation": "“努力”指尽力去做某事，与“提高”不是反义关系。"}, {"text": "维持", "is_correct": false, "explanation": "“维持”指保持某种状态不变，与“提高”不构成反义。"}], "correct_answer": "降低", "explanations": {"降低": "“降低”指使数量或水平变低，与“提高”构成反义，符合“提高工作效率”的对立面。", "保持": "“保持”指使事物维持原样，不与“提高”构成反义。", "努力": "“努力”指尽力去做某事，与“提高”不是反义关系。", "维持": "“维持”指保持某种状态不变，与“提高”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "“降低”指使水平变低，与“提高”构成反义，符合“生活水平提高”的对立面。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做完某件事，与“提高”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“提高”不是反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见，与“提高”不构成反义。"}], "correct_answer": "降低", "explanations": {"降低": "“降低”指使水平变低，与“提高”构成反义，符合“生活水平提高”的对立面。", "完成": "“完成”指做完某件事，与“提高”不构成反义。", "参加": "“参加”指加入某项活动，与“提高”不是反义关系。", "讨论": "“讨论”指交换意见，与“提高”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事物变得比原来更好。", "primary_collocate": null, "pronunciation": "tí gāo", "ipa": "tʰi˧˥ kau˥", "syllable_count": 2, "sentences": [{"text": "我想提高我的汉语水平。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多练习可以提高口语。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂提高了产品的质量。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方法能提高工作效率。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师希望大家提高学习成绩。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司提高了工人的工资。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看书能提高写作能力。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了提高速度,他换了新电脑。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直努力提高自己的英语。", "target_word": "提高", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些年，这个城市的生活水平提高了很多。", "target_word": "提高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提高了", "label": "体标"}, {"form": "提高过", "label": "体标"}, {"form": "提高到", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "提高：使水平、质量、能力等变得比原来更高更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“汉语水平”作宾语。"}, {"text": "提高", "is_correct": true, "explanation": "“提高”表示使水平变得更高，与句中“想……汉语水平”的意思相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与“水平”搭配，不能说“唱汉语水平”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“汉语水平”无关，句子说不通。"}], "explanations": {"散步": "配价：“散步”是不及物动词，不能带“汉语水平”作宾语。", "提高": "“提高”表示使水平变得更高，与句中“想……汉语水平”的意思相合。", "唱": "搭配：“唱”不与“水平”搭配，不能说“唱汉语水平”。", "吃": "语义：“吃”指进食，与“汉语水平”无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "提高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提高了两个小时才到家。", "explanation": "这里应该用〈花〉。“提高”用于水平、质量，不用于时间的消耗，说花费时间要用“花”。"}, {"text": "他一晚上提高了三本书。", "explanation": "这里应该用〈读〉。“提高”用于水平、质量，不指阅读，读书要用“读”。"}, {"text": "这次改革提高了学校的校长。", "explanation": "这里应该用〈提拔〉。“提高”用于水平、质量等，不用于指人的职务晋升，职务上升应该用“提拔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降低", "is_correct": false, "explanation": "语义：“降低”指使变低，与“看书能……写作能力”的积极作用相反，句子说不通。"}, {"text": "提高", "is_correct": true, "explanation": "“提高”表示使能力变得更强，与“看书能”的积极作用相合，符合句意。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不能与“写作能力”搭配，不能说“打写作能力”。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与“写作能力”无关，句子说不通。"}], "explanations": {"降低": "语义：“降低”指使变低，与“看书能……写作能力”的积极作用相反，句子说不通。", "提高": "“提高”表示使能力变得更强，与“看书能”的积极作用相合，符合句意。", "打": "搭配：“打”不能与“写作能力”搭配，不能说“打写作能力”。", "喝": "语义：“喝”指饮用，与“写作能力”无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "提高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在超市提高了一百块钱。", "explanation": "这里应该用〈花〉。“提高”用于水平、质量等，不表示用掉钱，用钱买东西要说“花”。"}, {"text": "妈妈在商店提高了一件新衣服。", "explanation": "这里应该用〈买〉。“提高”用于水平、质量等，不表示购物，在商店付钱拿东西要说“买”。"}, {"text": "我们提高了一个下午的路程。", "explanation": "这里应该用〈走〉。“提高”用于水平、质量，不用于距离，走一段路应该用“走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂把产品的质量提高。", "corrected_sentence": "这家工厂把产品的质量提高了。", "error_description": "错误：“把”字句中动词后缺少“了”，句子不完整。正确形式是“把产品的质量提高了”，动态助词“了”应放在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工资提高在了五千元。", "corrected_sentence": "工资提高到了五千元。", "error_description": "错误：结果补语用错，“提高在”不成立。表示提升到某个数额要用“提高到”，正确形式是“工资提高到了五千元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
