INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买东西的人和卖东西的人商量价格。", "primary_collocate": null, "pronunciation": "yì jià", "ipa": "i˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "我想和老板议价，看能不能便宜点。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买二手车时，你可以和卖家议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在市场里议价了很久。", "target_word": "议价", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店不能议价，价格都写在牌子上。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈擅长议价，每次都买得便宜。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子前，我们先找中介议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客想议价，可是老板不同意。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别急着买，先跟他议价吧。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和摊主议价，最后只花了五十块。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国旅游时，买纪念品常常要议价。", "target_word": "议价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "议价了", "label": "体标（了）"}, {"form": "议价过", "label": "体标（过）"}, {"form": "議價", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖双方商量价格（动词用法）：和老板议价、跟卖家议价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddebd6cf-17ed-4b0a-b28c-0c938fbac07a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议价", "is_correct": true, "explanation": "正确：议价，指买卖双方商量价格。"}, {"text": "衣架", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。"}, {"text": "一家", "is_correct": false, "explanation": "一家实际读 yì jiā（变调），jiā（第一声）与 jià（第四声）声调不同，意思是一个家庭。"}, {"text": "意见", "is_correct": false, "explanation": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}], "explanations": {"议价": "正确：议价，指买卖双方商量价格。", "衣架": "yī（第一声）与 yì（第四声）声调不同，意思是衣服架子。", "一家": "一家实际读 yì jiā（变调），jiā（第一声）与 jià（第四声）声调不同，意思是一个家庭。", "意见": "jiàn 与 jià 韵尾不同（多一个 n），意思是看法。"}, "sentence_index": null, "correct_answer": "议价"}, "level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“和老板议价”表示与老板商量价格，与“看能不能便宜点”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：与老板结婚和“看能不能便宜点”毫不相干，句意不通。"}, {"text": "辞职", "is_correct": false, "explanation": "配价：“辞职”不能与“和老板”搭配表示商量价格，后半句语义也不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：和老板散步不能使价格变便宜，句意不通。"}], "explanations": {"议价": "“和老板议价”表示与老板商量价格，与“看能不能便宜点”的语境相符。", "结婚": "语义：与老板结婚和“看能不能便宜点”毫不相干，句意不通。", "辞职": "配价：“辞职”不能与“和老板”搭配表示商量价格，后半句语义也不通。", "散步": "语义：和老板散步不能使价格变便宜，句意不通。"}, "sentence_index": 0, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商场决定议价促销，全部商品都参加。", "explanation": "这里应该用〈降价〉。商场统一促销应说降价，议价是买卖双方的协商。"}, {"text": "晚上我们在家议价了一场足球比赛。", "explanation": "这里应该用〈看〉。议价指买卖双方商量价格，看比赛不能说议价。"}, {"text": "他们在工厂里议价，生产了很多零件。", "explanation": "这里应该用〈生产〉。议价指买卖双方商量价格，制造零件应说生产，不能说议价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议价", "is_correct": true, "explanation": "“顾客想议价，可是老板不同意”中，议价指顾客想与老板商量价格，语境通顺。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“顾客想失眠”不成立，与语境不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“顾客想出生”不合逻辑，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“想下雨”不能用顾客的意愿来表述，“下雨”不带这种主语。"}], "explanations": {"议价": "“顾客想议价，可是老板不同意”中，议价指顾客想与老板商量价格，语境通顺。", "失眠": "语义：“顾客想失眠”不成立，与语境不符。", "出生": "语义：“顾客想出生”不合逻辑，句意不通。", "下雨": "搭配：“想下雨”不能用顾客的意愿来表述，“下雨”不带这种主语。"}, "sentence_index": 6, "correct_answer": "议价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商品都要议价，合格后才能出售。", "explanation": "这里应该用〈质检〉。议价指买卖双方商量价格，检验商品是否合格应说质检，不能说议价。"}, {"text": "超市天天议价，价格很便宜。", "explanation": "这里应该用〈打折〉。超市统一打折，顾客不需要和店员商量，不能说议价。"}, {"text": "卖家议价一千块，我们还价到八百。", "explanation": "这里应该用〈开价〉。开价是卖家先报出价格，议价是双方商量的过程，不能说“议价一千块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想老板议价，看看能不能给我打个折。", "corrected_sentence": "我想跟老板议价，看看能不能给我打个折。", "error_description": "介词缺失：「议价」要用「跟」引出对方，应说「跟老板议价」，不能直接说「老板议价」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈常常在摊主议价。", "corrected_sentence": "我妈妈常常跟摊主议价。", "error_description": "介词错误：引出议价对象应用「跟」，「在」不能引出议价的对象，正确说法是「跟摊主议价」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a009061-a336-437b-b63e-20b566096da3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "延长", "is_correct": true, "explanation": "“延长”与“缩短”是反义词：缩短指使长度、时间变短，延长指使其变长。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指探讨、钻研，与“缩短”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把物体从一处运到另一处，与“缩短”没有反义关系。"}, {"text": "训练", "is_correct": false, "explanation": "“训练”指通过反复练习提高能力，与“缩短”没有反义关系。"}], "correct_answer": "延长", "explanations": {"延长": "“延长”与“缩短”是反义词：缩短指使长度、时间变短，延长指使其变长。", "研究": "“研究”指探讨、钻研，与“缩短”没有反义关系。", "搬运": "“搬运”指把物体从一处运到另一处，与“缩短”没有反义关系。", "训练": "“训练”指通过反复练习提高能力，与“缩短”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "延长", "is_correct": true, "explanation": "“延长”与“缩短”是反义词：缩短指使长度、时间变短，延长指使其变长。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指使杂乱的东西有序，与“缩短”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指交换意见、共同研究，与“缩短”没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指使损坏的东西恢复正常，与“缩短”没有反义关系。"}], "correct_answer": "延长", "explanations": {"延长": "“延长”与“缩短”是反义词：缩短指使长度、时间变短，延长指使其变长。", "整理": "“整理”指使杂乱的东西有序，与“缩短”没有反义关系。", "讨论": "“讨论”指交换意见、共同研究，与“缩短”没有反义关系。", "修理": "“修理”指使损坏的东西恢复正常，与“缩短”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使时间、距离或长度变短。", "primary_collocate": null, "pronunciation": "suō duǎn", "ipa": "swo˥ twan˨˩˦", "syllable_count": 2, "sentences": [{"text": "新路缩短了回家的时间。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐高铁可以缩短路上的时间。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把会议缩短到了半小时。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裙子太长，请帮我缩短一点。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁缩短了两个城市的距离。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，想缩短和第一名的差距。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校缩短了夏天的假期。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说要缩短看电脑的时间。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新桥缩短了过河的路程。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这根绳子缩短十厘米。", "target_word": "缩短", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缩短了", "label": "体标"}, {"form": "缩短过", "label": "体标"}, {"form": "縮短", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使时间、距离、长度变短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缩短", "is_correct": true, "explanation": "“缩短”指使时间变短，与“回家的时间”搭配，符合句意：新路让回家的时间变少。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”搭配纪录、沉默、局面等，不能与“时间”搭配，“新路打破了回家的时间”不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清除灰尘、垃圾，不能施用于时间，句子语义荒谬。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，无法施用于“时间”，句子语义荒谬。"}], "explanations": {"缩短": "“缩短”指使时间变短，与“回家的时间”搭配，符合句意：新路让回家的时间变少。", "打破": "搭配：“打破”搭配纪录、沉默、局面等，不能与“时间”搭配，“新路打破了回家的时间”不通。", "打扫": "语义：“打扫”指清除灰尘、垃圾，不能施用于时间，句子语义荒谬。", "点燃": "语义：“点燃”指使物体燃烧，无法施用于“时间”，句子语义荒谬。"}, "sentence_index": 0, "correct_answer": "缩短"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司决定缩短人手。", "explanation": "这里应该用〈缩减〉。缩短用于长度、时间、距离，人员、人手等数量的减少要用〈缩减〉。"}, {"text": "这个城市的范围缩短了。", "explanation": "这里应该用〈缩小〉。缩短用于长度、时间、距离，范围、面积的变小要用缩小。"}, {"text": "这次考试的难度缩短了。", "explanation": "这里应该用〈降低〉。缩短用于长度、时间、距离，难度、水平的下降要用降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩短", "is_correct": true, "explanation": "“缩短”指使时间变短，与“夏天的假期”搭配，表示学校减少了假期的时长。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物体的外表，与“假期”不相容，句子语义荒谬。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指把液体烧开，不能施用于“假期”，句子语义荒谬。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪去多余的部分，不能施用于“假期”，句子语义荒谬。"}], "explanations": {"缩短": "“缩短”指使时间变短，与“夏天的假期”搭配，表示学校减少了假期的时长。", "装饰": "语义：“装饰”指美化物体的外表，与“假期”不相容，句子语义荒谬。", "煮沸": "语义：“煮沸”指把液体烧开，不能施用于“假期”，句子语义荒谬。", "修剪": "语义：“修剪”指剪去多余的部分，不能施用于“假期”，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "缩短"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府缩短了预算。", "explanation": "这里应该用〈削减〉。缩短用于长度、时间、距离，预算、开支的减少要用削减。"}, {"text": "工厂缩短了开支。", "explanation": "这里应该用〈压缩〉。缩短用于长度、时间，开支的减少要用压缩，“压缩”强调用力使其变小。"}, {"text": "我们要缩短用水。", "explanation": "这里应该用〈节约〉。缩短用于长度、时间、距离，用水量的减少要用节约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把论文缩短得三页。", "corrected_sentence": "他把论文缩短到三页。", "error_description": "补语错误：表示结果终点要用“缩短到”，不能用“得”。应为“把论文缩短到三页”，不能说“缩短得三页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根管子缩短在了一米。", "corrected_sentence": "这根管子缩短到了一米。", "error_description": "介词错误：表示结果终点要用“缩短到”，不能用“在”，应为“缩短到了一米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
