INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21694, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "你就要遇到一件事了。", "primary_collocate": null, "pronunciation": "miàn lín", "ipa": "mjɛn˥˩ lin˧˥", "syllable_count": 2, "sentences": [{"text": "公司现在面临很大的问题。", "target_word": "面临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们面临一个新的选择。", "target_word": "面临", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明年她就要面临考试了。", "target_word": "面临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市面临缺水的问题。", "target_word": "面临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都会面临困难。", "target_word": "面临", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他面临着一个大决定。", "target_word": "面临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，你要面临工作的问题。", "target_word": "面临", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子面临着洪水。", "target_word": "面临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从没面临过这么大的危险。", "target_word": "面临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们面临的最大问题是孤独。", "target_word": "面临", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "面临着", "label": "体标"}, {"form": "面临过", "label": "体标"}], "register": "书面", "sense_fingerprint": "动词，指问题、困难或选择等摆在面前，将要遇到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21694, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面临", "is_correct": true, "explanation": "正确。“面临”表示将要遇到问题，与“很大的问题”搭配，符合句意。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”的对象应是人，不能安慰问题。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：“歌唱”与“问题”毫无关系，句子不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”不能以“问题”作宾语。"}], "explanations": {"面临": "正确。“面临”表示将要遇到问题，与“很大的问题”搭配，符合句意。", "安慰": "语义：“安慰”的对象应是人，不能安慰问题。", "歌唱": "语义：“歌唱”与“问题”毫无关系，句子不通。", "游泳": "搭配：“游泳”不能以“问题”作宾语。"}, "sentence_index": 0, "correct_answer": "面临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上面临了一位老同学。", "explanation": "这里应该用〈遇到〉。“面临”接的是问题、困难或选择，不接人。"}, {"text": "他面临着一份生日礼物。", "explanation": "这里应该用〈收到〉。“面临”指将要应对问题、困难或选择，收到礼物要说〈收到〉。"}, {"text": "这件事已经面临过去了。", "explanation": "这里应该用〈结束〉。“面临”指将要遇到问题、困难或选择，已经完结的事要说〈结束〉，不能用“面临”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面临", "is_correct": true, "explanation": "正确。“面临”表示将要遇到工作的问题，与句意相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”只用于生命体，不能与“问题”搭配。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”不能以“工作的问题”作宾语。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：“呼吸”是生理动作，与工作问题无关。"}], "explanations": {"面临": "正确。“面临”表示将要遇到工作的问题，与句意相符。", "出生": "语义：“出生”只用于生命体，不能与“问题”搭配。", "散步": "搭配：“散步”不能以“工作的问题”作宾语。", "呼吸": "语义：“呼吸”是生理动作，与工作问题无关。"}, "sentence_index": 6, "correct_answer": "面临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们面临很多好处，非常开心。", "explanation": "语义：“面临”接的是需要应对的问题、困难或选择，“好处”不能用“面临”，这里应该用〈获得〉。"}, {"text": "他面临着一双新鞋。", "explanation": "语义：这里应该用〈穿〉。“面临”接的是需要应对的问题、困难或选择，鞋子要说〈穿〉。"}, {"text": "这个周末他面临一场精彩的电影。", "explanation": "语义：“面临”接问题、困难或选择，电影不能用“面临”，这里应该用〈看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司被面临着很大的竞争。", "corrected_sentence": "公司面临着很大的竞争。", "error_description": "错误：“面临”是及物动词，不能加“被”构成被动句。应去掉“被”，说“公司面临着很大的竞争”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前从没面临了这样的困难。", "corrected_sentence": "我们以前从没面临过这样的困难。", "error_description": "错误：“从没”表示没有过某种经历，后面的“面临”要用“过”，不能用“了”。应说“我们以前从没面临过这样的困难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
