INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21696, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个地方或整个地球长时间的气温、降水等气候状况发生改变，就是气候变化。", "primary_collocate": null, "pronunciation": "qì hòu biàn huà", "ipa": "tɕʰi˥˩ xou˥˩ pjɛn˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "气候变化让夏天越来越热。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家正在研究气候变化。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变化会影响农民种地。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为气候变化，这里的雨越来越少。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说，气候变化很大，冬天不冷了。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "气候变化使海边的城市有危险。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该少开车，一起面对气候变化。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年的气候变化，让很多动物离开了家。", "target_word": "气候变化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里常说气候变化，可是我不太懂。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校今天有一节关于气候变化的课。", "target_word": "气候变化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "全球气候变化", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方或整个地球长时间的冷热、雨量等天气情况发生改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气候变化", "is_correct": true, "explanation": "正确。“气候变化”指气候长期的变化，可以作主语，说明夏天越来越热的原因。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，与气温无关，句子不通。"}, {"text": "海浪", "is_correct": false, "explanation": "搭配：“海浪”与“让夏天越来越热”不搭，海浪不会使气温升高。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是制冷的电器，不会让夏天变热。"}], "explanations": {"气候变化": "正确。“气候变化”指气候长期的变化，可以作主语，说明夏天越来越热的原因。", "书包": "语义：书包是装书的袋子，与气温无关，句子不通。", "海浪": "搭配：“海浪”与“让夏天越来越热”不搭，海浪不会使气温升高。", "冰箱": "语义：“冰箱”是制冷的电器，不会让夏天变热。"}, "sentence_index": 0, "correct_answer": "气候变化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个气候变化很重，我背不动。", "explanation": "这里应该用〈书包〉。“很重、背不动”说的是有重量的东西，“气候变化”不能用来形容重量，要用〈书包〉。"}, {"text": "今天的气候变化很好，可以出去玩。", "explanation": "这里应该用〈天气〉。“气候变化”是长期的变化过程，说某一天好不好要用天气。"}, {"text": "这里的气候变化很低。", "explanation": "这里应该用〈气温〉。说温度的高低用气温，“气候变化”不能用“很低”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气候变化", "is_correct": true, "explanation": "正确。“面对”的宾语是问题或挑战，“气候变化”符合句子语境。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“面对”的宾语应是问题或困难，“饺子”不能作宾语。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”与“少开车”“一起面对”的语境无关，句子意思不通。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“面对”不能带“地毯”作宾语，句子不通。"}], "explanations": {"气候变化": "正确。“面对”的宾语是问题或挑战，“气候变化”符合句子语境。", "饺子": "搭配：“面对”的宾语应是问题或困难，“饺子”不能作宾语。", "闹钟": "语义：“闹钟”与“少开车”“一起面对”的语境无关，句子意思不通。", "地毯": "搭配：“面对”不能带“地毯”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "气候变化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个季节的气候变化很热，大家都不想出门。", "explanation": "这里应该用〈天气〉。“气候变化”指长期的变化过程，不能用来形容某段时间的冷热。"}, {"text": "妈妈做的气候变化很好吃。", "explanation": "这里应该用〈饭菜〉。“好吃”说的是食物，“气候变化”不能用来形容味道。"}, {"text": "他的气候变化很高。", "explanation": "这里应该用〈身高〉。说人的高矮要用身高，“气候变化”不能用“很高”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我担心这只气候变化影响农作物。", "corrected_sentence": "我担心这种气候变化影响农作物。", "error_description": "错误：量词「只」用于动物或成对物体中的一个，不能用于抽象的“气候变化”。正确：应为“这种气候变化”，量词「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该一起面对一块气候变化。", "corrected_sentence": "我们应该一起面对气候变化。", "error_description": "错误：量词「块」用于块状的东西，不能用于抽象的“气候变化”。正确：去掉量词，应为“我们应该一起面对气候变化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
