INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21698, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情发生或产生某种结果。", "primary_collocate": null, "pronunciation": "dǎo zhì", "ipa": "tɑʊ˨˩˦ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "大雨导致路上堵车。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡得太少会导致头疼。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错误导致了比赛失败。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是什么导致了这次事故？", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多糖可能导致牙疼。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雪导致学校今天放假了。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小小的错误，导致了大问题。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好导致飞机晚点了。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩手机太久导致他的眼睛很累。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏习惯导致他常常迟到。", "target_word": "导致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "导致了", "label": "体标"}, {"form": "導致", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某个原因引起并造成某种（多为不好的）结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ebcdd33-4c2b-4870-aa27-7ac3753dba86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21698, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导致", "is_correct": true, "explanation": "正确：“导致”表示引起某种结果，与“大雨……堵车”的因果相符。"}, {"text": "防止", "is_correct": false, "explanation": "语义：“防止”是提前阻止坏事发生，与“大雨引起堵车”的因果正好相反。"}, {"text": "消灭", "is_correct": false, "explanation": "搭配：“消灭”多用于敌人、害虫，不用于“堵车”。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”是人的情感，大雨不会喜欢堵车。"}], "explanations": {"导致": "正确：“导致”表示引起某种结果，与“大雨……堵车”的因果相符。", "防止": "语义：“防止”是提前阻止坏事发生，与“大雨引起堵车”的因果正好相反。", "消灭": "搭配：“消灭”多用于敌人、害虫，不用于“堵车”。", "喜欢": "语义：“喜欢”是人的情感，大雨不会喜欢堵车。"}, "sentence_index": 0, "correct_answer": "导致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条小路导致市中心。", "explanation": "这里应该用〈通往〉。导致表示引起某种结果，不能表示道路通到某地，道路通向某地要说通往。"}, {"text": "他导致了一份工作。", "explanation": "这里应该用〈获得〉。导致表示引起结果，不能表示得到某样东西，得到工作要说获得。"}, {"text": "这张图导致了一种红色。", "explanation": "这里应该用〈呈现〉。导致表示引起某种结果，图上的颜色是呈现出来的，要说呈现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21698, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导致", "is_correct": true, "explanation": "正确：“导致”表示引起某种结果，与“一个小错误引起大问题”相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏美好的事物，不能用于“大问题”。"}, {"text": "赢得", "is_correct": false, "explanation": "语义：“赢得”指在竞争中取得，错误不能“赢得”问题。"}, {"text": "获得", "is_correct": false, "explanation": "搭配：“获得”多接奖励、经验等正面的东西，不接“大问题”。"}], "explanations": {"导致": "正确：“导致”表示引起某种结果，与“一个小错误引起大问题”相符。", "欣赏": "语义：“欣赏”是赞赏美好的事物，不能用于“大问题”。", "赢得": "语义：“赢得”指在竞争中取得，错误不能“赢得”问题。", "获得": "搭配：“获得”多接奖励、经验等正面的东西，不接“大问题”。"}, "sentence_index": 6, "correct_answer": "导致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他导致了那份作业。", "explanation": "这里应该用〈完成〉。导致表示引起某种结果，不能表示做完某件事，完成作业要说完成。"}, {"text": "他导致了那座山。", "explanation": "这里应该用〈攀登〉。导致表示引起某种结果，不能表示爬上某座山，攀登山峰要说攀登。"}, {"text": "他导致了那杯茶。", "explanation": "这里应该用〈泡〉。导致表示引起某种结果，不能表示把茶泡出来，泡茶要说泡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改变没有导致了问题。", "corrected_sentence": "这次改变没有导致问题。", "error_description": "“没有”表示未发生，后面不能加“了”；应写作“没有导致问题”，“没有导致了问题”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熬夜被导致他头疼。", "corrected_sentence": "熬夜导致他头疼。", "error_description": "“导致”直接用“原因＋导致＋结果”的主动结构，不能在前面加“被”；应删去“被”，写作“熬夜导致他头疼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eab54a1a-1381-4946-a277-ff5da033c111') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "膨胀", "is_correct": true, "explanation": "正确：“膨胀”指体积变大，与“收缩”互为反义。"}, {"text": "保存", "is_correct": false, "explanation": "“保存”指使东西不损坏，与“收缩”没有反义关系。"}, {"text": "挑选", "is_correct": false, "explanation": "“挑选”指从多个中选出，与“收缩”没有反义关系。"}, {"text": "演奏", "is_correct": false, "explanation": "“演奏”指表演乐曲，与“收缩”没有反义关系。"}], "correct_answer": "膨胀", "explanations": {"膨胀": "正确：“膨胀”指体积变大，与“收缩”互为反义。", "保存": "“保存”指使东西不损坏，与“收缩”没有反义关系。", "挑选": "“挑选”指从多个中选出，与“收缩”没有反义关系。", "演奏": "“演奏”指表演乐曲，与“收缩”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "伸长", "is_correct": true, "explanation": "正确：“伸长”指东西变长，与“收缩”（变短）互为反义。"}, {"text": "融化", "is_correct": false, "explanation": "“融化”指固体变成液体，与“收缩”没有反义关系。"}, {"text": "点燃", "is_correct": false, "explanation": "“点燃”指使东西燃烧，与“收缩”没有反义关系。"}, {"text": "摇晃", "is_correct": false, "explanation": "“摇晃”指来回晃动，与“收缩”没有反义关系。"}], "correct_answer": "伸长", "explanations": {"伸长": "正确：“伸长”指东西变长，与“收缩”（变短）互为反义。", "融化": "“融化”指固体变成液体，与“收缩”没有反义关系。", "点燃": "“点燃”指使东西燃烧，与“收缩”没有反义关系。", "摇晃": "“摇晃”指来回晃动，与“收缩”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变小了或变短了。", "primary_collocate": null, "pronunciation": "shōu suō", "ipa": "ʂoʊ⁵⁵ suɔ³⁵", "syllable_count": 2, "sentences": [{"text": "这条裤子洗完后收缩了。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛衣放在热水里会收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，水管会稍微收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球没有气，就会慢慢收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的棉衬衫洗了一次就收缩了。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块海绵泡水后很大，晾干就收缩了。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，这件衣服遇热水容易收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气温降低时，铁桥的长度会收缩一点。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机烘干以后，裤腿收缩了一截。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料袋靠近火就会收缩。", "target_word": "收缩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收缩了", "label": "体标"}, {"form": "收缩过", "label": "体标"}, {"form": "收缩着", "label": "体标"}, {"form": "收缩压", "label": "复合"}, {"form": "收縮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "收缩：东西变小、变短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收缩", "is_correct": true, "explanation": "正确：“收缩”指裤子洗后变小，与“洗完后”的语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：裤子不能唱歌，与“洗完后”的变化不符。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮料，不能用于裤子。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：裤子不会睡觉，与句子描述的变化无关。"}], "explanations": {"收缩": "正确：“收缩”指裤子洗后变小，与“洗完后”的语境相符。", "唱歌": "语义：裤子不能唱歌，与“洗完后”的变化不符。", "饮用": "搭配：“饮用”的对象是饮料，不能用于裤子。", "睡觉": "语义：裤子不会睡觉，与句子描述的变化无关。"}, "sentence_index": 0, "correct_answer": "收缩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个文件收缩以后只有几兆了。", "explanation": "这里应该用〈压缩〉。收缩指物体自身变小，文件等数据变小要用“压缩”。"}, {"text": "这次考试的难度收缩了不少。", "explanation": "这里应该用〈降低〉。收缩指物体的体积或长度变小，难度的下降要用“降低”。"}, {"text": "河水的水位收缩了很多。", "explanation": "这里应该用〈下降〉。收缩用于物体的体积或长度，水位降低要用“下降”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收缩", "is_correct": true, "explanation": "正确：“收缩”指衣服遇热水后变小，与“遇热水容易”相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：热水不会使衣服结冰，与“遇热水”矛盾。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”用于金属，不能用于衣服。"}, {"text": "发酵", "is_correct": false, "explanation": "语义：衣服不会发酵，与句子描述的变化无关。"}], "explanations": {"收缩": "正确：“收缩”指衣服遇热水后变小，与“遇热水容易”相符。", "结冰": "语义：热水不会使衣服结冰，与“遇热水”矛盾。", "生锈": "搭配：“生锈”用于金属，不能用于衣服。", "发酵": "语义：衣服不会发酵，与句子描述的变化无关。"}, "sentence_index": 6, "correct_answer": "收缩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的时间收缩了两天。", "explanation": "这里应该用〈缩短〉。收缩指东西的体积或长度变小，时间的减少要用“缩短”。"}, {"text": "请把电视的声音收缩一点。", "explanation": "这里应该用〈调小〉。收缩指东西的体积或长度变小，声音变小要说“调小”。"}, {"text": "这种药的副作用收缩了不少。", "explanation": "这里应该用〈减轻〉。收缩指东西的体积或长度变小，副作用变弱要用“减轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布料下水后会收缩很一点。", "corrected_sentence": "这块布料下水后会收缩一点。", "error_description": "错误：数量短语“一点”前多加了“很”。“很”只能修饰形容词等，不能修饰数量短语。正确：“这块布料下水后会收缩一点。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件毛衣洗了以后收缩了得很厉害。", "corrected_sentence": "这件毛衣洗了以后收缩得很厉害。", "error_description": "错误：“收缩”后接程度补语时不能再加“了”，应直接用“收缩得很厉害”。正确：“这件毛衣洗了以后收缩得很厉害。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
