INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物各个部分之间搭配的方式或特点。", "primary_collocate": null, "pronunciation": "jié gòu xìng", "ipa": "tɕiɛ˧˥ kou˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这家工厂有结构性的问题。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家发现这座桥有结构性缺陷。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定做结构性改革。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结构性矛盾一直没有解决。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的结构性问题很多。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分析了市场的结构性变化。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种结构性差异很明显。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先看清问题的结构性原因。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次结构性调整，不是小修小改。", "target_word": "结构性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼的结构性改造需要先经过审批。", "target_word": "结构性", "complexity_tier": "T3", "furigana": "zhè dòng lóu de jiégòuxìng gǎizào xūyào xiān jīngguò shěnpī", "sentence_source": "generated"}], "morphological_forms": [{"form": "结构性失业", "label": "复合"}], "register": "书面", "sense_fingerprint": "事物各部分如何搭配组合所形成的特点，多修饰问题、矛盾、改革等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”修饰“问题”，指工厂问题来自各部分搭配的方式。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”指愉快的感受，工厂有“乐趣的问题”说不通。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，不能说工厂有风景问题。"}, {"text": "长相", "is_correct": false, "explanation": "语义：“长相”指人的外貌，不能用来说工厂的问题。"}], "explanations": {"结构性": "“结构性”修饰“问题”，指工厂问题来自各部分搭配的方式。", "乐趣": "语义：“乐趣”指愉快的感受，工厂有“乐趣的问题”说不通。", "风景": "语义：“风景”指景色，不能说工厂有风景问题。", "长相": "语义：“长相”指人的外貌，不能用来说工厂的问题。"}, "sentence_index": 0, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的结构性很稳定。", "explanation": "这里应该用〈天气〉。“结构性”指事物各部分的搭配方式，不能用来指天气；说天气稳定要用“天气”。"}, {"text": "我的朋友是结构性的。", "explanation": "这里应该用〈热情〉。“结构性”指事物各部分的搭配方式，不用来描述人的性格；形容朋友要用“热情”等词。"}, {"text": "他把结构性送给了朋友。", "explanation": "这里应该用〈礼物〉。“结构性”是属性，不是可以送出去的东西；送人的应该是“礼物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构性", "is_correct": true, "explanation": "“结构性”指组成方式的特点，与“差异很明显”搭配自然。"}, {"text": "跑步", "is_correct": false, "explanation": "语法：“跑步”是动词，不能修饰“差异”，“这种跑步差异”不成立。"}, {"text": "唱歌", "is_correct": false, "explanation": "语法：“唱歌”是动词，不能修饰“差异”，句子不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语法：“睡觉”是动词，不能修饰“差异”，句子不成立。"}], "explanations": {"结构性": "“结构性”指组成方式的特点，与“差异很明显”搭配自然。", "跑步": "语法：“跑步”是动词，不能修饰“差异”，“这种跑步差异”不成立。", "唱歌": "语法：“唱歌”是动词，不能修饰“差异”，句子不成立。", "睡觉": "语法：“睡觉”是动词，不能修饰“差异”，句子不成立。"}, "sentence_index": 6, "correct_answer": "结构性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的结构性很热闹。", "explanation": "这里应该用〈气氛〉。“结构性”指事物各部分的搭配方式，不用来描述场面的热闹；说热闹的场面要用“气氛”等词。"}, {"text": "这栋楼的结构性很好吃。", "explanation": "这里应该用〈味道〉。“结构性”指组成方式，不能用来形容口感或滋味；形容口感要用“味道”。"}, {"text": "这栋楼的结构性很多。", "explanation": "这里应该用〈部分〉。“结构性”表示各部分搭配方式的特点，是一种性质，不能说“很多”；说数量多要用“部分”等词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这栋楼的问题是结构性。", "corrected_sentence": "这栋楼的问题是结构性的。", "error_description": "错误：“是结构性”；正确：“是结构性的”。作表语时，“结构性”后面要加“的”，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革的重点是结构性地。", "corrected_sentence": "这次改革的重点是结构性的。", "error_description": "错误：“是结构性地”；正确：“是结构性的”。作表语时要用“的”，“地”用于动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
