INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21706, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "某件事总是在很短的时间里出现很多次。", "primary_collocate": null, "pronunciation": "pín fā", "ipa": "pʰin˧˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这个路口交通事故频发。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天高温天气频发，大家要多喝水。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近这座城市火灾频发。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地区地震频发，人们很担心。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨季里，山区的泥石流频发。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近事故频发，政府增加了红绿灯。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话诈骗频发，老人要小心。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么这里的问题频发？", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年极端天气频发。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里盗窃案频发，大家都很不安。", "target_word": "频发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "频发的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "坏事或灾害在短时间内多次发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "频发", "is_correct": true, "explanation": "正确。频发指坏事或灾害在短时间内多次发生，“交通事故频发”符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱指发出歌声，不能用来形容事故。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗指清洗，不能用于事故。"}, {"text": "闻", "is_correct": false, "explanation": "语义：闻指用鼻子感觉气味，事故不能被闻。"}], "explanations": {"频发": "正确。频发指坏事或灾害在短时间内多次发生，“交通事故频发”符合语境。", "唱": "语义：唱指发出歌声，不能用来形容事故。", "洗": "搭配：洗指清洗，不能用于事故。", "闻": "语义：闻指用鼻子感觉气味，事故不能被闻。"}, "sentence_index": 0, "correct_answer": "频发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年那个地区只频发了一次地震。", "explanation": "这里应该用〈发生〉。频发指多次出现，只出现一次要用发生。"}, {"text": "去年这里的游客频发了很多。", "explanation": "这里应该用〈增加〉。频发用于坏事或灾害，人数增多要用增加。"}, {"text": "这几年房价频发得很快。", "explanation": "这里应该用〈增长〉。频发用于坏事或灾害，房价上涨要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "频发", "is_correct": true, "explanation": "正确。频发指坏事或灾害多次发生，“电话诈骗频发”指这类事件接连出现。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳指身体的动作，不能用来形容诈骗。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是做饭的动作，与诈骗无关。"}, {"text": "赢", "is_correct": false, "explanation": "搭配：赢多用于比赛、竞争，不说“电话诈骗赢”。"}], "explanations": {"频发": "正确。频发指坏事或灾害多次发生，“电话诈骗频发”指这类事件接连出现。", "跳": "语义：跳指身体的动作，不能用来形容诈骗。", "煮": "语义：煮是做饭的动作，与诈骗无关。", "赢": "搭配：赢多用于比赛、竞争，不说“电话诈骗赢”。"}, "sentence_index": 6, "correct_answer": "频发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校上周频发了一次篮球比赛。", "explanation": "这里应该用〈举行〉。频发用于坏事或灾害，比赛要用举行。"}, {"text": "这项技术已经频发到农村。", "explanation": "这里应该用〈普及〉。频发用于坏事或灾害，技术推广要用普及。"}, {"text": "这个城市刚频发了一种新的鸟。", "explanation": "这里应该用〈出现〉。频发强调多次发生，刚出现的新事物要用出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年山区的泥石流了频发。", "corrected_sentence": "这几年山区的泥石流频发。", "error_description": "体标位置：“了”不能放在动词“频发”前面，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市里的噪音投诉最近被频发。", "corrected_sentence": "城市里的噪音投诉最近频发。", "error_description": "被字句误用：频发是不及物动词，不能加“被”构成被动，应删去“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
