INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做出来的东西有多少。", "primary_collocate": null, "pronunciation": "chǎn liàng", "ipa": "ʈʂʰan˨˩ ljaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "今年苹果的产量很高。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的产量不太高。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的产量比去年多了。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨太少，粮食产量下降了。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器让产量增加了一倍。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民希望提高茶叶的产量。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每月的产量是一万个。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好，今年的产量会更多。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法提高产量。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的产量比前年少。", "target_word": "产量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年产量", "label": "复合"}, {"form": "產量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一定时间内生产出来的东西的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '662c7823-51e1-46b7-b4e3-759c04a652e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "搭配：“味道”指口感，不说“味道很高”，与“产量”的数量义不符。"}, {"text": "产量", "is_correct": true, "explanation": "“产量”指生产出来的东西的数量，与“很高”搭配自然。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时段，“苹果的时间很高”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”一般说深浅或鲜艳，不说颜色“很高”。"}], "explanations": {"味道": "搭配：“味道”指口感，不说“味道很高”，与“产量”的数量义不符。", "产量": "“产量”指生产出来的东西的数量，与“很高”搭配自然。", "时间": "语义：“时间”指时段，“苹果的时间很高”说不通。", "颜色": "搭配：“颜色”一般说深浅或鲜艳，不说颜色“很高”。"}, "sentence_index": 0, "correct_answer": "产量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校的产量很远。", "explanation": "这里应该用〈距离〉。产量指生产出的东西的数量，两地之间的远近要说“距离”。"}, {"text": "这朵花的产量很漂亮。", "explanation": "这里应该用〈颜色〉。产量指生产出的东西的数量，花的颜色要说“颜色”，不能说产量。"}, {"text": "这场演出的产量很长。", "explanation": "这里应该用〈时间〉。产量指生产出的东西的数量，演出持续多久要用“时间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地址", "is_correct": false, "explanation": "语义：“地址”指住所或位置，不是按月计算的数量，“每月的地址是一万个”说不通。"}, {"text": "产量", "is_correct": true, "explanation": "“产量”指一定时间内生产的数量，与“每月的……是一万个”相符。"}, {"text": "生活", "is_correct": false, "explanation": "搭配：“生活”不用“个”计量，不说“每月的生活是一万个”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性格表现，不能用数量计算。"}], "explanations": {"地址": "语义：“地址”指住所或位置，不是按月计算的数量，“每月的地址是一万个”说不通。", "产量": "“产量”指一定时间内生产的数量，与“每月的……是一万个”相符。", "生活": "搭配：“生活”不用“个”计量，不说“每月的生活是一万个”。", "脾气": "语义：“脾气”是性格表现，不能用数量计算。"}, "sentence_index": 6, "correct_answer": "产量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去年的产量比前年矮了五厘米。", "explanation": "这里应该用〈身高〉。产量指生产出的东西的数量，人的高矮要说“身高”。"}, {"text": "小明去年的产量比前年大了一岁。", "explanation": "这里应该用〈年龄〉。产量指生产出的东西的数量，人的岁数要说“年龄”。"}, {"text": "他去年的产量比前年轻了五公斤。", "explanation": "这里应该用〈体重〉。产量指生产出的东西的数量，人的轻重要说“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子想增长大米的产量。", "corrected_sentence": "这个村子想提高大米的产量。", "error_description": "动词搭配错误：“增长”是不及物动词，不能带宾语“产量”；使产量变多要说“提高产量”。正确说法：这个村子想提高大米的产量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的产量比去年高的多。", "corrected_sentence": "今年的产量比去年高得多。", "error_description": "补语标记错误：表示程度的补语前应用“得”，不能用“的”。“高的多”应说“高得多”。正确说法：今年的产量比去年高得多。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb92d47d-b163-42b2-9991-7720f4cd034a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。"}, {"text": "陌生", "is_correct": false, "explanation": "无反义关系：“陌生”指不熟悉，与“紧张”的心理意义不相对。"}, {"text": "深刻", "is_correct": false, "explanation": "无反义关系：“深刻”形容印象或道理深入，与“紧张”不构成反义。"}, {"text": "清脆", "is_correct": false, "explanation": "无反义关系：“清脆”形容声音，与“紧张”的心理状态无关。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。", "陌生": "无反义关系：“陌生”指不熟悉，与“紧张”的心理意义不相对。", "深刻": "无反义关系：“深刻”形容印象或道理深入，与“紧张”不构成反义。", "清脆": "无反义关系：“清脆”形容声音，与“紧张”的心理状态无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放松", "is_correct": true, "explanation": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。"}, {"text": "幽默", "is_correct": false, "explanation": "无反义关系：“幽默”形容言语风趣，与“紧张”的心理状态无关。"}, {"text": "平淡", "is_correct": false, "explanation": "无反义关系：“平淡”形容不突出，与“紧张”的心理意义不相对。"}, {"text": "热烈", "is_correct": false, "explanation": "无反义关系：“热烈”形容情绪高涨，与“紧张”不构成反义。"}], "correct_answer": "放松", "explanations": {"放松": "反义：“紧张”与“放松”相对，指心里由害怕转为安适。", "幽默": "无反义关系：“幽默”形容言语风趣，与“紧张”的心理状态无关。", "平淡": "无反义关系：“平淡”形容不突出，与“紧张”的心理意义不相对。", "热烈": "无反义关系：“热烈”形容情绪高涨，与“紧张”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里很害怕，不能放松。", "primary_collocate": null, "pronunciation": "jǐn zhāng", "ipa": "tɕin˨˩ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "我坐飞机的时候总是很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩第一次看牙医，紧张得哭了。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里一个人在家，她紧张极了。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他紧张得手一直在发抖。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听见奇怪的声音，我心里很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "放轻松，不用紧张，这只是个小测试。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她紧张地看着门外的黑影。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗朝我跑来，我紧张得不敢动。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一进医院，我就觉得紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子站在高高的台上，看起来很紧张。", "target_word": "紧张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紧张感", "label": "复合"}, {"form": "緊張", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容词：心里害怕、不能放松", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b739b74e-8c84-4c81-94e9-a5882880eae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“很紧张”表示心里害怕、不能放松，符合句中的描述。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气、皮肤，不用来形容人的心里状态。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”描述环境，与句中“我”的心理状态不符。"}, {"text": "平坦", "is_correct": false, "explanation": "搭配：“平坦”形容地面、道路，不说人“很平坦”。"}], "explanations": {"紧张": "正确。“很紧张”表示心里害怕、不能放松，符合句中的描述。", "干燥": "搭配：“干燥”形容空气、皮肤，不用来形容人的心里状态。", "潮湿": "语义：“潮湿”描述环境，与句中“我”的心理状态不符。", "平坦": "搭配：“平坦”形容地面、道路，不说人“很平坦”。"}, "sentence_index": 0, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子考了第一名，紧张得直拍手。", "explanation": "这里应该用〈兴奋〉。紧张表示害怕、不能放松，因高兴而拍手要用兴奋。"}, {"text": "听到医生说手术很成功，她终于紧张了。", "explanation": "这里应该用〈安心〉。紧张表示心里害怕、不能放松，听到好消息后心里踏实要用安心。"}, {"text": "他每天在花园里浇花，心情很紧张。", "explanation": "这里应该用〈放松〉。紧张表示心里害怕、不能放松，悠然浇花的心情要用放松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧张", "is_correct": true, "explanation": "正确。“紧张地看着”表示因害怕而注视，符合门外黑影的语境。"}, {"text": "欢喜", "is_correct": false, "explanation": "语义：“欢喜”表示高兴，与门外黑影带来的害怕语境不合。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”多用于对待人，不说“热情地看着黑影”。"}, {"text": "愉快", "is_correct": false, "explanation": "语义：“愉快”表示轻松的好心情，与句中害怕的情绪不合。"}], "explanations": {"紧张": "正确。“紧张地看着”表示因害怕而注视，符合门外黑影的语境。", "欢喜": "语义：“欢喜”表示高兴，与门外黑影带来的害怕语境不合。", "热情": "搭配：“热情”多用于对待人，不说“热情地看着黑影”。", "愉快": "语义：“愉快”表示轻松的好心情，与句中害怕的情绪不合。"}, "sentence_index": 6, "correct_answer": "紧张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很生气，紧张地摔上了门。", "explanation": "这里应该用〈气冲冲〉。紧张表示心里害怕、不能放松，生气摔门要说“气冲冲地摔上了门”。"}, {"text": "阳光很好，她一边哼着歌一边洗衣服，心里很紧张。", "explanation": "这里应该用〈轻松〉。紧张表示心里害怕、不能放松，哼着歌洗衣服的心情要用轻松。"}, {"text": "她和朋友在公园里开心地聊天，心里很紧张。", "explanation": "这里应该用〈愉快〉。紧张表示害怕、不能放松，和朋友开心聊天的心情要用愉快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走进黑漆漆的地下室，我紧张地腿都软了。", "corrected_sentence": "走进黑漆漆的地下室，我紧张得腿都软了。", "error_description": "「紧张」后引出结果补语“腿都软了”要用“得”，用“地”（状语标记）则不成句，应说「紧张得腿都软了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一听见雷声，心里很就紧张。", "corrected_sentence": "她一听见雷声，心里就很紧张。", "error_description": "副词「就」与「很」次序颠倒：「很」要紧接在形容词“紧张”之前，应说「心里就很紧张」，不能说「心里很就紧张」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a03ff467-eecf-49f3-8b62-b4ecf7c3170c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和：与“极端”相对，指态度、办法平和、有分寸。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴：与“极端”没有反义关系，只表示心情愉快。"}, {"text": "简单", "is_correct": false, "explanation": "简单：与“极端”没有反义关系，只表示不复杂。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：与“极端”没有反义关系，只表示明白、不模糊。"}], "correct_answer": "温和", "explanations": {"温和": "温和：与“极端”相对，指态度、办法平和、有分寸。", "高兴": "高兴：与“极端”没有反义关系，只表示心情愉快。", "简单": "简单：与“极端”没有反义关系，只表示不复杂。", "清楚": "清楚：与“极端”没有反义关系，只表示明白、不模糊。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和：与“极端”相对，指态度、办法平和、有分寸。"}, {"text": "干净", "is_correct": false, "explanation": "干净：与“极端”没有反义关系，只表示没有脏东西。"}, {"text": "轻松", "is_correct": false, "explanation": "轻松：与“极端”没有反义关系，只表示不费力、不紧张。"}, {"text": "明显", "is_correct": false, "explanation": "明显：与“极端”没有反义关系，只表示容易看出。"}], "correct_answer": "温和", "explanations": {"温和": "温和：与“极端”相对，指态度、办法平和、有分寸。", "干净": "干净：与“极端”没有反义关系，只表示没有脏东西。", "轻松": "轻松：与“极端”没有反义关系，只表示不费力、不紧张。", "明显": "明显：与“极端”没有反义关系，只表示容易看出。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "程度达到顶点的；过分、不留余地的（多含贬义），如“极端天气”“极端的办法”。", "primary_collocate": null, "pronunciation": "jí duān", "ipa": "tɕi˧˥ twan˥", "syllable_count": 2, "sentences": [{"text": "今年夏天的天气非常极端。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法太极端了，我不同意。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "极端天气让很多农民很难过。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做有点极端。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个很极端的人，不是爱就是恨。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的气温很极端，白天热，晚上冷。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用这么极端的办法解决问题。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的看法一点也不极端。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近出现了极端的高温天气。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得他说得太极端，没有考虑别人。", "target_word": "极端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "极端的", "label": "定语形式"}, {"form": "极端化", "label": "复合词"}], "register": "中性", "sense_fingerprint": "程度达到顶点的，过分的、不留余地的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极端", "is_correct": true, "explanation": "极端（jí duān）：程度达到顶点、过分。"}, {"text": "击断", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）、duàn（第四声）与 duān（第一声）声调都不同，意思是击打致断。"}, {"text": "极短", "is_correct": false, "explanation": "duǎn（第三声）与 duān（第一声）声调不同，意思是非常短。"}, {"text": "挤断", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）、duàn（第四声）与 duān（第一声）声调都不同，意思是挤压致断。"}], "explanations": {"极端": "极端（jí duān）：程度达到顶点、过分。", "击断": "jī（第一声）与 jí（第二声）、duàn（第四声）与 duān（第一声）声调都不同，意思是击打致断。", "极短": "duǎn（第三声）与 duān（第一声）声调不同，意思是非常短。", "挤断": "jǐ（第三声）与 jí（第二声）、duàn（第四声）与 duān（第一声）声调都不同，意思是挤压致断。"}, "sentence_index": null, "correct_answer": "极端"}, "level_3": {"options": [{"text": "极端", "is_correct": true, "explanation": "极端：说天气变化超出常态，符合“非常”的语境。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容天气。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描写人或物的高度，不用来说天气。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”用于人、地方或感觉，不与“天气”搭配。"}], "explanations": {"极端": "极端：说天气变化超出常态，符合“非常”的语境。", "聪明": "语义：“聪明”形容人的智力，不能用来形容天气。", "矮": "体貌：“矮”描写人或物的高度，不用来说天气。", "陌生": "搭配：“陌生”用于人、地方或感觉，不与“天气”搭配。"}, "sentence_index": 0, "correct_answer": "极端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我考得极端好。", "explanation": "这里应该用〈非常〉。极端表示程度过分、不留余地，多含贬义，不用来夸正面的好。"}, {"text": "这张桌子很极端。", "explanation": "这里应该用〈干净〉。极端用于态度、办法、天气等，不用来描述桌子的整洁。"}, {"text": "他的房间很极端。", "explanation": "这里应该用〈整齐〉。极端不用来描述房间的整齐与否。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极端", "is_correct": true, "explanation": "极端：说办法过分、不留余地，符合“不要用”的语境。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容味道，不能用来形容办法。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：“寂寞”形容人的心情，不能用来形容办法。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描写人或动物的体形，不用来说办法。"}], "explanations": {"极端": "极端：说办法过分、不留余地，符合“不要用”的语境。", "香甜": "语义：“香甜”形容味道，不能用来形容办法。", "寂寞": "语义：“寂寞”形容人的心情，不能用来形容办法。", "瘦小": "体貌：“瘦小”描写人或动物的体形，不用来说办法。"}, "sentence_index": 6, "correct_answer": "极端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的头发很极端。", "explanation": "这里应该用〈长〉。极端不用来描述头发的长短。"}, {"text": "这顿饭很极端。", "explanation": "这里应该用〈丰盛〉。极端不用来形容饭菜的数量与品种。"}, {"text": "他的声音很极端。", "explanation": "这里应该用〈洪亮〉。极端不用来描述声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用极端地手段对付对手。", "corrected_sentence": "他用极端的手段对付对手。", "error_description": "结构助词错误：“极端”修饰名词“手段”时要用“的”，不能用“地”；“地”用于修饰动词或形容词作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他极端的反对这种做法。", "corrected_sentence": "他极端地反对这种做法。", "error_description": "结构助词错误：“极端”修饰动词作状语时要用“地”，不能用“的”，应说“极端地反对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稳定", "is_correct": true, "explanation": "反义：「稳定」指不起伏、不变动，与「波动」相对。"}, {"text": "读书", "is_correct": false, "explanation": "无关：「读书」是学习活动，与起伏变化没有反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "无关：「生长」指生物长大，与「波动」没有反义关系。"}, {"text": "歌唱", "is_correct": false, "explanation": "无关：「歌唱」指唱歌，与「波动」没有反义关系。"}], "correct_answer": "稳定", "explanations": {"稳定": "反义：「稳定」指不起伏、不变动，与「波动」相对。", "读书": "无关：「读书」是学习活动，与起伏变化没有反义关系。", "生长": "无关：「生长」指生物长大，与「波动」没有反义关系。", "歌唱": "无关：「歌唱」指唱歌，与「波动」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稳定", "is_correct": true, "explanation": "反义：「稳定」指不起伏、不变动，与「波动」相对。"}, {"text": "写字", "is_correct": false, "explanation": "无关：「写字」是书写文字，与起伏变化没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：「睡觉」指休息，与「波动」没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：「唱歌」指发声演唱，与「波动」没有反义关系。"}], "correct_answer": "稳定", "explanations": {"稳定": "反义：「稳定」指不起伏、不变动，与「波动」相对。", "写字": "无关：「写字」是书写文字，与起伏变化没有反义关系。", "睡觉": "无关：「睡觉」指休息，与「波动」没有反义关系。", "唱歌": "无关：「唱歌」指发声演唱，与「波动」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像水一样上下动。", "primary_collocate": null, "pronunciation": "bō dòng", "ipa": "pɔ⁵⁵ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "最近菜价波动很大。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的气温波动不大。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心情常常波动。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股票价格每天都在波动。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水随着风轻轻波动。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的天气波动得很厉害。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的体重一直在波动。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船随着海水上下波动。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格波动了几天，后来就稳定了。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水一波动，小鱼就游走了。", "target_word": "波动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "波动了", "label": "体标"}, {"form": "波动着", "label": "体标"}, {"form": "波动过", "label": "体标"}, {"form": "波动性", "label": "复合"}, {"form": "波動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "像水波一样上下起伏变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe847b-453c-49ae-ad59-f1b51c9b852b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "波动", "is_correct": true, "explanation": "正确：「波动」指菜价上下起伏变化，与“很大”搭配，符合句意。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：「跳舞」是人的动作，菜价不会跳舞。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：「讨论」需要人作主语、事件作宾语，“菜价讨论很大”不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」指人闭眼休息，与菜价的变化无关。"}], "explanations": {"波动": "正确：「波动」指菜价上下起伏变化，与“很大”搭配，符合句意。", "跳舞": "语义：「跳舞」是人的动作，菜价不会跳舞。", "讨论": "配价：「讨论」需要人作主语、事件作宾语，“菜价讨论很大”不成立。", "睡觉": "语义：「睡觉」指人闭眼休息，与菜价的变化无关。"}, "sentence_index": 0, "correct_answer": "波动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手机在桌上波动。", "explanation": "这里应该用〈振动〉。波动多指水、价格等有起伏的变化，手机的震动要用“振动”。"}, {"text": "他在屋里来回波动。", "explanation": "这里应该用〈踱步〉。人在室内来回走动要说“踱步”，“波动”不用来描述人的行走。"}, {"text": "他冷得浑身波动。", "explanation": "这里应该用〈颤抖〉。人因寒冷发抖要说“颤抖”，“波动”不用来形容人体的抖动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "波动", "is_correct": true, "explanation": "正确：「波动」指体重起伏变化，与“一直在”搭配，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是人的休闲活动，体重不能散步。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」指在水中运动，体重不能游泳。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：「喜欢」需要有感情的主语和对象，“体重在喜欢”不成立。"}], "explanations": {"波动": "正确：「波动」指体重起伏变化，与“一直在”搭配，符合句意。", "散步": "语义：「散步」是人的休闲活动，体重不能散步。", "游泳": "语义：「游泳」指在水中运动，体重不能游泳。", "喜欢": "配价：「喜欢」需要有感情的主语和对象，“体重在喜欢”不成立。"}, "sentence_index": 6, "correct_answer": "波动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在山路上波动。", "explanation": "这里应该用〈颠簸〉。车辆在崎岖路面上的上下跳动要用“颠簸”，“波动”多用于水、价格等有起伏的变化，不用来描述车辆。"}, {"text": "妈妈波动了我的头发。", "explanation": "配价：〈波动〉不能直接带宾语“头发”，这里应该用〈吹动〉。"}, {"text": "他用手波动了门。", "explanation": "配价：〈波动〉不能直接带“门”作宾语，这里应该用〈推动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "价格一直在的波动。", "corrected_sentence": "价格一直在波动。", "error_description": "错误：“在的波动”。正确：“在波动”。“在”是副词，后面直接接动词，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "股市这几天波动地很厉害。", "corrected_sentence": "股市这几天波动得很厉害。", "error_description": "错误：“波动地”。正确：“波动得”。动词后接程度补语要用“得”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f80b1c-a7d9-45a1-824c-58a02ab5c6d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
