INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变得和以前不一样，让事情更合适。", "primary_collocate": null, "pronunciation": "tiáo zhěng", "ipa": "tʰiɑʊ̯˧˥ ʈʂɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把椅子调整到合适的高度。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他调整了一下坐姿，坐得舒服多了。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把闹钟调整到了六点半。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师调整了大家的座位。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想调整自己的心态，别太紧张。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "镜子的角度不对，请调整一下。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把屏幕调整得亮一点。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作息不太好，要调整一下。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的饮食需要慢慢调整。", "target_word": "调整", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把会议时间调整到了下午。", "target_word": "调整", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "调整了", "label": "完成体"}, {"form": "调整过", "label": "经历体"}, {"form": "调整调整", "label": "重叠"}], "register": "中性", "sense_fingerprint": "改变物品、状态或安排，使它更合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c928e1f6-5741-4790-be78-40c893415c14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21716, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "调整", "is_correct": true, "explanation": "调整：把椅子的高度变得合适，与“到合适的高度”相符。"}, {"text": "站", "is_correct": false, "explanation": "配价：“站”是不及物动词，不能把椅子作宾语。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指清洁表面，与“合适的高度”无关，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，与调节高度无关，句子不通。"}], "explanations": {"调整": "调整：把椅子的高度变得合适，与“到合适的高度”相符。", "站": "配价：“站”是不及物动词，不能把椅子作宾语。", "擦": "语义：“擦”指清洁表面，与“合适的高度”无关，句子不通。", "洗": "语义：“洗”指清洗，与调节高度无关，句子不通。"}, "sentence_index": 0, "correct_answer": "调整"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人调整了那台坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。修理用于损坏的东西，调整针对能用但需要变得合适的东西。"}, {"text": "妈妈调整了一块旧抹布，它现在很干净。", "explanation": "这里应该用〈清洗〉。清洗指用水去除污渍，调整表示使事物变得合适，不能表示洗涤。"}, {"text": "他不小心调整了盘子，盘子碎成了好几块。", "explanation": "这里应该用〈打碎〉。打碎指弄坏、使破裂，调整不能表示损坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调整", "is_correct": true, "explanation": "调整：对屏幕的亮度做调节，与“亮一点”相符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或事情，不能用于屏幕。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”指关闭，屏幕关掉后不会更亮，与“亮一点”矛盾。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”的对象是话语，不能带“屏幕”作宾语，句子不通。"}], "explanations": {"调整": "调整：对屏幕的亮度做调节，与“亮一点”相符。", "讨论": "搭配：“讨论”的对象是问题或事情，不能用于屏幕。", "关": "语义：“关”指关闭，屏幕关掉后不会更亮，与“亮一点”矛盾。", "说": "配价：“说”的对象是话语，不能带“屏幕”作宾语，句子不通。"}, "sentence_index": 6, "correct_answer": "调整"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧书调整到了垃圾桶里。", "explanation": "这里应该用〈扔〉。扔指丢弃，调整表示让东西变得合适，不能表示丢弃。"}, {"text": "他把水调整进了杯子里。", "explanation": "这里应该用〈倒〉。倒指把液体注入容器，调整不能表示倾倒。"}, {"text": "她把想法调整在了纸上。", "explanation": "这里应该用〈写〉。写指用文字记录下来，调整表示使事物变得合适，不能表示书写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把灯调整在了合适的亮度。", "corrected_sentence": "他把灯调整到了合适的亮度。", "error_description": "补语介词错误：“调整”后接“到”表示调整到某种状态，“在”不能接在“调整”后。应说“调整到了合适的亮度”，不能说“调整在了合适的亮度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把电视调整地小一点。", "corrected_sentence": "她把电视调整得小一点。", "error_description": "结构助词错误：动词后表示程度的补语要用“得”，“地”用于动词前修饰动词。应说“调整得小一点”，不能说“调整地小一点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd25b5865-410b-4790-8dfa-e2b7af39d8ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
