INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政策是政府告诉大家要怎么做事情。", "primary_collocate": null, "pronunciation": "zhèng cè", "ipa": "ʈʂəŋ˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "政府出台了新的环保政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的教育政策让更多孩子能上学。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策帮助了很多农民。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策鼓励大家多骑自行车。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府制定政策，是为了让生活更好。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的住房政策下个月会改变。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策规定，学校附近不能开网吧。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了国家的农业政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的新政策让外地人也能买房。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府的好政策让大家的日子越来越好。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项政策", "label": "量词"}, {"form": "政策性", "label": "复合"}], "register": "正式", "sense_fingerprint": "政策：政府制定的、要求大家怎样做事的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a50759fb-3f82-4d2e-b11e-78657eb50899') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21718, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "政策：政府制定的要求大家怎样做事的规定，与“出台了新的环保”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“出台”不接“颜色”，“出台了新的环保颜色”说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种植花草的地方，不是可以出台的规定，句子不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“出台”不能与“体温”搭配，句子不通。"}], "explanations": {"政策": "政策：政府制定的要求大家怎样做事的规定，与“出台了新的环保”搭配，符合句意。", "颜色": "搭配：“出台”不接“颜色”，“出台了新的环保颜色”说不通。", "花园": "语义：“花园”是种植花草的地方，不是可以出台的规定，句子不通。", "体温": "搭配：“出台”不能与“体温”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的政策很有意思。", "explanation": "这里应该用〈内容〉。政策是规定或办法，书里讲的东西要说内容，不能说政策。"}, {"text": "这道菜的政策是先放盐再放油。", "explanation": "这里应该用〈做法〉。政策是政府制定的规定，做菜的步骤要说做法。"}, {"text": "他对待工作的政策很认真。", "explanation": "这里应该用〈态度〉。政策是政府制定的规定，个人对待工作的看法要用态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21718, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "政策：正式规定，与“新……规定”搭配，指学校附近不能开网吧的规定，符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“新”不能修饰“脚步”构成规定，“新脚步规定”说不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不是可以制定的规定，与“不能开网吧”的意思不合。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不是规定，“学校附近不能开网吧”与饭菜无关，句子不通。"}], "explanations": {"政策": "政策：正式规定，与“新……规定”搭配，指学校附近不能开网吧的规定，符合句意。", "脚步": "搭配：“新”不能修饰“脚步”构成规定，“新脚步规定”说不通。", "心情": "语义：“心情”不是可以制定的规定，与“不能开网吧”的意思不合。", "饭菜": "语义：“饭菜”不是规定，“学校附近不能开网吧”与饭菜无关，句子不通。"}, "sentence_index": 6, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下棋时用的政策很高明。", "explanation": "这里应该用〈策略〉。下棋时的计划和方法叫策略，政策是政府制定的规定。"}, {"text": "这是自然界的政策。", "explanation": "这里应该用〈规律〉。政策是人为制定的规定，自然界的现象不能叫政策。"}, {"text": "他家的政策是晚上九点必须睡觉。", "explanation": "这里应该用〈规矩〉。家里的要求叫规矩，政策是政府制定的规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府又出台了一座新政策。", "corrected_sentence": "政府又出台了一项新政策。", "error_description": "错误：“一座”；正确：“一项”。“座”用于山、房屋等大型固定物，政策应使用量词“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府制定过这把政策。", "corrected_sentence": "政府制定过这项政策。", "error_description": "错误：“这把”；正确：“这项”。“把”用于有柄的器具等，政策应使用量词“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '459c1e00-80a1-48bf-a6a9-1b8f4c6573bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
