INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们一起管理国家的事情。", "primary_collocate": null, "pronunciation": "zhèng zhì", "ipa": "tʂɤŋ˥˩ tʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他对政治很感兴趣。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学学政治。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人不关心政治。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢看政治新闻。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政治很稳定。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做政治方面的工作。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃饭的时候，我们不聊政治。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是研究政治的老师。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治和经济都会影响人们的生活。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前在政府工作，现在不谈政治了。", "target_word": "政治", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "政治家", "label": "复合"}, {"form": "政治学", "label": "复合"}], "register": "中性", "sense_fingerprint": "管理国家的公共事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09aebaf0-be95-4ef2-b319-0da839c40a89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政治", "is_correct": true, "explanation": "政治 zhèngzhì：正确答案，指人们一起管理国家的事情。"}, {"text": "正直", "is_correct": false, "explanation": "声调不同：正直 zhèngzhí 第二个音节是第二声，政治 zhèngzhì 是第四声，意思是品行端正。"}, {"text": "争执", "is_correct": false, "explanation": "声调不同：争执 zhēngzhí 两个音节的声调都与政治不同，意思是因意见不合而争论。"}, {"text": "正是", "is_correct": false, "explanation": "声母不同：正是 zhèngshì 的 sh 与政治 zhèngzhì 的 zh 不同，意思是恰好、正是如此。"}], "explanations": {"政治": "政治 zhèngzhì：正确答案，指人们一起管理国家的事情。", "正直": "声调不同：正直 zhèngzhí 第二个音节是第二声，政治 zhèngzhì 是第四声，意思是品行端正。", "争执": "声调不同：争执 zhēngzhí 两个音节的声调都与政治不同，意思是因意见不合而争论。", "正是": "声母不同：正是 zhèngshì 的 sh 与政治 zhèngzhì 的 zh 不同，意思是恰好、正是如此。"}, "sentence_index": null, "correct_answer": "政治"}, "level_3": {"options": [{"text": "政治", "is_correct": true, "explanation": "政治：正确答案，指国家的公共事务，与“对……感兴趣”搭配自然。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“对……感兴趣”的对象多为领域或话题，感冒是疾病，不能作为兴趣对象。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是生理现象，一般不会被当作让人感兴趣的话题。"}, {"text": "脚趾", "is_correct": false, "explanation": "语义：脚趾是身体部位，句子表达的是对某一领域的兴趣，句意不通。"}], "explanations": {"政治": "政治：正确答案，指国家的公共事务，与“对……感兴趣”搭配自然。", "感冒": "搭配：“对……感兴趣”的对象多为领域或话题，感冒是疾病，不能作为兴趣对象。", "眼泪": "语义：眼泪是生理现象，一般不会被当作让人感兴趣的话题。", "脚趾": "语义：脚趾是身体部位，句子表达的是对某一领域的兴趣，句意不通。"}, "sentence_index": 0, "correct_answer": "政治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府出台了新的环保政治。", "explanation": "这里应该用〈政策〉。政治指管理国家的公共事务，不是具体规定；“出台”的对象是政策。"}, {"text": "这个政治有很多党员。", "explanation": "这里应该用〈政党〉。政治是抽象的管理活动，没有党员；有党员的是政党。"}, {"text": "他是一位出色的政治。", "explanation": "这里应该用〈政治家〉。政治指管理国家公共事务的活动，不指人；指从事政治的人要用“政治家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21722, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "政治", "is_correct": true, "explanation": "政治 zhèngzhì：正确答案，指人们一起管理国家的事情。"}, {"text": "整治", "is_correct": false, "explanation": "声调不同：整治 zhěngzhì 第一个音节是第三声，政治 zhèngzhì 是第四声，意思是整顿、治理。"}, {"text": "正式", "is_correct": false, "explanation": "声母不同：正式 zhèngshì 的 sh 与政治 zhèngzhì 的 zh 不同，意思是符合规定的、正规的。"}, {"text": "正值", "is_correct": false, "explanation": "声调不同：正值 zhèngzhí 第二个音节是第二声，政治 zhèngzhì 是第四声，意思是恰好赶上某个时候。"}], "explanations": {"政治": "政治 zhèngzhì：正确答案，指人们一起管理国家的事情。", "整治": "声调不同：整治 zhěngzhì 第一个音节是第三声，政治 zhèngzhì 是第四声，意思是整顿、治理。", "正式": "声母不同：正式 zhèngshì 的 sh 与政治 zhèngzhì 的 zh 不同，意思是符合规定的、正规的。", "正值": "声调不同：正值 zhèngzhí 第二个音节是第二声，政治 zhèngzhì 是第四声，意思是恰好赶上某个时候。"}, "sentence_index": null, "correct_answer": "政治"}, "level_3": {"options": [{"text": "政治", "is_correct": true, "explanation": "政治：正确答案，指国家事务，是可以在饭桌上避开的话题之一。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物件，不是可以在饭桌上谈论的话题，“不聊钥匙”句意不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不是可以谈论的话题，“不聊椅子”句意不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：“拖鞋”是物件，不是可以谈论的话题，句意不通。"}], "explanations": {"政治": "政治：正确答案，指国家事务，是可以在饭桌上避开的话题之一。", "钥匙": "语义：“钥匙”是物件，不是可以在饭桌上谈论的话题，“不聊钥匙”句意不通。", "椅子": "语义：“椅子”是家具，不是可以谈论的话题，“不聊椅子”句意不通。", "拖鞋": "语义：“拖鞋”是物件，不是可以谈论的话题，句意不通。"}, "sentence_index": 6, "correct_answer": "政治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的政治很好。", "explanation": "这里应该用〈医疗〉。政治指管理国家公共事务，不能用来评价医院的水平；评价医院要说“医疗”。"}, {"text": "军人发动了政治。", "explanation": "这里应该用〈政变〉。“发动”搭配的是政变这类事件，政治不能被发动。"}, {"text": "候选人公布了政治。", "explanation": "这里应该用〈政纲〉。公布的是竞选时提出的政纲，政治是抽象的概念，不能被公布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给政治不感兴趣。", "corrected_sentence": "妈妈对政治不感兴趣。", "error_description": "介词错误：表示对某事感不感兴趣，要用“对”，说“对政治不感兴趣”，不能用“给”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在政治没有兴趣。", "corrected_sentence": "她对政治没有兴趣。", "error_description": "介词错误：表示对某事有没有兴趣，要用“对”，说“对政治没有兴趣”，不能用“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a99349c-a414-4f31-81ee-602b0549755f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
