INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水往一个方向走。", "primary_collocate": null, "pronunciation": "liú xiàng", "ipa": "ljou̯˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "河水的流向是从西到东。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的箭头表示河流的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的流向很特别。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先观察一下这段河道的流向。", "target_word": "流向", "complexity_tier": "T3", "furigana": "liú xiàng", "sentence_source": "generated"}, {"text": "下雨后，雨水的流向跟着地势走。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用红笔画出了河水的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用树叶测出了小溪的流向。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里地势低，所以水的流向是向南。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水的流向很难看出来。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人要先搞清楚污水的流向，再修管道。", "target_word": "流向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "河水流向", "label": "复合"}, {"form": "水流流向", "label": "复合"}], "register": "中性", "sense_fingerprint": "河水、雨水等水流动的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流速", "is_correct": false, "explanation": "语义：流速说水流的快慢，不能说明水流从哪里到哪里的方向。"}, {"text": "流向", "is_correct": true, "explanation": "流向指水流动的方向，与“从西到东”搭配，符合句意。"}, {"text": "水位", "is_correct": false, "explanation": "语义：水位指水面的高低，不能说明水流从西到东的走向。"}, {"text": "流域", "is_correct": false, "explanation": "语义：流域指河流经过的区域，不是水流的方向。"}], "explanations": {"流速": "语义：流速说水流的快慢，不能说明水流从哪里到哪里的方向。", "流向": "流向指水流动的方向，与“从西到东”搭配，符合句意。", "水位": "语义：水位指水面的高低，不能说明水流从西到东的走向。", "流域": "语义：流域指河流经过的区域，不是水流的方向。"}, "sentence_index": 0, "correct_answer": "流向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这段河道的流向很快，要注意安全。", "explanation": "这里应该用〈流速〉。流向说水流的方向，水流的快慢要用〈流速〉。"}, {"text": "这条河在夏天的流向最大。", "explanation": "这里应该用〈流量〉。流向说方向，不说大小；夏天水量最大要用〈流量〉。"}, {"text": "这条河的流向在夏天上涨了。", "explanation": "这里应该用〈水位〉。流向说方向，不能上涨；河水高度的变化要用〈水位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：用树叶测不出颜色，与“测出”的对象不相符。"}, {"text": "流向", "is_correct": true, "explanation": "流向指水流朝哪边走，用树叶漂浮可以测出，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“测出味道”不搭配，树叶无法测量味道。"}, {"text": "光泽", "is_correct": false, "explanation": "语义：光泽是表面的反光效果，与水流的测量无关。"}], "explanations": {"颜色": "语义：用树叶测不出颜色，与“测出”的对象不相符。", "流向": "流向指水流朝哪边走，用树叶漂浮可以测出，符合句意。", "味道": "搭配：“测出味道”不搭配，树叶无法测量味道。", "光泽": "语义：光泽是表面的反光效果，与水流的测量无关。"}, "sentence_index": 6, "correct_answer": "流向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口井的流向很好，可以直接饮用。", "explanation": "这里应该用〈水质〉。流向说水流的方向，水的好坏要用〈水质〉。"}, {"text": "这口井的流向很低，适合保存食物。", "explanation": "这里应该用〈水温〉。流向说方向，水的冷热要用〈水温〉。"}, {"text": "这片湖的流向不到两米，很适合划船。", "explanation": "这里应该用〈水深〉。流向说方向，水的深浅要用〈水深〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水的流向地是向东。", "corrected_sentence": "湖水的流向是向东。", "error_description": "错误：“流向地是向东”中多了“地”；正确：“流向是向东”。“流向”是名词，后面不能接“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在河边画出了溪水地流向。", "corrected_sentence": "孩子们在河边画出了溪水的流向。", "error_description": "错误：“溪水地流向”；正确：“溪水的流向”。“流向”是名词，前面的定语要用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
