INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种地的人家。", "primary_collocate": null, "pronunciation": "nóng hù", "ipa": "nʊŋ˧˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "这家农户住在山脚下，家里有五亩地。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天到了，农户忙着收稻子。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农户把新鲜的蔬菜拉到市场上卖。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老李家是我们村里种地的农户。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干旱让农户的收入少了很多。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农户每天很早就下地干活。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些农户用自己种的水果做果酱。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者去农户家里采访了一位老人。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农户们一起买种子，价格更便宜。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的雨水很多，农户都很高兴。", "target_word": "农户", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "户", "label": "量词"}, {"form": "小农户", "label": "复合"}, {"form": "農戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以种地为生的人家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21732, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工厂", "is_correct": false, "explanation": "语义：工厂不会住在山脚下，也不会“家里有五亩地”。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：量词“家”不能与“学生”搭配，学生也不会“家里有五亩地”。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不是家庭，不会“住在山脚下、家里有五亩地”。"}, {"text": "农户", "is_correct": true, "explanation": "“农户”指以种地为生的人家，符合“住在山脚下、家里有五亩地”的语境。"}], "explanations": {"工厂": "语义：工厂不会住在山脚下，也不会“家里有五亩地”。", "学生": "搭配：量词“家”不能与“学生”搭配，学生也不会“家里有五亩地”。", "医院": "语义：医院不是家庭，不会“住在山脚下、家里有五亩地”。", "农户": "“农户”指以种地为生的人家，符合“住在山脚下、家里有五亩地”的语境。"}, "sentence_index": 0, "correct_answer": "农户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校的农户都很用功。", "explanation": "这里应该用〈学生〉。农户指以种地为生的人家，学校里的人不能称农户。"}, {"text": "我们公司的农户每天坐在办公室里上班。", "explanation": "这里应该用〈员工〉。农户指以种地为生的人家，公司里上班的人要说员工。"}, {"text": "老李家是我们村里种地的一只农户。", "explanation": "这里应该用量词〈户〉。“只”不用于以家庭为单位的农户。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机器", "is_correct": false, "explanation": "语义：机器不会种水果，也不会用水果做果酱。"}, {"text": "农户", "is_correct": true, "explanation": "“农户”指以种地为生的人家，符合“用自己种的水果做果酱”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种水果，也不能做果酱。"}, {"text": "书", "is_correct": false, "explanation": "配价：“做果酱”的施事应是人，“书”不能做果酱。"}], "explanations": {"机器": "语义：机器不会种水果，也不会用水果做果酱。", "农户": "“农户”指以种地为生的人家，符合“用自己种的水果做果酱”的语境。", "石头": "语义：石头不能种水果，也不能做果酱。", "书": "配价：“做果酱”的施事应是人，“书”不能做果酱。"}, "sentence_index": 6, "correct_answer": "农户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家农户的董事会昨天召开了年度会议。", "explanation": "这里应该用〈公司〉。农户是家庭经营单位，没有董事会，应说公司。"}, {"text": "这家农户的老师很多。", "explanation": "这里应该用〈学校〉。农户指以种地为生的人家，不能说有老师。"}, {"text": "这家农户的护士都很热情。", "explanation": "这里应该用〈医院〉。农户不是医疗机构，不能说有护士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村东头那户很农户一直靠种地为生。", "corrected_sentence": "村东头那户农户一直靠种地为生。", "error_description": "错误：程度副词“很”不能修饰名词“农户”，应删去“很”，说“那户农户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里那户靠种地为生农户很能干。", "corrected_sentence": "村里那户靠种地为生的农户很能干。", "error_description": "错误：修饰语“靠种地为生”与中心语“农户”之间漏掉了“的”。应说“靠种地为生的农户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "正确：“背对”与“面对”相反，指背朝某个方向，与“房子面对大海”形成对立。"}, {"text": "打开", "is_correct": false, "explanation": "“打开”指使合拢的东西张开，与表示朝向的“面对”没有反义关系。"}, {"text": "拿起", "is_correct": false, "explanation": "“拿起”指用手提起物品，与“面对”的朝向义没有反义关系。"}, {"text": "坐下", "is_correct": false, "explanation": "“坐下”指身体改成坐的姿势，与“面对”的朝向义没有反义关系。"}], "correct_answer": "背对", "explanations": {"背对": "正确：“背对”与“面对”相反，指背朝某个方向，与“房子面对大海”形成对立。", "打开": "“打开”指使合拢的东西张开，与表示朝向的“面对”没有反义关系。", "拿起": "“拿起”指用手提起物品，与“面对”的朝向义没有反义关系。", "坐下": "“坐下”指身体改成坐的姿势，与“面对”的朝向义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "正确：“背对”与“面对”相反，指背朝某个方向，与“请你面对墙”形成对立。"}, {"text": "写字", "is_correct": false, "explanation": "“写字”指用笔写字，与表示朝向的“面对”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音演唱曲调，与“面对”的朝向义没有反义关系。"}, {"text": "看书", "is_correct": false, "explanation": "“看书”指阅读书籍，与“面对”的朝向义没有反义关系。"}], "correct_answer": "背对", "explanations": {"背对": "正确：“背对”与“面对”相反，指背朝某个方向，与“请你面对墙”形成对立。", "写字": "“写字”指用笔写字，与表示朝向的“面对”没有反义关系。", "唱歌": "“唱歌”指用声音演唱曲调，与“面对”的朝向义没有反义关系。", "看书": "“看书”指阅读书籍，与“面对”的朝向义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脸对着某个方向或东西。", "primary_collocate": null, "pronunciation": "miàn duì", "ipa": "mjɛn⁵¹ tuei⁵¹", "syllable_count": 2, "sentences": [{"text": "他面对窗户坐着。", "target_word": "面对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家面对老师站好。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里，学生都面对黑板。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座房子面对大海，风景很好。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她面对镜子整理头发。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他转过身，面对着我。", "target_word": "面对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的门面对一条小路。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客面对大山拍了一张照片。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们面对老师站成两排。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你面对墙，不要回头。", "target_word": "面对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "面对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "脸朝向某个方向或物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面对", "is_correct": true, "explanation": "正确：“面对”表示脸朝向窗户，符合“他……窗户坐着”的语境。"}, {"text": "接受", "is_correct": false, "explanation": "语义：“接受”指接纳某物或某事，不能表示身体朝向，“接受窗户坐着”说不通。"}, {"text": "瞪", "is_correct": false, "explanation": "搭配：“瞪”的对象通常是人，不能瞪窗户，句子不成立。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、邀请等，不能用于窗户，与“坐着”的位置描述无关。"}], "explanations": {"面对": "正确：“面对”表示脸朝向窗户，符合“他……窗户坐着”的语境。", "接受": "语义：“接受”指接纳某物或某事，不能表示身体朝向，“接受窗户坐着”说不通。", "瞪": "搭配：“瞪”的对象通常是人，不能瞪窗户，句子不成立。", "拒绝": "搭配：“拒绝”的对象是请求、邀请等，不能用于窗户，与“坐着”的位置描述无关。"}, "sentence_index": 0, "correct_answer": "面对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他面对一个星期，终于把书读完了。", "explanation": "这里误用了“面对”的“面临、应对”义，“一个星期”是时段，不能被面对，应说〈用〉一个星期。"}, {"text": "他面对昨天，心里很开心。", "explanation": "这里误用了“面对”的“面临、应对”义，“昨天”是时间，不能被面对，应说〈回想〉昨天的事。"}, {"text": "这棵树面对去年长高了。", "explanation": "“面对”的对象是人、物或方向，“去年”是时间，不能被面对；应说〈比〉去年长高了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面对", "is_correct": true, "explanation": "正确：“面对”表示门朝向一条小路，符合“我家的门……一条小路”的语境。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压在上面，门不能踩路，句子说不通。"}, {"text": "选择", "is_correct": false, "explanation": "配价：“选择”要求有意愿的施事，门不能做选择，此处不成立。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再要某物，门不会放弃路，与“门朝向小路”的描述不合。"}], "explanations": {"面对": "正确：“面对”表示门朝向一条小路，符合“我家的门……一条小路”的语境。", "踩": "语义：“踩”是用脚压在上面，门不能踩路，句子说不通。", "选择": "配价：“选择”要求有意愿的施事，门不能做选择，此处不成立。", "放弃": "语义：“放弃”指不再要某物，门不会放弃路，与“门朝向小路”的描述不合。"}, "sentence_index": 6, "correct_answer": "面对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他面对三点钟，马上就出门了。", "explanation": "这里误用了“面对”的“面临、应对”义，“三点钟”是时间点，不能被面对，应说〈等到〉三点钟再出门。"}, {"text": "我面对星期五，觉得很累。", "explanation": "这里误用了“面对”的“面临、应对”义，“星期五”是时间，不能被面对，应说〈盼望〉星期五到来。"}, {"text": "他面对自己的名字，笑着跑开了。", "explanation": "这里误用了“面对”的“面临”义，“名字”不是可以被面对的情况，应说〈听见〉自己的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她转过身，面对了着老师。", "corrected_sentence": "她转过身，面对着老师。", "error_description": "「面对了着老师」中“了”和“着”不能同时用在同一动词后；表示动作持续只用“着”，应说“面对着老师”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间屋子被面对一片树林。", "corrected_sentence": "这间屋子面对一片树林。", "error_description": "“面对”是主动动词，不能加“被”构成被动句，应说“这间屋子面对一片树林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21736, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c52ccf7c-18a6-4962-acc1-231bfff3779e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
