INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示全都一样或全都如此。", "primary_collocate": null, "pronunciation": "jūn", "ipa": "tɕyn⁵⁵", "syllable_count": 1, "sentences": [{"text": "这里的房子价格均不高。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个孩子的成绩均很好。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "参加比赛的学生均已到齐。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果均是今天早上买的。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三位老师均来自北京。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里的衣服均打八折。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的年纪均在二十岁左右。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各位客人均可免费喝茶。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几本书均是他写的。", "target_word": "均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班同学的作业均已交齐。", "target_word": "均", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "范围副词，表示全都如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7cea0ef-f5d6-475e-98b1-4539dcad4711') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”（jūn）表示全都，是这里要听的词。"}, {"text": "窘", "is_correct": false, "explanation": "jiǒng 与 jūn 韵母、声调都不同，意思是为难、窘迫。"}, {"text": "居", "is_correct": false, "explanation": "jū 与 jūn 韵母不同，少了鼻音 -n，意思是居住。"}, {"text": "郡", "is_correct": false, "explanation": "jùn（第四声）与 jūn（第一声）声调不同，意思是古代行政区。"}, {"text": "俊", "is_correct": false, "explanation": "jùn（第四声）与 jūn（第一声）声调不同，意思是英俊。"}], "explanations": {"均": "正确：“均”（jūn）表示全都，是这里要听的词。", "窘": "jiǒng 与 jūn 韵母、声调都不同，意思是为难、窘迫。", "居": "jū 与 jūn 韵母不同，少了鼻音 -n，意思是居住。", "郡": "jùn（第四声）与 jūn（第一声）声调不同，意思是古代行政区。", "俊": "jùn（第四声）与 jūn（第一声）声调不同，意思是英俊。"}, "sentence_index": null, "correct_answer": "均"}, "level_3": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”表示全都，与“这里的房子价格”搭配，符合“不高”的整体描述。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示比较中的最高程度，句中没有比较对象，“最不高”说不通。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，句子要说的是这些房子价格都不高，而不是只有个别。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同做某事，价格不能“一起不高”，说不通。"}], "explanations": {"均": "正确：“均”表示全都，与“这里的房子价格”搭配，符合“不高”的整体描述。", "最": "搭配：“最”表示比较中的最高程度，句中没有比较对象，“最不高”说不通。", "只": "语义：“只”表示限定，句子要说的是这些房子价格都不高，而不是只有个别。", "一起": "语义：“一起”表示共同做某事，价格不能“一起不高”，说不通。"}, "sentence_index": 0, "correct_answer": "均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些人中，有一个均来了。", "explanation": "“均”表示全部一致，“有一个”只指部分，两者矛盾，不能搭配。"}, {"text": "这个水果均是今天早上买的。", "explanation": "“均”表示全部，要求主语是多个对象；这里只说“这个水果”一个，不能用“均”。"}, {"text": "我均去过北京。", "explanation": "“均”表示全都，主语须是两个或以上；“我”只指一人，不能用“均”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”（jūn）表示全都，是这里要听的词。"}, {"text": "捐", "is_correct": false, "explanation": "juān 与 jūn 韵母不同（-uan 与 -un），意思是捐献。"}, {"text": "金", "is_correct": false, "explanation": "jīn 与 jūn 韵母不同（-in 与 -un），意思是金子。"}, {"text": "群", "is_correct": false, "explanation": "qún 与 jūn 声母（q 与 j）和声调都不同，意思是一群。"}], "explanations": {"均": "正确：“均”（jūn）表示全都，是这里要听的词。", "捐": "juān 与 jūn 韵母不同（-uan 与 -un），意思是捐献。", "金": "jīn 与 jūn 韵母不同（-in 与 -un），意思是金子。", "群": "qún 与 jūn 声母（q 与 j）和声调都不同，意思是一群。"}, "sentence_index": null, "correct_answer": "均"}, "level_3": {"options": [{"text": "均", "is_correct": true, "explanation": "正确：“均”表示全都，符合“他们的年纪……在二十岁左右”的整体描述。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”突出程度，与“在二十岁左右”的估计语气冲突。"}, {"text": "一共", "is_correct": false, "explanation": "搭配：“一共”用于总计，年纪不能加总，“一共在二十岁左右”不成立。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与预期相反，与描述年龄范围的语境不合。"}], "explanations": {"均": "正确：“均”表示全都，符合“他们的年纪……在二十岁左右”的整体描述。", "特别": "语义：“特别”突出程度，与“在二十岁左右”的估计语气冲突。", "一共": "搭配：“一共”用于总计，年纪不能加总，“一共在二十岁左右”不成立。", "偏偏": "语义：“偏偏”表示故意与预期相反，与描述年龄范围的语境不合。"}, "sentence_index": 6, "correct_answer": "均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的同学均很高，只有他很矮。", "explanation": "“均”表示全部一致，后面不能接“只有他”这样的例外，前后矛盾。"}, {"text": "这间屋子的窗户均朝南，但有一扇朝北。", "explanation": "“均”表示全部一致，后面却说“有一扇朝北”，前后矛盾。"}, {"text": "全班同学的作业均已交齐，但有几个人还没交。", "explanation": "“均”表示全都如此，后面却说“有几个人还没交”，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些同学均的已报名。", "corrected_sentence": "这些同学均已报名。", "error_description": "“均”是副词，后面不能加“的”，应说“这些同学均已报名”，不能说“均的已报名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位老师都均已经到了。", "corrected_sentence": "几位老师均已经到了。", "error_description": "“均”和“都”都表示全都，不能叠用，应去掉“都”，说“几位老师均已经到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75c67f1d-1a91-444a-905b-9d12e4644a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
