INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事可能遇到不好的事情，就像走一条有坑的路。", "primary_collocate": null, "pronunciation": "fēng xiǎn", "ipa": "fəŋ˥ ɕjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "做生意有一定的风险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做的风险太大了。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想冒这个风险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买股票有风险，要小心。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先想想有什么风险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机的风险比开车小。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划风险很高，我不同意。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们愿意承担一些风险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天爬山有很大的风险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减少风险，他买了保险。", "target_word": "风险", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个风险", "label": "量词（个）"}, {"form": "风险投资", "label": "复合词"}, {"form": "風險", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事时可能遇到的不好的结果或危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21740, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风险", "is_correct": true, "explanation": "“风险”指做事可能遇到的不好结果，与“一定的”搭配，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能说“做生意有一定的桌子”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“做生意”与“颜色”无关，“有一定的颜色”说不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是作品，与做生意的后果无关。"}], "explanations": {"风险": "“风险”指做事可能遇到的不好结果，与“一定的”搭配，句意通顺。", "桌子": "语义：“桌子”是家具，不能说“做生意有一定的桌子”。", "颜色": "语义：“做生意”与“颜色”无关，“有一定的颜色”说不通。", "歌曲": "语义：“歌曲”是作品，与做生意的后果无关。"}, "sentence_index": 0, "correct_answer": "风险"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司面临一只风险。", "explanation": "这里应该用〈个〉。风险是抽象名词，不能用“只”，“只”多用于动物。"}, {"text": "他承担了一条风险。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，与“风险”搭配不自然。"}, {"text": "我们遇到了一座风险。", "explanation": "这里应该用〈个〉。风险是抽象名词，不能用“座”，“座”多用于山、建筑等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21740, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风险", "is_correct": true, "explanation": "“风险”指可能遇到的不好结果，与“很高”搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不能说“这个计划天气很高”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书的包，不能说“这个计划书包很高”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是建筑物，不能用来描述计划的程度。"}], "explanations": {"风险": "“风险”指可能遇到的不好结果，与“很高”搭配，句意通顺。", "天气": "语义：“天气”是自然现象，不能说“这个计划天气很高”。", "书包": "语义：“书包”是装书的包，不能说“这个计划书包很高”。", "房子": "语义：“房子”是建筑物，不能用来描述计划的程度。"}, "sentence_index": 6, "correct_answer": "风险"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次航行遇到了一盏风险。", "explanation": "这里应该用〈个〉。风险是抽象名词，不能用“盏”，“盏”多用于灯。"}, {"text": "他在比赛中遇到一支风险。", "explanation": "这里应该用〈个〉。风险是抽象名词，不能用“支”，“支”多用于笔、队伍等。"}, {"text": "我们要防止一颗风险发生。", "explanation": "这里应该用〈个〉。风险是抽象名词，不能用“颗”，“颗”用于粒状的小东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案有一把明显的风险。", "corrected_sentence": "这个方案有一个明显的风险。", "error_description": "错误在量词“把”。“把”用于有柄的物品，“风险”要用“个”，正确形式是“一个明显的风险”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们承担了着很大的风险。", "corrected_sentence": "他们承担着很大的风险。", "error_description": "错误在于“承担”后面同时用了“了”和“着”两个动态助词。正确形式是“承担着”，表示持续的状态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个别", "is_correct": true, "explanation": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物头绪多、难理解，与“普遍”的意思没有对立关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价钱低，与“普遍”的范围广没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“普遍”不构成反义。"}], "correct_answer": "个别", "explanations": {"个别": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。", "复杂": "“复杂”形容事物头绪多、难理解，与“普遍”的意思没有对立关系。", "便宜": "“便宜”形容价钱低，与“普遍”的范围广没有反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“普遍”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个别", "is_correct": true, "explanation": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。"}, {"text": "清淡", "is_correct": false, "explanation": "“清淡”形容味道或颜色淡，与“普遍”的意思无关，不构成反义。"}, {"text": "迟缓", "is_correct": false, "explanation": "“迟缓”形容动作或速度慢，与“普遍”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“普遍”的范围广不构成反义。"}], "correct_answer": "个别", "explanations": {"个别": "正确。“个别”指少数、不普遍，与“普遍”构成反义关系。", "清淡": "“清淡”形容味道或颜色淡，与“普遍”的意思无关，不构成反义。", "迟缓": "“迟缓”形容动作或速度慢，与“普遍”没有反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“普遍”的范围广不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是到处都有，很多地方都一样。", "primary_collocate": null, "pronunciation": "pǔ biàn", "ipa": "pʰu˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "现在手机在年轻人中很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种情况在大城市很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题很普遍，很多学校都有。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上网看书已经变得很普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑自行车在这里非常普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "普遍的看法是，早睡对身体好。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个习惯在老人中不太普遍。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生用电脑上课，现在很普遍了。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一个普遍的问题，不只你有。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花在南方很普遍，到处都能看到。", "target_word": "普遍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "普遍地", "label": "副词形式"}, {"form": "普遍性", "label": "复合词"}], "register": "中性", "sense_fingerprint": "存在范围很广，到处都有、大家都这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b72803e1-d339-466f-98b7-61dea376201f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "正确。“普遍”指到处都有、很多人都这样，与“现在手机在年轻人中很普遍”相符。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人有胆量，不能用来形容手机。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：“寂寞”形容人的心情，手机不会感到寂寞，不能这样形容它。"}, {"text": "缓慢", "is_correct": false, "explanation": "搭配：“缓慢”形容速度或动作慢，不能用来描述手机的普及程度。"}], "explanations": {"普遍": "正确。“普遍”指到处都有、很多人都这样，与“现在手机在年轻人中很普遍”相符。", "勇敢": "搭配：“勇敢”形容人有胆量，不能用来形容手机。", "寂寞": "搭配：“寂寞”形容人的心情，手机不会感到寂寞，不能这样形容它。", "缓慢": "搭配：“缓慢”形容速度或动作慢，不能用来描述手机的普及程度。"}, "sentence_index": 0, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜很普遍，别的店都没有这样的做法。", "explanation": "这里应该用〈独特〉。普遍指很多地方、很多人都有，与“别的店都没有”的意思相反；只说一家的特色要用独特。"}, {"text": "他只是个普遍的工人，没什么特别的经历。", "explanation": "这里应该用〈普通〉。普遍强调范围广，形容人平凡、一般要用普通。"}, {"text": "昨天的会议很普遍，是我们第一次在湖边开的。", "explanation": "这里应该用〈特殊〉。普遍指很多地方都有，单次活动不能说普遍；表示与众不同要用特殊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普遍", "is_correct": true, "explanation": "正确。“不太普遍”指在老人中并不多见，与句意一致。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”说人的年龄，不能用来形容习惯。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，习惯没有体形，不能这样说。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”指声音大而清楚，与“习惯在老人中是否多见”无关。"}], "explanations": {"普遍": "正确。“不太普遍”指在老人中并不多见，与句意一致。", "年轻": "搭配：“年轻”说人的年龄，不能用来形容习惯。", "高大": "体貌：“高大”形容人或物的体形，习惯没有体形，不能这样说。", "响亮": "语义：“响亮”指声音大而清楚，与“习惯在老人中是否多见”无关。"}, "sentence_index": 6, "correct_answer": "普遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次意外是普遍的，没人预料到。", "explanation": "这里应该用〈偶然〉。普遍指范围广、到处都有，单次意外不能说普遍；偶然发生的事要用偶然。"}, {"text": "这所学校有一个普遍的实验室。", "explanation": "这里应该用〈专门〉。普遍指范围广，形容单个设施不合适；为某项用途设立的要用专门。"}, {"text": "这里只有普遍的几户人家。", "explanation": "这里应该用〈零星〉。普遍指很多地方都有，少量分散的几户不能说普遍；形容分散稀少要用零星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种现象在城市里很普遍性。", "corrected_sentence": "这种现象在城市里很普遍。", "error_description": "词性错误：“普遍性”是名词，不能作“很”之后的形容词谓语，应说“很普遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个普遍地现象，很多人都见过。", "corrected_sentence": "这是一个普遍的现象，很多人都见过。", "error_description": "助词错误：修饰名词“现象”时要用“的”，不能用副词用的“地”，应说“普遍的现象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad148756-200b-47de-aecb-2bf8e8034b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21744, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "充足与缺乏是反义词，指足够、不缺。"}, {"text": "高兴", "is_correct": false, "explanation": "高兴与缺乏没有反义关系，只是形容心情的词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与缺乏没有反义关系，不是表示有无的词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明与缺乏没有反义关系，形容的是才智。"}], "correct_answer": "充足", "explanations": {"充足": "充足与缺乏是反义词，指足够、不缺。", "高兴": "高兴与缺乏没有反义关系，只是形容心情的词。", "清楚": "清楚与缺乏没有反义关系，不是表示有无的词。", "聪明": "聪明与缺乏没有反义关系，形容的是才智。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
