INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "就是没有的意思，比如说没有水、没有钱。", "primary_collocate": null, "pronunciation": "quē fá", "ipa": "tɕʰɥe˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "他刚工作，缺乏经验。", "target_word": "缺乏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子缺乏自信。", "target_word": "缺乏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多山区缺乏干净的水。", "target_word": "缺乏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司缺乏资金，不能买新电脑。", "target_word": "缺乏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太忙了，长期缺乏睡眠。", "target_word": "缺乏", "complexity_tier": "T3", "furigana": "tā tài máng le, cháng qī quē fá shuì mián.", "sentence_source": "generated"}, {"text": "我们学校缺乏好老师。", "target_word": "缺乏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章缺乏新的想法。", "target_word": "缺乏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话时缺乏信心。", "target_word": "缺乏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子缺乏运动，身体不太好。", "target_word": "缺乏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城缺乏工作机会，年轻人都走了。", "target_word": "缺乏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "缺乏：没有或不够某种需要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f562dea-1484-4d6c-8f48-09986f773a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "缺乏", "is_correct": true, "explanation": "“缺乏经验”指经验不足，与“刚工作”的语境相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“刚工作”矛盾。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”不及物，不能带宾语“经验”。"}, {"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”不及物，不能带宾语“经验”。"}], "explanations": {"缺乏": "“缺乏经验”指经验不足，与“刚工作”的语境相符。", "退休": "语义：“退休”指离开工作岗位，与“刚工作”矛盾。", "毕业": "配价：“毕业”不及物，不能带宾语“经验”。", "结婚": "配价：“结婚”不及物，不能带宾语“经验”。"}, "sentence_index": 0, "correct_answer": "缺乏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我缺乏了这班火车。", "explanation": "这里应该用〈错过〉。缺乏指缺少需要的东西，没赶上车要说“错过”。"}, {"text": "他这次缺乏了比赛。", "explanation": "这里应该用〈缺席〉。缺乏表示缺少需要的东西，人不到场要说“缺席”。"}, {"text": "他的钱包缺乏了。", "explanation": "这里应该用〈丢失〉。缺乏指缺少需要的东西，已有的东西不见了要说“丢失”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺乏", "is_correct": true, "explanation": "“缺乏新的想法”指没有新的想法，与“文章”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”不及物，不能带宾语“想法”。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”指清洁身体，与“新的想法”不搭。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”指整理物品，不能用于“想法”。"}], "explanations": {"缺乏": "“缺乏新的想法”指没有新的想法，与“文章”的语境相符。", "睡觉": "配价：“睡觉”不及物，不能带宾语“想法”。", "洗澡": "语义：“洗澡”指清洁身体，与“新的想法”不搭。", "收拾": "语义：“收拾”指整理物品，不能用于“想法”。"}, "sentence_index": 6, "correct_answer": "缺乏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快地缺乏了一瓶水。", "explanation": "这里应该用〈喝完〉。缺乏是状态，不表示很快完成的动作，应说“喝完”。"}, {"text": "祝你缺乏快乐。", "explanation": "这里应该用〈拥有〉。祝愿是希望对方有某物，“缺乏”表示没有，意思相反。"}, {"text": "这台机器缺乏了运行。", "explanation": "这里应该用〈开机〉。缺乏指缺少需要的东西，机器运行是动作，不能用“缺乏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23291e5-b33c-4e2b-b6f4-2da4fb3db2fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
