INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示东西不大。", "primary_collocate": null, "pronunciation": "xiǎo", "ipa": "ɕjɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个盒子太小，装不下书。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这张桌子很小，只能坐两个人。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手机屏幕很小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个苹果比那个小。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的书包太小了，放不下水瓶。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子对大人来说太小。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个蛋糕很小，一个人就能吃完。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小的那个箱子是我的。", "target_word": "小", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋有点小，走路脚疼。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外的花园很小，树也都很矮。", "target_word": "小", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "小小", "label": "重叠"}], "register": "中性", "sense_fingerprint": "具体东西的个头、尺寸不大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 书包 (Zipf 3.62), 不下 (Zipf 3.94), 水瓶 (Zipf 3.14)']::text[], '19817550-c904-44e4-a2d8-d2169ad3d57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），表示东西不大。"}, {"text": "校", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。"}, {"text": "消", "is_correct": false, "explanation": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。"}, {"text": "想", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。"}, {"text": "效", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），表示东西不大。", "校": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“学校”。", "消": "声调不同：xiāo（第一声）与 xiǎo（第三声）声调不同，意思是“消除”。", "想": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“想念”。", "效": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“效果”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“盒子太小”指盒子的容积不够，“小”与“装不下书”相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能修饰“盒子”。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线充足，与“装不下书”的容量义无关，句意不通。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”指速度低，与“盒子”的容量无关，句意不通。"}], "explanations": {"小": "正确：“盒子太小”指盒子的容积不够，“小”与“装不下书”相符。", "甜": "搭配：“甜”形容味道，不能修饰“盒子”。", "亮": "语义：“亮”指光线充足，与“装不下书”的容量义无关，句意不通。", "慢": "语义：“慢”指速度低，与“盒子”的容量无关，句意不通。"}, "sentence_index": 0, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家离学校很小，要坐一个小时车。", "explanation": "这里应该用〈远〉。“小”说东西的体积、尺寸不大，说距离要用“远”，“离学校很小”不这么说。"}, {"text": "他们之间的感情很小，几乎不往来。", "explanation": "这里应该用〈淡〉。“小”说东西的大小，不说感情的深浅；感情淡薄要用“淡”，“感情很小”不这么用。"}, {"text": "这个箱子的价钱很小，我买不起。", "explanation": "这里应该用〈高〉。“小”说东西的大小，不说价钱高低；价钱高要用“高”，“价钱很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "小", "is_correct": true, "explanation": "本词：小（xiǎo，第三声），表示东西不大。"}, {"text": "笑", "is_correct": false, "explanation": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。"}, {"text": "脚", "is_correct": false, "explanation": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。"}, {"text": "险", "is_correct": false, "explanation": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。"}, {"text": "享", "is_correct": false, "explanation": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}], "explanations": {"小": "本词：小（xiǎo，第三声），表示东西不大。", "笑": "声调不同：xiào（第四声）与 xiǎo（第三声）声调不同，意思是“笑”。", "脚": "声母不同：jiǎo 的声母是 j，xiǎo 的声母是 x，意思是“脚”。", "险": "韵母不同：xiǎn 的韵母是 -an，xiǎo 的韵母是 -ao，意思是“危险”。", "享": "韵母不同：xiǎng 的韵母是 -ang，xiǎo 的韵母是 -ao，意思是“享受”。"}, "sentence_index": null, "correct_answer": "小"}, "level_3": {"options": [{"text": "小", "is_correct": true, "explanation": "正确：“蛋糕很小”指蛋糕的体积不大，与“一个人就能吃完”相符。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”形容距离，不能用来修饰“蛋糕”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能形容蛋糕。"}, {"text": "暖", "is_correct": false, "explanation": "语义：“暖”指温度，与“一个人就能吃完”的份量义无关，句意不通。"}], "explanations": {"小": "正确：“蛋糕很小”指蛋糕的体积不大，与“一个人就能吃完”相符。", "远": "搭配：“远”形容距离，不能用来修饰“蛋糕”。", "瘦": "体貌：“瘦”形容人或动物的身材，不能形容蛋糕。", "暖": "语义：“暖”指温度，与“一个人就能吃完”的份量义无关，句意不通。"}, "sentence_index": 6, "correct_answer": "小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在车站停留的时间很小，就出发了。", "explanation": "这里应该用〈短〉。“小”说东西的大小，不说时间长短；时间短要用“短”，“停留时间很小”不这么用。"}, {"text": "这间屋子的温度很小，大家都冷得发抖。", "explanation": "这里应该用〈低〉。“小”说东西的大小，不说温度高低，温度低要用“低”，“温度很小”不这么用。"}, {"text": "这列火车跑得很小。", "explanation": "这里应该用〈快〉。“小”说东西的大小，不用来形容“跑得”的快慢；说快慢要用“快”或“慢”，“跑得很小”不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鞋小穿不进去。", "corrected_sentence": "这只鞋小得穿不进去。", "error_description": "补语错误：“小”作谓语时后接补语“穿不进去”，中间须用“得”连接，应说“小得穿不进去”；漏掉“得”，“小穿不进去”不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只碗小很，装不下这么多汤。", "corrected_sentence": "这只碗很小，装不下这么多汤。", "error_description": "位置错误：“很”是程度副词，应放在形容词前，说“很小”，不说“小很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0af25b-9d4d-4739-a7c3-d9a3cd8ddec7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。"}, {"text": "严格", "is_correct": false, "explanation": "形容要求高、不宽松，与“国际”没有反义关系。"}, {"text": "委婉", "is_correct": false, "explanation": "形容说话含蓄、不直接，与“国际”没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "形容经济条件好、财产多，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。", "严格": "形容要求高、不宽松，与“国际”没有反义关系。", "委婉": "形容说话含蓄、不直接，与“国际”没有反义关系。", "富裕": "形容经济条件好、财产多，与“国际”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。"}, {"text": "迟钝", "is_correct": false, "explanation": "形容反应慢、感觉不灵敏，与“国际”没有反义关系。"}, {"text": "温和", "is_correct": false, "explanation": "形容性情或态度平和，与“国际”没有反义关系。"}, {"text": "亲切", "is_correct": false, "explanation": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}], "correct_answer": "国内", "explanations": {"国内": "与“国际”相对，指一国之内，不涉及不同国家之间的事务，二者构成反义。", "迟钝": "形容反应慢、感觉不灵敏，与“国际”没有反义关系。", "温和": "形容性情或态度平和，与“国际”没有反义关系。", "亲切": "形容态度和蔼、让人感到温暖，与“国际”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "指不同国家之间的事情。", "primary_collocate": null, "pronunciation": "guó jì", "ipa": "kwo˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "国际上，很多国家都在帮助这个地方。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际关系越来越好，两国来往也多了。", "target_word": "国际", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对国际问题很感兴趣。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国际组织帮助贫困的儿童。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际形势会影响各国的经济。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "整个国际社会都希望和平。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条国际规定要求所有国家遵守。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际合作让环境变得更干净。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际事务不是一个国家能解决的。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在国际机构工作了五年。", "target_word": "国际", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际化", "label": "复合"}, {"form": "国际象棋", "label": "复合"}, {"form": "國際", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不同国家之间的事务、关系与局势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确答案。国际读作 guó jì，指不同国家之间的事情。"}, {"text": "国籍", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。"}, {"text": "过激", "is_correct": false, "explanation": "guò jī 与 guó jì 声母韵母相同，只是声调不同，意思是过分激烈。"}, {"text": "过季", "is_correct": false, "explanation": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。"}, {"text": "国境", "is_correct": false, "explanation": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}], "explanations": {"国际": "正确答案。国际读作 guó jì，指不同国家之间的事情。", "国籍": "jí（第二声）与 jì（第四声）声调不同，意思是国籍。", "过激": "guò jī 与 guó jì 声母韵母相同，只是声调不同，意思是过分激烈。", "过季": "guò（第四声）与 guó（第二声）声调不同，意思是过了季节。", "国境": "jìng 比 jì 多了韵尾 ng，意思是国家的边界。"}, "sentence_index": null, "correct_answer": "国际"}, "level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际上”指在国与国之间的范围，与“很多国家都在帮助”相符。"}, {"text": "农村", "is_correct": false, "explanation": "语义：“农村上”不是有效的处所，且与“很多国家”的范围不相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校上”只指一所学校，与“很多国家帮助”的范围矛盾。"}, {"text": "家里", "is_correct": false, "explanation": "搭配：“家里上”不能作处所词，与“上”的用法不搭配。"}], "explanations": {"国际": "正确：“国际上”指在国与国之间的范围，与“很多国家都在帮助”相符。", "农村": "语义：“农村上”不是有效的处所，且与“很多国家”的范围不相符。", "学校": "语义：“学校上”只指一所学校，与“很多国家帮助”的范围矛盾。", "家里": "搭配：“家里上”不能作处所词，与“上”的用法不搭配。"}, "sentence_index": 0, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国际政府决定增加学校经费。", "explanation": "这里应该用〈国家〉。“国际”指国与国之间，一个政府只属于一个国家，要说“国家政府”。"}, {"text": "这几年国际的天气变化很大。", "explanation": "这里应该用〈全球〉。“国际”指国与国之间，天气变化属于整个地球，要说“全球”。"}, {"text": "国际的农民收入提高了。", "explanation": "这里应该用〈国内〉。“国际”指国与国之间，说一国之内的农民要用“国内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际", "is_correct": true, "explanation": "正确：“国际规定”指国与国之间的规定，要求所有国家遵守，与句意相符。"}, {"text": "国内", "is_correct": false, "explanation": "语义：“国内规定”只在一国之内有效，不能要求所有国家遵守。"}, {"text": "地方", "is_correct": false, "explanation": "语义：“地方规定”只约束当地，不能要求所有国家遵守。"}, {"text": "班级", "is_correct": false, "explanation": "搭配：“班级”的规定约束的是学生，不能用来要求国家遵守。"}], "explanations": {"国际": "正确：“国际规定”指国与国之间的规定，要求所有国家遵守，与句意相符。", "国内": "语义：“国内规定”只在一国之内有效，不能要求所有国家遵守。", "地方": "语义：“地方规定”只约束当地，不能要求所有国家遵守。", "班级": "搭配：“班级”的规定约束的是学生，不能用来要求国家遵守。"}, "sentence_index": 6, "correct_answer": "国际"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父母一直住在国际的小城市。", "explanation": "这里应该用〈本国〉。“国际”指国与国之间，说自己国家之内的小城市要用“本国”。"}, {"text": "我家的国际沙发很舒服。", "explanation": "这里应该用〈国产〉。“国际”指国与国之间，说我国自己生产的沙发要用“国产”。"}, {"text": "这个国际的人口超过了一亿。", "explanation": "这里应该用〈地区〉。“国际”指国与国之间，一个地区的人口不能说成“国际的人口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们对国际了事务很关心。", "corrected_sentence": "我们对国际事务很关心。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“对国际事务很关心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在国际了机构工作了两年。", "corrected_sentence": "她在国际机构工作了两年。", "error_description": "语法错误：区别词“国际”修饰名词时后面不能加动态助词“了”，应去掉“了”。正确说法是“在国际机构工作了两年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
