INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一些人自己出钱开的公司或工厂。", "primary_collocate": null, "pronunciation": "sī yíng qǐ yè", "ipa": "sɹ̩˥ iŋ˧˥ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "他自己出钱开了一家私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私营企业只有三个人。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "私营企业的工资有时比较高。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在私营企业工作过。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个朋友合开了一家私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家私营企业生产的鞋很便宜。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想开一家小的私营企业。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家私营企业是我朋友自己办的。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥辞职后办了私营企业。", "target_word": "私营企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家私营企业的老板很年轻。", "target_word": "私营企业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "私营企业主", "label": "复合"}, {"form": "私營企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个人自己出钱开办的公司或工厂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929f630-bb3e-4acd-8c80-d8e8929653e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：私营企业是一些人自己出钱开办的公司或工厂，与“出钱开了一家”相符。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能被“开”，也不能说“开了一家老师”。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：量词“家”用于店铺、公司，猫应用“只”，且不能被开办。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能被出钱开办。"}], "explanations": {"私营企业": "正确：私营企业是一些人自己出钱开办的公司或工厂，与“出钱开了一家”相符。", "老师": "语义：老师是人，不能被“开”，也不能说“开了一家老师”。", "小猫": "搭配：量词“家”用于店铺、公司，猫应用“只”，且不能被开办。", "天空": "语义：天空是自然景象，不能被出钱开办。"}, "sentence_index": 0, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一台私营企业。", "explanation": "这里应该用〈家〉。企业用量词“家”，“台”用于机器，不能用于企业。"}, {"text": "我舅舅是私营企业，很有钱。", "explanation": "这里应该用〈私营企业主〉。私营企业指机构，不能指人。"}, {"text": "这家私营企业会员很多，每周都有比赛。", "explanation": "这里应该用〈俱乐部〉。会员和比赛是俱乐部的活动，私营企业指由私人经营的公司，不设会员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "私营企业", "is_correct": true, "explanation": "正确：私营企业是个人出资经营的企业，与“我想开一家小的”相符。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：量词“家”用于店铺、公司，狗应用“只”，不能说“一家小的狗”。"}, {"text": "冬天", "is_correct": false, "explanation": "语义：冬天是时间，不能被“开”。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：火车应用量词“列”或“辆”，不能用“家”。"}], "explanations": {"私营企业": "正确：私营企业是个人出资经营的企业，与“我想开一家小的”相符。", "狗": "搭配：量词“家”用于店铺、公司，狗应用“只”，不能说“一家小的狗”。", "冬天": "语义：冬天是时间，不能被“开”。", "火车": "搭配：火车应用量词“列”或“辆”，不能用“家”。"}, "sentence_index": 6, "correct_answer": "私营企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她小学是在私营企业念的。", "explanation": "这里应该用〈私立学校〉。“私营”用于企业，学校应说“私立”。"}, {"text": "我们的私营企业很爱笑，每天都很开心。", "explanation": "这里应该用〈老板〉。“私营企业”指机构，不会笑，说人很开心要用“老板”。"}, {"text": "这家私营企业是政府出资开的。", "explanation": "这里应该用〈国有企业〉。私营企业由私人出资，政府出资就不能说是私营。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在一只私营企业当秘书。", "corrected_sentence": "我姐姐在一家私营企业当秘书。", "error_description": "量词错误：“企业”应用量词“家”，“只”用于动物等。错误在“一只”，应改为“一家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸以前过开一家私营企业。", "corrected_sentence": "我爸爸以前开过一家私营企业。", "error_description": "体标位置错误：“过”表示经历，应紧跟动词，写作“开过”，不能放在动词前。错误在“过开”，应改为“开过一家私营企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dbc4bb8-5566-4d2f-beff-7f3a34bd77d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
