INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西变成用电脑能处理的样子。", "primary_collocate": null, "pronunciation": "shù zì huà", "ipa": "ʂu˥˩ tsɨ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "图书馆想把旧书都数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在把老照片数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纸上的资料，需要先数字化才能存进电脑。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把所有合同数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字化以后，文件就不会丢了。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆把很多文物数字化了，大家在网上就能看。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把课本数字化，学生用平板就能读。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行想让更多服务数字化。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把爷爷的旧录音数字化，留给孩子。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要数字化一本旧书，要先一页一页扫描。", "target_word": "数字化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数字化了", "label": "体标"}, {"form": "数字化转型", "label": "复合"}], "register": "中性", "sense_fingerprint": "数字化:把东西变成电脑能处理的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e4321f-de6e-46a4-8743-02c784fb0964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“图书馆想把旧书都数字化”指把旧书转换成电脑能处理的形式，符合句意。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：书不能被吃掉，与“图书馆想把旧书都”的处理意图不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“旧书”这类物件作宾语，句子讲不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”多用于食物，不能用来处理旧书。"}], "explanations": {"数字化": "正确：“图书馆想把旧书都数字化”指把旧书转换成电脑能处理的形式，符合句意。", "吃掉": "语义：书不能被吃掉，与“图书馆想把旧书都”的处理意图不合。", "唱": "配价：“唱”不能带“旧书”这类物件作宾语，句子讲不通。", "煮": "搭配：“煮”多用于食物，不能用来处理旧书。"}, "sentence_index": 0, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这本英文书数字化成了中文。", "explanation": "这里应该用〈翻译〉。数字化指转换为数字形式，不指改变语言，应说“翻译成中文”。"}, {"text": "他把我妈妈做的饭菜数字化了。", "explanation": "这里应该用〈记下〉。数字化的对象须是资料或信息，饭菜是实物，无法转换成数字形式，只能把做法记下来。"}, {"text": "他把这块石头数字化成了雕像。", "explanation": "这里应该用〈雕刻〉。数字化指转换为数字形式，不能用来指把石头雕成雕像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字化", "is_correct": true, "explanation": "正确：“老师把课本数字化”指把课本转成电子形式，学生才能用平板阅读，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是破坏纸张的动作，与“学生用平板就能读”的处理结果不合，句意讲不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：课本烧掉后就无法阅读，与“学生用平板就能读”的结果矛盾，句意讲不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象须是饮品，不能带“课本”作宾语，句子讲不通。"}], "explanations": {"数字化": "正确：“老师把课本数字化”指把课本转成电子形式，学生才能用平板阅读，符合句意。", "撕": "语义：撕是破坏纸张的动作，与“学生用平板就能读”的处理结果不合，句意讲不通。", "烧": "语义：课本烧掉后就无法阅读，与“学生用平板就能读”的结果矛盾，句意讲不通。", "喝": "搭配：“喝”的对象须是饮品，不能带“课本”作宾语，句子讲不通。"}, "sentence_index": 6, "correct_answer": "数字化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把坏掉的椅子数字化好了。", "explanation": "这里应该用〈修理〉。数字化指转换为数字形式，不指修好实物。"}, {"text": "他把两人的友情数字化了。", "explanation": "这里应该用〈记住〉。数字化的对象须是资料或信息，友情是情感，无法转换成数字形式，只能记在心里。"}, {"text": "这间屋子用鲜花数字化了一下。", "explanation": "这里应该用〈装饰〉。数字化指转换为数字形式，不指用鲜花美化房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用这些老照片数字化了。", "corrected_sentence": "我们把这些老照片数字化了。", "error_description": "介词错误。“把”引出被处理的对象，“用”不能引出“数字化”的对象，应说“把这些老照片数字化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "图书馆正在把旧报纸数字化了。", "corrected_sentence": "图书馆正在把旧报纸数字化。", "error_description": "体标错误。“正在”表示动作正在进行，不能与表示完成的“了”同用。应说“图书馆正在把旧报纸数字化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '130f335a-1162-4cda-8e52-2b2b8a232d05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
