INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21756, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们用来买卖东西或让钱变多的一种工具，比如借钱的合同或股票。", "primary_collocate": null, "pronunciation": "jīn róng gōng jù", "ipa": "tɕin˥ ʐʊŋ˧˥ kʊŋ˥ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "股票是一种金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借钱的合同也是金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用金融工具让钱变多了。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人用金融工具来投资。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一些金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行有很多种金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同是一种金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校学过怎么用金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解不同的金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基金和债券都是常见的金融工具。", "target_word": "金融工具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衍生金融工具", "label": "复合"}, {"form": "新型金融工具", "label": "复合"}], "register": "书面", "sense_fingerprint": "借钱的合同、股票等让钱变多的凭证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21756, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金融工具", "is_correct": true, "explanation": "填入“金融工具”：股票是一种用于买卖或让钱增值的金融工具，与句意相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：股票是金融凭证，不是乐器，“是一种乐器”与句意不符。"}, {"text": "水果", "is_correct": false, "explanation": "语义：股票不是水果，无法归为“一种水果”。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：“典籍”是古代书籍的书面词，与“股票”不能归为一类，语体也不协调。"}], "explanations": {"金融工具": "填入“金融工具”：股票是一种用于买卖或让钱增值的金融工具，与句意相符。", "乐器": "语义：股票是金融凭证，不是乐器，“是一种乐器”与句意不符。", "水果": "语义：股票不是水果，无法归为“一种水果”。", "典籍": "语域：“典籍”是古代书籍的书面词，与“股票”不能归为一类，语体也不协调。"}, "sentence_index": 0, "correct_answer": "金融工具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店员用金融工具结账。", "explanation": "这里应该用〈收银机〉。金融工具指股票、借款合同等金融凭证，不是用来结账的机器。"}, {"text": "他用金融工具修好了自行车。", "explanation": "这里应该用〈扳手〉等修理工具。“金融工具”指股票、借款合同等金融凭证，不能用来修车。"}, {"text": "木匠用金融工具做桌子。", "explanation": "这里应该用〈锯子〉等实体器具。“金融工具”指股票、借款合同等金融凭证，不能用来做桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21756, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金融工具", "is_correct": true, "explanation": "填入“金融工具”：借钱的合同属于金融工具，“是一种金融工具”句意成立。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：合同是法律凭证，不是房屋，“是一种房屋”与句意不符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：合同不是课本，句子讲的是金融性质的凭证。"}, {"text": "红色", "is_correct": false, "explanation": "体貌：“红色”描述颜色，合同是文件，不能用颜色作为类别。"}], "explanations": {"金融工具": "填入“金融工具”：借钱的合同属于金融工具，“是一种金融工具”句意成立。", "房屋": "语义：合同是法律凭证，不是房屋，“是一种房屋”与句意不符。", "课本": "语义：合同不是课本，句子讲的是金融性质的凭证。", "红色": "体貌：“红色”描述颜色，合同是文件，不能用颜色作为类别。"}, "sentence_index": 6, "correct_answer": "金融工具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店用金融工具称重。", "explanation": "这里应该用〈秤〉。金融工具指用于买卖或增值的金融凭证，不能用来称重。"}, {"text": "她用金融工具联系朋友。", "explanation": "这里应该用〈电话〉。金融工具是金融凭证，不能用来联系朋友。"}, {"text": "基金和债券都是一条常见的金融工具。", "explanation": "这里应该用〈种〉。“条”多用于细长的东西，金融工具要用“种”或“类”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21756, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一台金融工具让钱变多了。", "corrected_sentence": "他用一种金融工具让钱变多了。", "error_description": "量词错误：“金融工具”应用“种”，“台”多用于机器、电器，这里说“一台”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21756, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想了解金融工具们的用途。", "corrected_sentence": "我想了解金融工具的用途。", "error_description": "“们”只用于指人的名词，“金融工具”指事物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21758, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反义：“反对”与“支持”（同意并帮助）相对，表示不同意并加以阻挠。"}, {"text": "收藏", "is_correct": false, "explanation": "与“支持”无反义或近义关系，“收藏”指把东西保存起来。"}, {"text": "整理", "is_correct": false, "explanation": "与“支持”无反义或近义关系，“整理”指把杂乱的东西归置好。"}, {"text": "观察", "is_correct": false, "explanation": "与“支持”无反义或近义关系，“观察”指仔细察看。"}], "correct_answer": "反对", "explanations": {"反对": "反义：“反对”与“支持”（同意并帮助）相对，表示不同意并加以阻挠。", "收藏": "与“支持”无反义或近义关系，“收藏”指把东西保存起来。", "整理": "与“支持”无反义或近义关系，“整理”指把杂乱的东西归置好。", "观察": "与“支持”无反义或近义关系，“观察”指仔细察看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
