INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21758, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支持就是同意别人，并帮助他。", "primary_collocate": null, "pronunciation": "zhī chí", "ipa": "ʈʂɻ̩˥ ʈʂʰɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "爸爸妈妈都支持我学音乐。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你一直支持我。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们支持他开一家小店。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我支持你的决定。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都支持这个好主意。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很支持丈夫的工作。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球迷们来现场支持自己的球队。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师支持我们参加比赛。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我会一直支持着你。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想做就做，我们都支持。", "target_word": "支持", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支持了", "label": "体标"}, {"form": "支持着", "label": "体标"}, {"form": "支持过", "label": "体标"}], "register": "中性", "sense_fingerprint": "同意并帮助某人或某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e27744d-182f-47c3-87f2-2fd95c884f94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21758, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案，意思是同意别人并帮助他。"}, {"text": "知识", "is_correct": false, "explanation": "zhī shí 与 zhī chí 的第二音节声母不同（sh 与 ch），意思是知识。"}, {"text": "直尺", "is_correct": false, "explanation": "两个音节声调都不同（zhí chǐ 与 zhī chí），意思是量直线的尺子。"}, {"text": "指斥", "is_correct": false, "explanation": "两个音节声调都不同（zhǐ chì 与 zhī chí），意思是指出错误并加以斥责。"}, {"text": "智齿", "is_correct": false, "explanation": "两个音节声调都不同（zhì chǐ 与 zhī chí），意思是最里面长出的一对大牙。"}], "explanations": {"支持": "正确答案，意思是同意别人并帮助他。", "知识": "zhī shí 与 zhī chí 的第二音节声母不同（sh 与 ch），意思是知识。", "直尺": "两个音节声调都不同（zhí chǐ 与 zhī chí），意思是量直线的尺子。", "指斥": "两个音节声调都不同（zhǐ chì 与 zhī chí），意思是指出错误并加以斥责。", "智齿": "两个音节声调都不同（zhì chǐ 与 zhī chí），意思是最里面长出的一对大牙。"}, "sentence_index": null, "correct_answer": "支持"}, "level_3": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案。“支持”表示同意并帮助，与“我学音乐”的语境相符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”的对象是语言或文字，“学音乐”不能被翻译。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”搭配器物，不能带“我学音乐”作宾语。"}, {"text": "复制", "is_correct": false, "explanation": "配价：“复制”要求宾语是可被复制的具体事物，“学音乐”不符合。"}], "explanations": {"支持": "正确答案。“支持”表示同意并帮助，与“我学音乐”的语境相符。", "翻译": "语义：“翻译”的对象是语言或文字，“学音乐”不能被翻译。", "修理": "搭配：“修理”搭配器物，不能带“我学音乐”作宾语。", "复制": "配价：“复制”要求宾语是可被复制的具体事物，“学音乐”不符合。"}, "sentence_index": 0, "correct_answer": "支持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台手机支持无线充电。", "explanation": "这里的“支持”指具备某种功能，主语是手机，不是同意并帮助某人。"}, {"text": "这座桥的桥墩支持着整座大桥。", "explanation": "这里的“支持”指支撑、承受重量，是物理意义，不是同意并帮助某人。"}, {"text": "我的体力已经支持不住了。", "explanation": "这里的“支持”指勉强撑住，不是同意并帮助某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支持", "is_correct": true, "explanation": "正确答案。“支持”表示拥护、帮助，与“球队”搭配自然。"}, {"text": "乘坐", "is_correct": false, "explanation": "搭配：“乘坐”后接交通工具，不接“球队”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“球队”不能被吃。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”要求受事为衣物等可洗之物，“球队”不符合。"}], "explanations": {"支持": "正确答案。“支持”表示拥护、帮助，与“球队”搭配自然。", "乘坐": "搭配：“乘坐”后接交通工具，不接“球队”作宾语。", "吃": "语义：“吃”的对象是食物，“球队”不能被吃。", "洗": "配价：“洗”要求受事为衣物等可洗之物，“球队”不符合。"}, "sentence_index": 6, "correct_answer": "支持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "靠这点收入，他还要支持一家五口。", "explanation": "这里的“支持”指供养、维持生活，不是同意并帮助某人。"}, {"text": "这项研究的数据支持了这一结论。", "explanation": "这里的“支持”指用事实证明结论正确，不是同意并帮助某人。"}, {"text": "这堵墙支持不了整座房子的重量。", "explanation": "这里的“支持”指承受重量，是物理意义，不是同意并帮助某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
