INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21760, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地缘是指不同地方因为位置靠近而有的关系。", "primary_collocate": null, "pronunciation": "dì yuán", "ipa": "ti˥˩ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这两个村子地缘关系很近，常常来往。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地缘相近的国家，文化常常也很像。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是邻居，有地缘上的联系。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国和日本有很深的地缘关系。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为地缘相近，我们周末常去对方的城市玩。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地缘不同于血缘，它来自地理位置相近。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地缘让这几个小国走得很近。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司选这里，是看中了地缘上的方便。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个地区地缘相连，天气也差不多。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上讲了亚洲国家的地缘特点。", "target_word": "地缘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地緣", "label": "繁体"}, {"form": "地缘关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "地缘:不同地方因位置靠近而有的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fcdeda5-d8c7-49c0-8c4a-eb7c9e6fe46d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地缘", "is_correct": true, "explanation": "地缘关系：不同地方因位置靠近而有的关系，与“两个村子……常常来往”相符。"}, {"text": "师徒", "is_correct": false, "explanation": "语义：“师徒关系”指传授技艺的师生联系，两个村子之间不存在这种关系。"}, {"text": "恋爱", "is_correct": false, "explanation": "语义：“恋爱关系”只存在于两个人之间，不能用来形容两个村子。"}, {"text": "上下级", "is_correct": false, "explanation": "搭配：“上下级关系”说的是组织内部的隶属，与两个村子之间的往来不搭配。"}], "explanations": {"地缘": "地缘关系：不同地方因位置靠近而有的关系，与“两个村子……常常来往”相符。", "师徒": "语义：“师徒关系”指传授技艺的师生联系，两个村子之间不存在这种关系。", "恋爱": "语义：“恋爱关系”只存在于两个人之间，不能用来形容两个村子。", "上下级": "搭配：“上下级关系”说的是组织内部的隶属，与两个村子之间的往来不搭配。"}, "sentence_index": 0, "correct_answer": "地缘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在班里的地缘很好，大家都愿意和他玩。", "explanation": "这里应该用〈人缘〉。人缘指人与人之间的受欢迎程度，地缘指地方之间的关系。"}, {"text": "这台电脑的地缘很好，运行很快。", "explanation": "这里应该用〈性能〉。地缘指地方之间的关系，电脑的运行速度应说性能。"}, {"text": "这座城市的地缘很平坦。", "explanation": "这里应该用〈地势〉。地缘是关系，不指地形地貌，说地面的起伏要用地势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地缘", "is_correct": true, "explanation": "地缘：地理位置靠近带来的关系，正是句中让几个小国走近的原因。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无法使国家之间拉近距离，与句中的因果关系不符。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”指学习的费用，不能作为让国家“走得很近”的原因。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能使几个国家走近，与“走得很近”的原因不符。"}], "explanations": {"地缘": "地缘：地理位置靠近带来的关系，正是句中让几个小国走近的原因。", "天气": "语义：天气无法使国家之间拉近距离，与句中的因果关系不符。", "学费": "搭配：“学费”指学习的费用，不能作为让国家“走得很近”的原因。", "手机": "语义：手机不能使几个国家走近，与“走得很近”的原因不符。"}, "sentence_index": 6, "correct_answer": "地缘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个地区的地缘很干燥，几乎不下雨。", "explanation": "这里应该用〈气候〉。地缘指地方之间的关系，不指天气与湿度，说干燥、下雨要用气候。"}, {"text": "这两件衣服的地缘很好，颜色很相配。", "explanation": "这里应该用〈搭配〉。地缘指地方之间的关系，衣服之间的协调应说搭配。"}, {"text": "这片地缘的文化很丰富。", "explanation": "这里应该用〈地域〉。地缘是关系，不指地方本身，说一片地方的文化要用地域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个小国之间有着一条密切的地缘关系。", "corrected_sentence": "这两个小国之间有着一种密切的地缘关系。", "error_description": "错误在于“地缘关系”前的量词。“地缘关系”是抽象的关系，量词应用“种”，不能用细长条状的“条”，应说“一种密切的地缘关系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个国家之间有一张很深的地缘关系。", "corrected_sentence": "这两个国家之间有一种很深的地缘关系。", "error_description": "错误在于“地缘关系”前的量词。“张”用于纸、桌子等平面的东西，“地缘关系”是抽象的关系，量词应用“种”，说“一种很深的地缘关系”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9646aff6-57d3-436e-a40a-16889b4eab85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
