INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21772, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "绕着行星（如地球）运行的天体，如月亮；也指人造的卫星。", "primary_collocate": null, "pronunciation": "wèi xīng", "ipa": "weɪ˥˩ ɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "月亮是绕着地球转的卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里我看见天上有一颗卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球只有一颗卫星，就是月亮。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那颗卫星一直绕着地球转。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我：月亮是不是地球的卫星？", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上画了地球和它的卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宇航员在太空里修理了一颗卫星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把一颗新卫星送上了天。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗卫星转一圈要一个半小时。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天上的卫星看起来像一颗小星星。", "target_word": "卫星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "人造卫星", "label": "复合"}, {"form": "衛星", "label": "繁体"}], "register": "中性", "sense_fingerprint": "绕行星运行的天体或人造物，如月亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行星", "is_correct": false, "explanation": "语义：行星绕太阳运行，月亮绕的是地球，月亮不是行星。"}, {"text": "卫星", "is_correct": true, "explanation": "“卫星”指绕着地球转的天体，与句中“绕着地球转”相符。"}, {"text": "恒星", "is_correct": false, "explanation": "语义：恒星自身发光，月亮本身不发光，不能说是恒星。"}, {"text": "流星", "is_correct": false, "explanation": "语义：流星是流星体进入大气层时发光的现象，不绕着行星转，句意不通。"}], "explanations": {"行星": "语义：行星绕太阳运行，月亮绕的是地球，月亮不是行星。", "卫星": "“卫星”指绕着地球转的天体，与句中“绕着地球转”相符。", "恒星": "语义：恒星自身发光，月亮本身不发光，不能说是恒星。", "流星": "语义：流星是流星体进入大气层时发光的现象，不绕着行星转，句意不通。"}, "sentence_index": 0, "correct_answer": "卫星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳是离地球最近的卫星。", "explanation": "这里应该用〈恒星〉。太阳是恒星，卫星是绕行星转的天体，不能用来称呼太阳。"}, {"text": "夜空中最亮的卫星是金星。", "explanation": "这里应该用〈行星〉。金星绕太阳转，是行星，不是卫星。"}, {"text": "我们乘坐卫星去月球旅行。", "explanation": "这里应该用〈飞船〉。卫星是绕着地球转的东西，不载人，去月球要乘坐〈飞船〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陨石", "is_correct": false, "explanation": "语义：陨石是落到地面的流星体残骸，宇航员不会在太空中“修理”它。"}, {"text": "卫星", "is_correct": true, "explanation": "“卫星”指人造卫星时可以修理，句中“宇航员修理”指的是人造卫星，量词“颗”可用。"}, {"text": "彗星", "is_correct": false, "explanation": "语义：彗星是自然形成的天体，不是人造物，宇航员不会修理它。"}, {"text": "星星", "is_correct": false, "explanation": "配价：“修理”的对象应是可修复的人造物，“星星”不能作它的宾语。"}], "explanations": {"陨石": "语义：陨石是落到地面的流星体残骸，宇航员不会在太空中“修理”它。", "卫星": "“卫星”指人造卫星时可以修理，句中“宇航员修理”指的是人造卫星，量词“颗”可用。", "彗星": "语义：彗星是自然形成的天体，不是人造物，宇航员不会修理它。", "星星": "配价：“修理”的对象应是可修复的人造物，“星星”不能作它的宾语。"}, "sentence_index": 6, "correct_answer": "卫星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球是太阳系里的一颗卫星。", "explanation": "这里应该用〈行星〉。地球绕太阳转，本身是行星，不绕着其他行星转，所以不是卫星。"}, {"text": "卫星拖着长长的尾巴飞过天空。", "explanation": "这里应该用〈彗星〉。彗星有彗尾，卫星没有彗尾。"}, {"text": "黑洞是一种神秘的卫星。", "explanation": "这里应该用〈天体〉。卫星特指绕行星转的天体，黑洞不绕行星转，不能称为卫星。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们发射了一条卫星。", "corrected_sentence": "我们发射了一颗卫星。", "error_description": "错误：“一条卫星”；正确：“一颗卫星”。卫星用量词“颗”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人们把卫星们送上了天。", "corrected_sentence": "人们把卫星送上了天。", "error_description": "错误：“卫星们”；正确：“卫星”。“们”不用于事物名词，卫星后不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减弱", "is_correct": true, "explanation": "反义：“增强”指变得更强，“减弱”指变得更弱，二者在此义上相对。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指悠闲地走路，与“增强”没有反义关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清洁，与“增强”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”指进食，与“增强”没有反义关系。"}], "correct_answer": "减弱", "explanations": {"减弱": "反义：“增强”指变得更强，“减弱”指变得更弱，二者在此义上相对。", "散步": "无关：“散步”指悠闲地走路，与“增强”没有反义关系。", "打扫": "无关：“打扫”指清洁，与“增强”没有反义关系。", "吃饭": "无关：“吃饭”指进食，与“增强”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
