INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更有力气或更厉害。", "primary_collocate": null, "pronunciation": "zēng qiáng", "ipa": "tsəŋ˥ tɕʰjɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "每天跑步能增强抵抗力。", "target_word": "增强", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次比赛增强了我的信心。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要增强安全意识。", "target_word": "增强", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多吃水果可以增强体力。", "target_word": "增强", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好朋友能增强我们的力量。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队增强了防守。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办法可以增强记忆力。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要增强体质。", "target_word": "增强", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天天锻炼，他的体力增强了。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动增强了大家的合作意识。", "target_word": "增强", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "增强了", "label": "体标"}, {"form": "增强过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，指使体力、信心、能力等变得更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7679ce6-7410-49f6-bfdd-e5891d0d533a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增强", "is_correct": true, "explanation": "正确。“增强”表示使抵抗力变得更强，与“每天跑步”搭配，符合句意。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”的对象应是人，不能安慰抵抗力。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化外表，与增强抵抗力无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是物品，不能搬运抵抗力。"}], "explanations": {"增强": "正确。“增强”表示使抵抗力变得更强，与“每天跑步”搭配，符合句意。", "安慰": "语义：“安慰”的对象应是人，不能安慰抵抗力。", "装饰": "语义：“装饰”指美化外表，与增强抵抗力无关。", "搬运": "搭配：“搬运”的对象是物品，不能搬运抵抗力。"}, "sentence_index": 0, "correct_answer": "增强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年这个城市的人口增强了很多。", "explanation": "这里应该用〈增加〉。“增强”用于力量、体质、能力等性质，人口等数量要用〈增加〉。"}, {"text": "这个房间增强了一张新沙发。", "explanation": "这里应该用〈增添〉。“增强”指使某种性质更强，不用于增加具体的物品。"}, {"text": "这次比赛增强了我们的成绩。", "explanation": "这里应该用〈提高〉。“增强”用于力量、体质等，成绩、水平要用〈提高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "增强", "is_correct": true, "explanation": "正确。“增强”表示使记忆力变得更强，与“这个办法可以”搭配，符合句意。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能驾驶记忆力。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能烹饪记忆力。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：“洗涤”指清洗物品，与记忆力无关，句子不通。"}], "explanations": {"增强": "正确。“增强”表示使记忆力变得更强，与“这个办法可以”搭配，符合句意。", "驾驶": "搭配：“驾驶”的对象是车辆，不能驾驶记忆力。", "烹饪": "搭配：“烹饪”的对象是食物，不能烹饪记忆力。", "洗涤": "语义：“洗涤”指清洗物品，与记忆力无关，句子不通。"}, "sentence_index": 6, "correct_answer": "增强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次锻炼增强了他的体重。", "explanation": "语义：“增强”指使力量、体质、能力等变得更强，体重的增减要说〈增加〉。"}, {"text": "我们增强了工作的速度。", "explanation": "这里应该用〈加快〉。“增强”用于力量、能力等，速度要用〈加快〉。"}, {"text": "这次假期增强了两天。", "explanation": "这里应该用〈延长〉。“增强”不用于时间，延长时间要用〈延长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训能增强了大家的沟通能力。", "corrected_sentence": "这次培训能增强大家的沟通能力。", "error_description": "错误：“能”表示能力，“了”表示完成，二者不能同时用在动词“增强”上。应说“这次培训能增强大家的沟通能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "多运动可以很增强体质。", "corrected_sentence": "多运动可以增强体质。", "error_description": "错误：副词“很”放在了动词“增强”前面。“很”一般只修饰形容词，这里应直接说“可以增强体质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97eb84d6-0adc-4532-a2d8-0ae9d29b69f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
