INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买东西时给钱。", "primary_collocate": null, "pronunciation": "zhī fù", "ipa": "tʂɻ̩⁵⁵ fu⁵¹", "syllable_count": 2, "sentences": [{"text": "买东西时，我用手机支付。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "顾客可以用现金支付。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在超市，你怎么支付？", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家小店只能用现金支付。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在收银台支付了水果钱。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我忘了带钱，不能支付。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请扫码支付。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈用银行卡支付了衣服的钱。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买完东西，你先去那边支付。", "target_word": "支付", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拿出钱包，准备支付。", "target_word": "支付", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "支付了", "label": "体标"}, {"form": "支付方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "购物时付款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21776, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "支付", "is_correct": true, "explanation": "正确：支付，买东西时把钱付给店家，与「我用手机」相符。"}, {"text": "收钱", "is_correct": false, "explanation": "语义：「收钱」是接收钱款，指卖方，与「我用手机」的顾客身份不符。"}, {"text": "找零", "is_correct": false, "explanation": "语义：「找零」是找回多余的钱，不是付款。"}, {"text": "讨价还价", "is_correct": false, "explanation": "搭配：「讨价还价」针对价格，不说用手机讨价还价。"}], "explanations": {"支付": "正确：支付，买东西时把钱付给店家，与「我用手机」相符。", "收钱": "语义：「收钱」是接收钱款，指卖方，与「我用手机」的顾客身份不符。", "找零": "语义：「找零」是找回多余的钱，不是付款。", "讨价还价": "搭配：「讨价还价」针对价格，不说用手机讨价还价。"}, "sentence_index": 0, "correct_answer": "支付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他支付了三天的时间来准备考试。", "explanation": "这里应该用〈花费〉。支付只用于付钱，时间要说花费。"}, {"text": "妈妈支付了我一个好的建议。", "explanation": "这里应该用〈提供〉。支付只用于钱款，建议要说提供。"}, {"text": "她支付了一次感冒，很快就好了。", "explanation": "这里应该用〈得〉。支付只用于付钱，感冒要说得，不能说支付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支付", "is_correct": true, "explanation": "正确：支付，请顾客扫码付款。"}, {"text": "撕毁", "is_correct": false, "explanation": "语义：「撕毁」是撕坏，与扫码付款无关。"}, {"text": "洗净", "is_correct": false, "explanation": "搭配：「洗净」用于清洗物体，不用于扫码。"}, {"text": "切开", "is_correct": false, "explanation": "搭配：「切开」用于切割物体，不适用于扫码。"}], "explanations": {"支付": "正确：支付，请顾客扫码付款。", "撕毁": "语义：「撕毁」是撕坏，与扫码付款无关。", "洗净": "搭配：「洗净」用于清洗物体，不用于扫码。", "切开": "搭配：「切开」用于切割物体，不适用于扫码。"}, "sentence_index": 6, "correct_answer": "支付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她拿出钱包，准备支付这个问题。", "explanation": "这里应该用〈研究〉。支付只用于钱款，问题要说研究或解决。"}, {"text": "她拿出钱包，准备支付这份责任。", "explanation": "这里应该用〈承担〉。支付只用于付钱，责任要说承担。"}, {"text": "她拿出钱包，准备支付这个任务。", "explanation": "这里应该用〈完成〉。支付只用于钱款，任务要说完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚刚用信用卡支付着费用。", "corrected_sentence": "他刚刚用信用卡支付了费用。", "error_description": "体标错误：「刚刚」说明动作已经完成，应用完成体「了」，不能用表示持续的「着」，正确说法是「支付了费用」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在收银台支付了过一笔费用。", "corrected_sentence": "他在收银台支付过一笔费用。", "error_description": "体标错误：「了」与「过」不能同时用在同一动词后，「他在收银台支付了过一笔费用」应去掉「了」，正确说法是「支付过一笔费用」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
