INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21780, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "物体让光透过，能使人看清后面东西的程度。", "primary_collocate": null, "pronunciation": "tòu míng dù", "ipa": "/tʰou˥˩ miŋ˧˥ tu˥˩/", "syllable_count": 3, "sentences": [{"text": "这块玻璃的透明度很高。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水越干净，透明度越高。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料的透明度不太好。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖水的透明度很低，看不到底。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你检查一下这张膜的透明度。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子的透明度高，能看到里面的茶。", "target_word": "透明度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户的透明度不够，房间有点暗。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玻璃的透明度会影响房间的光线。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想知道海水的透明度有多高。", "target_word": "透明度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张纸的透明度太低，看不清后面的字。", "target_word": "透明度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "透明", "label": "词根"}], "register": "中性", "sense_fingerprint": "物体或液体让光透过、能看清后面东西的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明度", "is_correct": true, "explanation": "正确：“透明度”指物体让光透过的程度，与“这块玻璃的……很高”搭配。"}, {"text": "味道", "is_correct": false, "explanation": "语义：玻璃没有味道，“这块玻璃的味道很高”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不用“高”来形容，应说“深”或“浅”。"}, {"text": "气味", "is_correct": false, "explanation": "语义：玻璃没有气味，“很高”不能用来形容它的气味。"}], "explanations": {"透明度": "正确：“透明度”指物体让光透过的程度，与“这块玻璃的……很高”搭配。", "味道": "语义：玻璃没有味道，“这块玻璃的味道很高”说不通。", "颜色": "搭配：“颜色”不用“高”来形容，应说“深”或“浅”。", "气味": "语义：玻璃没有气味，“很高”不能用来形容它的气味。"}, "sentence_index": 0, "correct_answer": "透明度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的透明度很高，灯都亮着。", "explanation": "这里应该用〈亮度〉。透明度指光透过的程度，说房间明亮程度要用“亮度”。"}, {"text": "这张照片的透明度很高，人脸看得清楚。", "explanation": "这里应该用〈清晰度〉。透明度说的是物体透光的程度，照片清楚与否要用“清晰度”。"}, {"text": "这块玻璃的透明度很大，很难打碎。", "explanation": "这里应该用〈厚度〉。透明度与能否打碎无关，说玻璃厚、结实要用“厚度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明度", "is_correct": true, "explanation": "正确：“透明度”指透光的程度，与“窗户的……不够，房间有点暗”的语境相符。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：窗户的硬度不够并不会使房间变暗，句中因果关系不成立。"}, {"text": "重量", "is_correct": false, "explanation": "语义：窗户的重量与房间的明暗没有关系，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”一般用于人或生物，不说“窗户的年龄不够”。"}], "explanations": {"透明度": "正确：“透明度”指透光的程度，与“窗户的……不够，房间有点暗”的语境相符。", "硬度": "语义：窗户的硬度不够并不会使房间变暗，句中因果关系不成立。", "重量": "语义：窗户的重量与房间的明暗没有关系，句子说不通。", "年龄": "搭配：“年龄”一般用于人或生物，不说“窗户的年龄不够”。"}, "sentence_index": 6, "correct_answer": "透明度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的透明度很大，分量很足。", "explanation": "这里应该用〈重量〉。透明度指光透过的程度，说苹果分量足要用“重量”。"}, {"text": "房间的透明度太高，要开除湿机。", "explanation": "这里应该用〈湿度〉。透明度与潮湿程度无关，房间潮湿要用“湿度”。"}, {"text": "这根绳子的透明度很长，可以绕两圈。", "explanation": "这里应该用〈长度〉。透明度不能说长短，绳子的长短要用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块塑料的透明很好，能看到里面的东西。", "corrected_sentence": "这块塑料的透明度很好，能看到里面的东西。", "error_description": "错误：“的透明”。“透明”是形容词，不能直接作“的”后面的中心语；应加上“度”，说“透明度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这扇窗户很透明度很好，屋里很亮。", "corrected_sentence": "这扇窗户的透明度很好，屋里很亮。", "error_description": "错误：“很透明度”。“很”是程度副词，不能直接修饰名词“透明度”，应把“很”改为“的”，说“窗户的透明度很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
