INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你看东西时，眼睛看的方向和位置。", "primary_collocate": null, "pronunciation": "shì jiǎo", "ipa": "ʂʅ˥˩ tɕjau˨˩˦", "syllable_count": 2, "sentences": [{"text": "从飞机窗口往下看，视角很特别。", "target_word": "视角", "complexity_tier": "T3", "furigana": "cóng fēi jī chuāng kǒu wǎng xià kàn, shì jiǎo hěn tè bié.", "sentence_source": "generated"}, {"text": "这张照片的视角很特别。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把相机放低，换了个视角拍这只小猫。", "target_word": "视角", "complexity_tier": "T3", "furigana": "wǒ bǎ xiàng jī fàng dī, huàn le ge shì jiǎo pāi zhè zhī xiǎo māo.", "sentence_source": "generated"}, {"text": "摄影师选了一个很低的视角。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在桥上，视角正好能看到整条河。", "target_word": "视角", "complexity_tier": "T3", "furigana": "tā zhàn zài qiáo shàng, shì jiǎo zhèng hǎo néng kàn dào zhěng tiáo hé.", "sentence_source": "generated"}, {"text": "从树上往下看，视角很高，能看到整个公园。", "target_word": "视角", "complexity_tier": "T3", "furigana": "cóng shù shàng wǎng xià kàn, shì jiǎo hěn gāo, néng kàn dào zhěng gè gōng yuán.", "sentence_source": "generated"}, {"text": "站在山顶上，视角完全不一样了。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐在前排，视角比较好。", "target_word": "视角", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们从上面的视角看这座城市。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏的视角可以自己换。", "target_word": "视角", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "视角", "label": "词根"}], "register": "中性", "sense_fingerprint": "看东西或想问题时所站的位置和角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视角", "is_correct": true, "explanation": "正确：“视角”指观察事物的位置和方向，与“从飞机窗口往下看”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“往下看”只能看到东西，看不到味道，句子说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“往下看”是视觉行为，不能用它来感知声音。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“特别”通常形容事物的特点，不说“年龄很特别”。"}], "explanations": {"视角": "正确：“视角”指观察事物的位置和方向，与“从飞机窗口往下看”相符。", "味道": "语义：“往下看”只能看到东西，看不到味道，句子说不通。", "声音": "语义：“往下看”是视觉行为，不能用它来感知声音。", "年龄": "搭配：“特别”通常形容事物的特点，不说“年龄很特别”。"}, "sentence_index": 0, "correct_answer": "视角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的视角很温柔，让人很舒服。", "explanation": "这里应该用〈目光〉。目光可以温柔，视角指观察的位置和方向，不能用“温柔”形容。"}, {"text": "他的视角很坚定，从不动摇。", "explanation": "这里应该用〈立场〉。立场可以坚定，视角只是观察的角度，不能用“坚定”来形容。"}, {"text": "我家和学校之间的视角很远，要坐一个小时车。", "explanation": "这里应该用〈距离〉。视角指观察的位置和方向，两地之间的远近要用“距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视角", "is_correct": true, "explanation": "正确：“视角”指观察的位置和方向，站到山顶上，看东西的位置变了。"}, {"text": "名字", "is_correct": false, "explanation": "语义：站到山顶上不会改变人的名字，句子说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：站的位置不会让年龄改变，句子说不通。"}, {"text": "生日", "is_correct": false, "explanation": "语义：站在哪里和生日没有关系，句子说不通。"}], "explanations": {"视角": "正确：“视角”指观察的位置和方向，站到山顶上，看东西的位置变了。", "名字": "语义：站到山顶上不会改变人的名字，句子说不通。", "年龄": "语义：站的位置不会让年龄改变，句子说不通。", "生日": "语义：站在哪里和生日没有关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "视角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个三角形有一个很大的视角。", "explanation": "这里应该用〈角度〉。视角指观察事物的位置和方向，不用来指几何图形中的角。"}, {"text": "他对工作的视角很认真。", "explanation": "这里应该用〈态度〉。视角不能用“认真”来形容，人对工作的看法和行为倾向应说“态度”。"}, {"text": "他的视角落在窗外的树上。", "explanation": "这里应该用〈视线〉。视线可以“落在”某处，视角是观察的角度，不能用“落”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们换只视角拍这座山，会更好看。", "corrected_sentence": "我们换个视角拍这座山，会更好看。", "error_description": "错误：“只视角”。“只”多用于动物等，“视角”应用量词“个”，说“换个视角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影用孩子地视角讲故事。", "corrected_sentence": "这部电影用孩子的视角讲故事。", "error_description": "错误：“孩子地视角”。修饰名词应用结构助词“的”，不能用“地”，应说“孩子的视角”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
