INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "遥感就是用机器在远处看东西，不用碰到它。", "primary_collocate": null, "pronunciation": "yáo gǎn", "ipa": "jaʊ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "遥感能在很远的地方看清地面。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，遥感不用走到山上就能看山。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们用遥感看这座城市有多大。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机和卫星可以用遥感拍到大海。", "target_word": "遥感", "complexity_tier": "T3", "furigana": "fēi jī hé wèixīng kěyǐ yòng yáogǎn pāi dào dà hǎi", "sentence_source": "generated"}, {"text": "有了遥感，农民不用下地就能看到庄稼。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遥感不用碰到东西，就能知道它的样子。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是用遥感找地下的水。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的地理课上，我们学了遥感。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨前，气象站用遥感看天上的云。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遥感让人在远处看见森林里的火。", "target_word": "遥感", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遥感技术", "label": "复合"}, {"form": "遥感卫星", "label": "复合"}], "register": "中性", "sense_fingerprint": "遥感：用机器在远处看东西，不用碰到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af58cd74-a966-4809-b2bd-5cb92529248a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”是远距离探测的技术，可以作主语，说明它能在远处看清地面。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：“乐趣”是愉快的感受，不能在远处看清地面。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的外貌，不能做看清地面的主语。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性格，与“看清地面”的功能无关。"}], "explanations": {"遥感": "“遥感”是远距离探测的技术，可以作主语，说明它能在远处看清地面。", "乐趣": "语义：“乐趣”是愉快的感受，不能在远处看清地面。", "长相": "体貌：“长相”指人的外貌，不能做看清地面的主语。", "脾气": "语义：“脾气”指性格，与“看清地面”的功能无关。"}, "sentence_index": 0, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用遥感听音乐。", "explanation": "这里应该用〈收音机〉。“遥感”是远距离探测物体信息的技术，不能用来听音乐；听广播要用收音机。"}, {"text": "我用遥感换了一个台。", "explanation": "这里应该用〈遥控〉。遥感是探测技术，不是换台的工具。"}, {"text": "我的遥感很懂事。", "explanation": "这里应该用〈孩子〉。“遥感”是技术名称，不能用来形容人；说人懂事要用“孩子”等人物名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥感", "is_correct": true, "explanation": "“遥感”是用技术探测的手段，正好说明工作内容是找地下的水。"}, {"text": "好奇心", "is_correct": false, "explanation": "语义：“好奇心”是心理状态，不能用来找地下的水。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，不是找水的手段。"}, {"text": "酒量", "is_correct": false, "explanation": "搭配：“用……找水”的手段应是技术或工具，“酒量”不搭配。"}], "explanations": {"遥感": "“遥感”是用技术探测的手段，正好说明工作内容是找地下的水。", "好奇心": "语义：“好奇心”是心理状态，不能用来找地下的水。", "风景": "语义：“风景”指景色，不是找水的手段。", "酒量": "搭配：“用……找水”的手段应是技术或工具，“酒量”不搭配。"}, "sentence_index": 6, "correct_answer": "遥感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用遥感看家里有没有小偷。", "explanation": "这里应该用〈监控〉。“遥感”是远距离探测物体信息的技术，多用于大范围的地表观测，不用于家里防盗；防盗要用“监控”。"}, {"text": "她对远方的朋友有很强的遥感。", "explanation": "这里应该用〈感应〉。“遥感”是远距离探测的技术名词，不指人对远方的感觉；说人与人之间的感觉要用“感应”。"}, {"text": "这台遥感能帮我们做饭。", "explanation": "这里应该用〈炉灶〉。“遥感”是远距离探测的技术，不能用来做饭；做饭要用炉灶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把遥感观察远处的山。", "corrected_sentence": "我们用遥感观察远处的山。", "error_description": "错误：“把遥感”；正确：“用遥感”。“遥感”表示观察的手段，要用介词“用”引出，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的工作是用一台遥感技术找水。", "corrected_sentence": "他的工作是用一种遥感技术找水。", "error_description": "错误：“一台遥感技术”；正确：“一种遥感技术”。“遥感技术”是技术，应用量词“种”，不用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ac08d1a-efeb-4f2c-a70a-f3bd3f970645') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脆性", "is_correct": true, "explanation": "正确。“脆性”与“韧性”相对，指物体受力时容易破碎的性质。"}, {"text": "硬度", "is_correct": false, "explanation": "硬度指抵抗压入的能力，与“韧性”不构成反义关系。"}, {"text": "重量", "is_correct": false, "explanation": "重量是物体的质量程度，与“韧性”没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色与“韧性”属于不同性质，没有反义关系。"}], "correct_answer": "脆性", "explanations": {"脆性": "正确。“脆性”与“韧性”相对，指物体受力时容易破碎的性质。", "硬度": "硬度指抵抗压入的能力，与“韧性”不构成反义关系。", "重量": "重量是物体的质量程度，与“韧性”没有反义关系。", "颜色": "颜色与“韧性”属于不同性质，没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脆性", "is_correct": true, "explanation": "正确。“脆性”与“韧性”相对，指物体容易破裂的性质。"}, {"text": "长度", "is_correct": false, "explanation": "长度是尺寸的度量，与“韧性”没有反义关系。"}, {"text": "色泽", "is_correct": false, "explanation": "色泽指物体表面的颜色和光泽，与“韧性”没有反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度与“韧性”属于不同性质，没有反义关系。"}], "correct_answer": "脆性", "explanations": {"脆性": "正确。“脆性”与“韧性”相对，指物体容易破裂的性质。", "长度": "长度是尺寸的度量，与“韧性”没有反义关系。", "色泽": "色泽指物体表面的颜色和光泽，与“韧性”没有反义关系。", "温度": "温度与“韧性”属于不同性质，没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "不容易折断，比如橡皮筋拉长也不会断。", "primary_collocate": null, "pronunciation": "rèn xìng", "ipa": "ɻən˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种竹子韧性很好，不容易折断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "橡皮筋的韧性很强，拉长也不会断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根绳子韧性不够，一拉就断了。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钢的韧性比铁好。", "target_word": "韧性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做这把弓需要有韧性的木头。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柳树的枝条很有韧性，风吹不断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种塑料袋很有韧性，能装很重的东西。", "target_word": "韧性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面条很有韧性，用手拉也不容易断。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的皮带韧性很好，用不坏。", "target_word": "韧性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张纸有韧性，撕不开。", "target_word": "韧性", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "韌性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体受力弯曲拉长也不易折断的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73399449-2470-45bf-a42c-72fe9fbc4333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "韧性", "is_correct": true, "explanation": "正确。“韧性很好，不容易折断”，描述竹子不易折断的性质。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色本身不会折断，“不容易折断”不能用来形容颜色。"}, {"text": "香味", "is_correct": false, "explanation": "语义：香味与“折断”无关，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与“不容易折断”语义不符，句意不通。"}], "explanations": {"韧性": "正确。“韧性很好，不容易折断”，描述竹子不易折断的性质。", "颜色": "搭配：颜色本身不会折断，“不容易折断”不能用来形容颜色。", "香味": "语义：香味与“折断”无关，句意不通。", "价格": "语义：价格与“不容易折断”语义不符，句意不通。"}, "sentence_index": 0, "correct_answer": "韧性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃的韧性很高，能清楚地看到里面的东西。", "explanation": "〈透明度〉指光线透过的程度，“韧性”指不易折断，这里应该用〈透明度〉。"}, {"text": "这根橡皮筋很有韧性，轻轻一拉就断了。", "explanation": "“韧性”指不容易折断，一拉就断说明没有韧性，这里应该说〈很脆〉。"}, {"text": "这块合金的韧性很高，划不出痕迹。", "explanation": "〈硬度〉指抵抗划痕、压入的能力，“韧性”指不易折断，这里应该用〈硬度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "韧性", "is_correct": true, "explanation": "正确。“有韧性，能装很重的东西”，塑料袋要有不易断裂的性质。"}, {"text": "图案", "is_correct": false, "explanation": "语义：“图案”是花纹样式，不是可以承重的性质，“能装很重的东西”句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听觉现象，与袋子能否承重无关，句意不通。"}, {"text": "手艺", "is_correct": false, "explanation": "搭配：“很有手艺”说人的技能，不能用来形容塑料袋的性能。"}], "explanations": {"韧性": "正确。“有韧性，能装很重的东西”，塑料袋要有不易断裂的性质。", "图案": "语义：“图案”是花纹样式，不是可以承重的性质，“能装很重的东西”句意不通。", "声音": "语义：“声音”是听觉现象，与袋子能否承重无关，句意不通。", "手艺": "搭配：“很有手艺”说人的技能，不能用来形容塑料袋的性能。"}, "sentence_index": 6, "correct_answer": "韧性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在韧性里工作。", "explanation": "这里应该用〈车间〉。“韧性”是抽象性质，不能当作工作场所。"}, {"text": "他把韧性喝进了肚子里。", "explanation": "这里应该用〈饮料〉。“韧性”是抽象性质，不能被喝。"}, {"text": "这张纸的韧性是一个朋友。", "explanation": "“韧性”指材料不易折断的性质，不能与〈人〉等同，这句说法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这根铁丝是韧性，弯了也不断。", "corrected_sentence": "这根铁丝有韧性，弯了也不断。", "error_description": "动词错误：表示“具有”某种性质应用“有”，不能用“是”，应改为“这根铁丝有韧性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布的韧性的很好，洗多次也不坏。", "corrected_sentence": "这块布的韧性很好，洗多次也不坏。", "error_description": "“的”多余：“韧性很好”中“韧性”后不能再加“的”，应删去多余的“的”，说“这块布的韧性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微观", "is_correct": true, "explanation": "微观：从个体、局部方面看，与宏观意思相反，是常见的反义词。"}, {"text": "简单", "is_correct": false, "explanation": "简单：容易、不复杂，与宏观没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "安静：没有声音或不吵闹，与宏观没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖：指温度或感情的舒适，与宏观没有反义关系。"}], "correct_answer": "微观", "explanations": {"微观": "微观：从个体、局部方面看，与宏观意思相反，是常见的反义词。", "简单": "简单：容易、不复杂，与宏观没有反义关系。", "安静": "安静：没有声音或不吵闹，与宏观没有反义关系。", "温暖": "温暖：指温度或感情的舒适，与宏观没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "微观", "is_correct": true, "explanation": "微观：从个体、局部方面看，与宏观意思相反，是常见的反义词。"}, {"text": "快乐", "is_correct": false, "explanation": "快乐：指愉悦的心情，与宏观没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐：指排列有秩序，与宏观没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：指光线充足、明晃晃，与宏观没有反义关系。"}], "correct_answer": "微观", "explanations": {"微观": "微观：从个体、局部方面看，与宏观意思相反，是常见的反义词。", "快乐": "快乐：指愉悦的心情，与宏观没有反义关系。", "整齐": "整齐：指排列有秩序，与宏观没有反义关系。", "明亮": "明亮：指光线充足、明晃晃，与宏观没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指从整体方面看问题，不着眼于局部和细节。", "primary_collocate": null, "pronunciation": "hóng guān", "ipa": "xʊŋ˧˥ kwan˥", "syllable_count": 2, "sentences": [{"text": "他从宏观的角度看这个问题。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师先讲宏观的情况，再讲细节。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个宏观计划对全国都有用。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宏观地看，今年的经济不错。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划要有宏观的想法。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的宏观分析很清楚。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究整个国家的经济，要用宏观的方法。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法太宏观，没有具体办法。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要做宏观的安排。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从宏观上说，这个城市越来越好。", "target_word": "宏观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宏观经济", "label": "复合"}, {"form": "宏观调控", "label": "复合"}], "register": "书面语", "sense_fingerprint": "从整体方面看问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：角度与外貌无关，不能说“漂亮的角度”。"}, {"text": "宏观", "is_correct": true, "explanation": "宏观：从大的、整体的方面看，与“角度”搭配自然。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”说物体表面，不修饰“角度”。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：看问题的角度不说冷暖，“冰冷的角度”没有意义。"}], "explanations": {"漂亮": "语义：角度与外貌无关，不能说“漂亮的角度”。", "宏观": "宏观：从大的、整体的方面看，与“角度”搭配自然。", "粗糙": "搭配：“粗糙”说物体表面，不修饰“角度”。", "冰冷": "语义：看问题的角度不说冷暖，“冰冷的角度”没有意义。"}, "sentence_index": 0, "correct_answer": "宏观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座宏观的大楼矗立在广场中央。", "explanation": "这里应该用〈宏伟〉。宏观指从整体方面看问题，不形容建筑雄伟壮观，建筑的雄伟用宏伟。"}, {"text": "他的胸怀很宏观。", "explanation": "这里应该用〈宽广〉。宏观说的是观察的角度，不形容胸怀、器量的开阔，胸怀开阔用宽广。"}, {"text": "宏观的合唱震撼了全场。", "explanation": "这里应该用〈宏大〉。宏观指从整体方面看问题，形容合唱的气势雄壮要用宏大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微观", "is_correct": false, "explanation": "语义：“微观”着眼于个体和局部，与研究“整个国家的经济”矛盾。"}, {"text": "宏观", "is_correct": true, "explanation": "宏观：从整体方面看问题，研究整个国家的经济正需要整体的方法。"}, {"text": "细小", "is_correct": false, "explanation": "语义：“细小”形容东西小，不修饰研究方法，也与“整个国家”矛盾。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”修饰物品或场所，不修饰“方法”。"}], "explanations": {"微观": "语义：“微观”着眼于个体和局部，与研究“整个国家的经济”矛盾。", "宏观": "宏观：从整体方面看问题，研究整个国家的经济正需要整体的方法。", "细小": "语义：“细小”形容东西小，不修饰研究方法，也与“整个国家”矛盾。", "豪华": "搭配：“豪华”修饰物品或场所，不修饰“方法”。"}, "sentence_index": 6, "correct_answer": "宏观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片草原很宏观，一眼望不到边。", "explanation": "这里应该用〈辽阔〉。宏观指从整体方面看问题，不形容地面的广阔，草原的广阔用辽阔。"}, {"text": "这座塔看起来很宏观。", "explanation": "这里应该用〈高大〉。宏观不描述物体的高矮，形容建筑的高大用高大。"}, {"text": "她的经验很宏观。", "explanation": "这里应该用〈丰富〉。宏观不修饰经验的多少，经验的多少用丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宏观的说，这件事影响很大。", "corrected_sentence": "宏观地说，这件事影响很大。", "error_description": "“宏观”作状语修饰动词“说”时要用“地”，应说“宏观地说”；误用“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宏观的看，这个城市越来越好。", "corrected_sentence": "宏观地看，这个城市越来越好。", "error_description": "错误：“宏观”作状语修饰动词“看”，应用“地”，不能用“的”。正确：“宏观地看，这个城市越来越好。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
