INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里很想得到某个东西或做某件事。", "primary_collocate": null, "pronunciation": "yù wàng", "ipa": "y˥˩ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他有很强的学习欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子对新东西总有很强的探索欲望。", "target_word": "欲望", "complexity_tier": "T3", "furigana": "hái zi duì xīn dōng xi zǒng yǒu hěn qiáng de tàn suǒ yù wàng.", "sentence_source": "generated"}, {"text": "买太多东西会让欲望越来越大。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他控制不了吃甜品的欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "失败后，他没有了工作的欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告会让人有买东西的欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要学会控制自己的欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对成功的欲望很强。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想激发学生读书的欲望。", "target_word": "欲望", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到别人的新手机，他有了想买的欲望。", "target_word": "欲望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里强烈想得到或去做某事的愿望", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欲望", "is_correct": true, "explanation": "正确：“很强的学习欲望”指强烈想学习的心理，搭配自然。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“很强的”修饰，也不说“学习价格”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的外形，与学习无关。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人身的重量，不能说“学习体重”。"}], "explanations": {"欲望": "正确：“很强的学习欲望”指强烈想学习的心理，搭配自然。", "价格": "搭配：“价格”不能用“很强的”修饰，也不说“学习价格”。", "身材": "体貌：“身材”指人的外形，与学习无关。", "体重": "语义：“体重”是人身的重量，不能说“学习体重”。"}, "sentence_index": 0, "correct_answer": "欲望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生日那天，他对着蜡烛许了一个欲望。", "explanation": "这里应该用〈愿望〉。许愿、许下愿望是固定搭配，欲望指强烈想得到的东西，不能被“许”。"}, {"text": "医生治疗了他的欲望。", "explanation": "这里不是欲望的用法：欲望是心里强烈的想要，不是病症，不能被“治疗”。"}, {"text": "他最近生病了，欲望不好，吃得很少。", "explanation": "这里应该用〈胃口〉。胃口指想吃东西的感觉，可以说“胃口不好”；欲望是心里强烈想要，不说“欲望不好”来指食量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欲望", "is_correct": true, "explanation": "正确：“控制自己的欲望”指压制内心的冲动，搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：人不能“控制自己的天气”，与语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“控制”不能搭配“年龄”，年龄只会增长。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体的先天特征，不能说“控制自己的身高”。"}], "explanations": {"欲望": "正确：“控制自己的欲望”指压制内心的冲动，搭配自然。", "天气": "语义：人不能“控制自己的天气”，与语境不符。", "年龄": "搭配：“控制”不能搭配“年龄”，年龄只会增长。", "身高": "体貌：“身高”是身体的先天特征，不能说“控制自己的身高”。"}, "sentence_index": 6, "correct_answer": "欲望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把欲望送给了朋友。", "explanation": "这里不是欲望的用法：欲望是心里强烈的想要，不能当作东西送给别人。"}, {"text": "老板对员工提出了很高的欲望。", "explanation": "这里应该用〈要求〉。提出要求是固定搭配；欲望指心里强烈想得到的东西，不能用来指向别人提出的请求。"}, {"text": "我们周末去公园的欲望已经定好了。", "explanation": "这里应该用〈计划〉。计划可以“定好”；欲望是心里强烈想要的感觉，不能“定好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对音乐有一只强烈的欲望。", "corrected_sentence": "他对音乐有一种强烈的欲望。", "error_description": "量词错误：“欲望”应用量词“种”，“只”用于动物，应说“一种强烈的欲望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从小就对画画有一条强烈的欲望。", "corrected_sentence": "我从小就对画画有一种强烈的欲望。", "error_description": "量词错误：“欲望”应用量词“种”，“条”用于细长的东西，应说“一种强烈的欲望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
