INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21794, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "一件事表现出另一个事情。", "primary_collocate": null, "pronunciation": "tǐ xiàn", "ipa": "tʰi˨˩˦ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这件小事体现了他的好品质。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字体现了公司这一年的进步。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画体现了画家对家乡的爱。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话体现出对老人的尊重。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜体现了南方人的口味。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人，体现了一个人的善良。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子体现着古代人的智慧。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中，他体现出很强的团队精神。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日体现了中国人对家人的重视。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩体现了学生的努力。", "target_word": "体现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "体现了", "label": "体标"}, {"form": "体现着", "label": "体标"}, {"form": "體現", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某事物把另一种精神、品质或道理表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21794, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体现", "is_correct": true, "explanation": "“体现”指通过某事显出某种品质，与“好品质”搭配，句意通顺。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”指搬动实物，不能施用于抽象的“品质”，句子语义荒谬。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”搭配纪录、沉默、局面等，不说“打破品质”，搭配不当。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：“煮沸”指把液体烧开，与“品质”无法搭配，句子语义荒谬。"}], "explanations": {"体现": "“体现”指通过某事显出某种品质，与“好品质”搭配，句意通顺。", "搬运": "语义：“搬运”指搬动实物，不能施用于抽象的“品质”，句子语义荒谬。", "打破": "搭配：“打破”搭配纪录、沉默、局面等，不说“打破品质”，搭配不当。", "煮沸": "语义：“煮沸”指把液体烧开，与“品质”无法搭配，句子语义荒谬。"}, "sentence_index": 0, "correct_answer": "体现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屏幕上体现了当前的时间。", "explanation": "这里应该用〈显示〉。体现指某事物表现出抽象的品质或道理，屏幕上的数字、文字要用显示。"}, {"text": "博物馆体现了古代的陶器。", "explanation": "这里应该用〈展示〉。体现指抽象的品质或精神的显露，实物陈列出来要用展示。"}, {"text": "红灯体现了停止。", "explanation": "这里应该用〈表示〉。体现指抽象的品质或道理的显露，信号、符号传达意思要用表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21794, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体现", "is_correct": true, "explanation": "“体现”与“着”搭配，表示老房子持续呈现出古代人的智慧，句意通顺。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”搭配房屋、桥梁等具体工程，不能说“修建智慧”，搭配不当。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物，“智慧”不能被拆除，句子语义荒谬。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指用水去除污垢，不能施用于“智慧”，句子语义荒谬。"}], "explanations": {"体现": "“体现”与“着”搭配，表示老房子持续呈现出古代人的智慧，句意通顺。", "修建": "搭配：“修建”搭配房屋、桥梁等具体工程，不能说“修建智慧”，搭配不当。", "拆除": "语义：“拆除”指拆掉建筑物，“智慧”不能被拆除，句子语义荒谬。", "清洗": "语义：“清洗”指用水去除污垢，不能施用于“智慧”，句子语义荒谬。"}, "sentence_index": 6, "correct_answer": "体现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "镜子体现了他的样子。", "explanation": "这里应该用〈照出〉。体现指抽象的品质或道理的显露，镜子里映出人的样子要说“照出”。"}, {"text": "这本日记体现了旅行的经过。", "explanation": "这里应该用〈记录〉。体现指抽象的品质或道理，具体事件的记载要用记录。"}, {"text": "他体现了一本小说。", "explanation": "这里应该用〈写〉。体现指抽象的品质或道理的显露，创作作品要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21794, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动的意义体现团队合作上。", "corrected_sentence": "这次活动的意义体现在团队合作上。", "error_description": "介词省略错误：“体现”表示在某方面显出来时要用“体现在……上”，不能省略“在”，应为“体现在团队合作上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21794, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座庙体现了着当时人的信仰。", "corrected_sentence": "这座庙体现着当时人的信仰。", "error_description": "体标错误：“了”和“着”不能同时用在同一动词后；表示持续的状态应用“体现着”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
