INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "平台就是一块平平的、高高的地方，可以站上去。", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "小明站在平台上，高兴地笑了。", "target_word": "平台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平台很高，我爬了很久才上去。", "target_word": "平台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们爬上平台，往下看。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "平台上有一把椅子。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在平台上看见了大树。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师站在平台上说话。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个平台又平又高。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫跳上平台睡觉。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸把我抱上了平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在平台上晒太阳。", "target_word": "平台", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "高平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "又平又高、可以站上去的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42af6dd8-76df-4128-9f4d-41a929127788') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台是平坦的高台，人可以站在上面，符合句意。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯太小，是装水用的，人站不上去。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能站在上面。"}, {"text": "尖刺", "is_correct": false, "explanation": "体貌：尖刺细而尖，站不稳，也不是可以站人的平面。"}], "explanations": {"平台": "平台是平坦的高台，人可以站在上面，符合句意。", "水杯": "语义：水杯太小，是装水用的，人站不上去。", "空气": "语义：空气是看不见的气体，不能站在上面。", "尖刺": "体貌：尖刺细而尖，站不稳，也不是可以站人的平面。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个平台会游泳，我们把它推进了河里。", "explanation": "这里应该用「船」。平台是固定的台面，不会游泳，也不能推进河里。"}, {"text": "我把平台折起来，放进了书包。", "explanation": "这里应该用「纸」或「布」。平台是硬的台面，不能折起来装进书包。"}, {"text": "这座平台很陡，我们很难往上走。", "explanation": "这里应该用「斜坡」。平台是平的，不会陡，「陡」用来形容斜坡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "平台既平又高，符合「又平又高」的描述。"}, {"text": "花盆", "is_correct": false, "explanation": "体貌：花盆一般又小又圆，不高也不平，不能说「又平又高」。"}, {"text": "石子", "is_correct": false, "explanation": "体貌：石子小而圆，既不高也不平，不符合描述。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是用来坐的，可能是平的，但不高，不符合「又平又高」。"}], "explanations": {"平台": "平台既平又高，符合「又平又高」的描述。", "花盆": "体貌：花盆一般又小又圆，不高也不平，不能说「又平又高」。", "石子": "体貌：石子小而圆，既不高也不平，不符合描述。", "沙发": "语义：沙发是用来坐的，可能是平的，但不高，不符合「又平又高」。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把平台煮进了汤里，味道很鲜。", "explanation": "这里应该用「豆腐」或「蔬菜」。平台是固定的台面，不能煮；「鲜」形容食物。"}, {"text": "孩子们一起给平台讲故事。", "explanation": "这里应该用「玩偶」或「小朋友」。平台不是听众，也不能讲故事。"}, {"text": "这个平台很软，他们躺在上面睡觉。", "explanation": "这里应该用「床」。床可以软，平台是硬的平面，不会软。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们在一条平台上跳舞，大家都在鼓掌。", "corrected_sentence": "孩子们在一个平台上跳舞，大家都在鼓掌。", "error_description": "错误：「一条平台」，正确：「一个平台」。平台应用量词「个」，「条」用于细长的东西，不能用来数平台。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21796, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站那个平台上，那里很高。", "corrected_sentence": "他站在那个平台上，那里很高。", "error_description": "错误：「他站那个平台上」，正确：「他站在那个平台上」。表示站立的地点时，动词「站」后面要用介词「在」引出处所，缺了「在」本地人不会这样说。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '162139ae-0c32-4afa-8b85-9269af9a2c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
