INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21798, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不对的东西放在一起。", "primary_collocate": null, "pronunciation": "cuò pèi", "ipa": "tsʰuo⁵¹ pʰei⁵¹", "syllable_count": 2, "sentences": [{"text": "他把鞋和袜子错配了。", "target_word": "错配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服和裤子错配，不好看。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盖子和杯子错配了，盖不上。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把两只耳环错配了，颜色不一样。", "target_word": "错配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜和酒错配，味道很怪。", "target_word": "错配", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两块拼图错配了，放不进去。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把左右两只手套错配了。", "target_word": "错配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把照片和名字错配了。", "target_word": "错配", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螺丝和螺母错配，拧不紧。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电池和玩具错配，玩具不会动。", "target_word": "错配", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "错配了", "label": "体标"}, {"form": "錯配", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把不相配的物品搭在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ac8efc8-1461-4dce-be40-9987f9ef42b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "错配", "is_correct": true, "explanation": "错配：此处指把不相配的鞋和袜子搭在一起，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声的动作，“把鞋和袜子唱了”句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求饮食类宾语，鞋和袜子不能被吃。"}, {"text": "笑", "is_correct": false, "explanation": "语义：笑是表情动作，不能支配“鞋和袜子”，句意不通。"}], "explanations": {"错配": "错配：此处指把不相配的鞋和袜子搭在一起，符合句意。", "唱": "语义：唱是发声的动作，“把鞋和袜子唱了”句意不通。", "吃": "配价：“吃”要求饮食类宾语，鞋和袜子不能被吃。", "笑": "语义：笑是表情动作，不能支配“鞋和袜子”，句意不通。"}, "sentence_index": 0, "correct_answer": "错配"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服和裤子错配得很好看，大家都夸她。", "explanation": "这里应该用〈搭配〉。错配指配错，不能说“错配得很好看”，夸配得好要用搭配。"}, {"text": "这两块拼图错配得很合适，一下就拼上了。", "explanation": "这里应该用〈吻合〉。错配指配错，与“合适”“一下就拼上”矛盾，形容严丝合缝要用吻合。"}, {"text": "这双鞋和袜子错配得很相配，一起穿很舒服。", "explanation": "这里不能用错配：错配指把不对的东西放在一起，与“相配”“很舒服”矛盾。应改用〈搭配〉等表示配得好的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "错配", "is_correct": true, "explanation": "错配：此处指把不相配的左右手套搭在一起，符合句意。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳是人的动作，“把左右两只手套跳了”句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”要求饮品类宾语，手套不能被喝。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡是休息的动作，不能支配“左右两只手套”，句意不通。"}], "explanations": {"错配": "错配：此处指把不相配的左右手套搭在一起，符合句意。", "跳": "语义：跳是人的动作，“把左右两只手套跳了”句意不通。", "喝": "配价：“喝”要求饮品类宾语，手套不能被喝。", "睡": "语义：睡是休息的动作，不能支配“左右两只手套”，句意不通。"}, "sentence_index": 6, "correct_answer": "错配"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两只鞋子错配得很协调，穿着很舒服。", "explanation": "这里应该用〈搭配〉。错配指配错，与“很协调”矛盾，配得好要说“搭配得很协调”。"}, {"text": "他把杯子错配在了书架上面，找不到了。", "explanation": "这里应该用〈放错〉。错配指两样东西配错，不能只说东西放错了位置。"}, {"text": "这次谈判的结果错配得很好，两边都很满意。", "explanation": "这里不能用错配：错配指把不对的东西放在一起，与“很好”“很满意”矛盾。形容结果好应说“结果很圆满”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把两只手套错配了了，戴起来不舒服。", "corrected_sentence": "他把两只手套错配了，戴起来不舒服。", "error_description": "体标重复：“错配了”的“了”已表示完成，后面不能再加一个“了”，正确说法是“错配了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两块拼图错配了过，还是放不进去。", "corrected_sentence": "这两块拼图错配了，还是放不进去。", "error_description": "体标：''了''与''过''不能同时用在动词后（''错配了过''不成立），应删去''过''，说''错配了''。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a0d1ab8-86d2-40a3-92a4-e2d92badd85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
