INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以用来做事情的东西，比如水、木头、钱。", "primary_collocate": null, "pronunciation": "zī yuán", "ipa": "tsɹ̩˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "水是很重要的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的资源很丰富。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要节约资源，不要浪费。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林是地球上的重要资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇缺少资源，生活不太方便。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把钱和人都当成重要的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油是一种有限的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的资源不多，大家要一起用。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用有限的资源盖了一座新房子。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头、水和煤都是资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "水、木头、钱等可供使用的物质和财力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd85b7b25-3bf8-4da1-af69-47b35a3d9947') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资源", "is_correct": true, "explanation": "正是词目「资源」zī yuán，指可供使用的物质或财力。"}, {"text": "支援", "is_correct": false, "explanation": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。"}, {"text": "自愿", "is_correct": false, "explanation": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。"}, {"text": "字源", "is_correct": false, "explanation": "zì yuán 与 zī yuán 只有第一个字声调不同（第4声与第1声），意思是汉字的来源。"}], "explanations": {"资源": "正是词目「资源」zī yuán，指可供使用的物质或财力。", "支援": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。", "自愿": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。", "字源": "zì yuán 与 zī yuán 只有第一个字声调不同（第4声与第1声），意思是汉字的来源。"}, "sentence_index": null, "correct_answer": "资源"}, "level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可供使用的物质财富，水属于此类，句意通顺。"}, {"text": "资金", "is_correct": false, "explanation": "语义：「资金」指钱款，水是物质，不是钱款，句意不通。"}, {"text": "资格", "is_correct": false, "explanation": "搭配：「很重要的资格」说的是人或条件，不能用来指水。"}, {"text": "人口", "is_correct": false, "explanation": "语义：「人口」指人的数量，水不是人口，句意不通。"}], "explanations": {"资源": "资源：可供使用的物质财富，水属于此类，句意通顺。", "资金": "语义：「资金」指钱款，水是物质，不是钱款，句意不通。", "资格": "搭配：「很重要的资格」说的是人或条件，不能用来指水。", "人口": "语义：「人口」指人的数量，水不是人口，句意不通。"}, "sentence_index": 0, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的资源很好，学什么都快。", "explanation": "这里应该用〈资质〉。「资源」指可供利用的物质或财力，不用来指人的天资。"}, {"text": "这座桥的资源很牢固，车辆都能通过。", "explanation": "这里应该用〈质量〉。「资源」指可供利用的物质或财力，不用来说桥的牢固程度。"}, {"text": "他对这次比赛很有资源，一定能赢。", "explanation": "这里应该用〈把握〉。「资源」指可供利用的物质或财力，不用来表示对结果有把握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可供使用的物质财富，石油属于此类，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：石油是物质，「天气」不是可以「有限」的东西，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的感受，石油不能是心情，句意不通。"}, {"text": "人才", "is_correct": false, "explanation": "搭配：「一种……的人才」指人，与「石油」搭配不通。"}], "explanations": {"资源": "资源：可供使用的物质财富，石油属于此类，句意通顺。", "天气": "语义：石油是物质，「天气」不是可以「有限」的东西，句意不通。", "心情": "语义：「心情」是人的感受，石油不能是心情，句意不通。", "人才": "搭配：「一种……的人才」指人，与「石油」搭配不通。"}, "sentence_index": 6, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视的资源很清楚，画面很逼真。", "explanation": "这里应该用〈画质〉。「资源」不用来说电视的清晰程度，应说「画质」。"}, {"text": "他的演讲资源很精彩，大家都鼓掌。", "explanation": "这里应该用〈内容〉。「资源」不用来说演讲的内容好坏，应说「内容」。"}, {"text": "这位运动员的资源很棒，跑得很快。", "explanation": "这里应该用〈素质〉。「资源」不用来指运动员的身体条件，应说「素质」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座岛有丰富地资源。", "corrected_sentence": "这座岛有丰富的资源。", "error_description": "助词错误：形容词修饰名词要用「的」，不用「地」；「地」用于修饰动词。应说「丰富的资源」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把这些资源们都分给了各班。", "corrected_sentence": "学校把这些资源都分给了各班。", "error_description": "复数标记错误：「们」只用于人，「资源」是非人名词，不能加「们」，应说「这些资源」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a7135ca-31ed-44de-b065-1abec0640602') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
