INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21802, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "使隐藏的真相或规律显露出来。", "primary_collocate": null, "pronunciation": "jiē shì", "ipa": "tɕjɛ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这篇报道揭示了事情的真相。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家揭示了这种病的原因。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事揭示了人生的道理。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究揭示了天气变化的规律。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影揭示了社会的问题。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察终于揭示了案件的秘密。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话揭示了他心里的想法。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的发现揭示了古人的生活。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书揭示了很多历史秘密。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据揭示了一个大问题。", "target_word": "揭示", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "揭示了", "label": "体标"}, {"form": "揭示出", "label": "补语"}], "register": "书面", "sense_fingerprint": "使隐藏的真相或规律显露出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5fcf5b-556e-47e4-b003-813f3f632225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21802, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "揭示", "is_correct": true, "explanation": "正确。“揭示”指把隐藏的真相或规律显露出来，读作 jiē shì。"}, {"text": "解释", "is_correct": false, "explanation": "jiě shì（第三声）与 jiē shì（第一声）第一音节声调不同，意思是说明事理。"}, {"text": "结识", "is_correct": false, "explanation": "jié shí 与 jiē shì 两个音节声调都不同，意思是认识并交往。"}, {"text": "结实", "is_correct": false, "explanation": "jiē shi（第二音节轻声）与 jiē shì 声调不同，意思是坚固、强壮。"}, {"text": "节食", "is_correct": false, "explanation": "jié shí 与 jiē shì 两个音节声调都不同，意思是控制饮食。"}], "explanations": {"揭示": "正确。“揭示”指把隐藏的真相或规律显露出来，读作 jiē shì。", "解释": "jiě shì（第三声）与 jiē shì（第一声）第一音节声调不同，意思是说明事理。", "结识": "jié shí 与 jiē shì 两个音节声调都不同，意思是认识并交往。", "结实": "jiē shi（第二音节轻声）与 jiē shì 声调不同，意思是坚固、强壮。", "节食": "jié shí 与 jiē shì 两个音节声调都不同，意思是控制饮食。"}, "sentence_index": null, "correct_answer": "揭示"}, "level_3": {"options": [{"text": "揭示", "is_correct": true, "explanation": "正确。“揭示”表示把隐藏的真相显露出来，符合“报道揭示事情的真相”的语境。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指使进行中的活动终止，报道不能让真相“停止”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃了事情的真相”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器或器物，真相不能被修理。"}], "explanations": {"揭示": "正确。“揭示”表示把隐藏的真相显露出来，符合“报道揭示事情的真相”的语境。", "停止": "语义：“停止”指使进行中的活动终止，报道不能让真相“停止”。", "吃": "搭配：“吃”的对象是食物，不能说“吃了事情的真相”。", "修理": "搭配：“修理”的对象是机器或器物，真相不能被修理。"}, "sentence_index": 0, "correct_answer": "揭示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他轻轻揭示了锅盖。", "explanation": "这里应该用〈揭开〉。“揭示”用于隐藏的真相或规律，“揭开”才用于锅盖、面纱等具体物件。"}, {"text": "他脸上揭示了笑容。", "explanation": "这里应该用〈露出〉。“揭示”用于隐藏的秘密或真相，表情显露要用“露出”，不能说“揭示笑容”。"}, {"text": "我在路上揭示了一个新朋友。", "explanation": "这里应该用〈认识〉。“揭示”的对象是真相或规律，不能用于认识的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "揭示", "is_correct": true, "explanation": "正确。“揭示”表示使隐藏的想法显露出来，符合“他的话揭示了他心里的想法”的语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或地面，不能说“打扫想法”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做熟食物，与“想法”毫无关系，句子不通。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：“熨”的对象是衣物，不能用于“想法”。"}], "explanations": {"揭示": "正确。“揭示”表示使隐藏的想法显露出来，符合“他的话揭示了他心里的想法”的语境。", "打扫": "搭配：“打扫”的对象是场所或地面，不能说“打扫想法”。", "煮": "语义：“煮”指用水加热做熟食物，与“想法”毫无关系，句子不通。", "熨": "搭配：“熨”的对象是衣物，不能用于“想法”。"}, "sentence_index": 6, "correct_answer": "揭示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在展览会上揭示了自己的画。", "explanation": "这里应该用〈展示〉。“揭示”强调使隐藏的内容显露，“展示”才指把作品拿给人看。"}, {"text": "屏幕上揭示了一个数字。", "explanation": "这里应该用〈显示〉。“显示”用于屏幕、仪表等显现信息，“揭示”指使隐藏的真相显露。"}, {"text": "我把箱子揭示，看到了里面的玩具。", "explanation": "这里应该用〈打开〉。“揭示”用于隐藏的真相，打开箱子要用“打开”，不能说“揭示箱子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从来没揭示了真相。", "corrected_sentence": "他从来没揭示过真相。", "error_description": "体标错误：“没”后不能用“了”，表示从未有过的经历要用“过”，应说“从来没揭示过真相”，不说“从来没揭示了真相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调查揭示来了事故的真相。", "corrected_sentence": "这次调查揭示出了事故的真相。", "error_description": "补语错误：“揭示”后应接趋向补语“出”，表示把隐藏的内容显露出来；“揭示来”不成立，应说“揭示出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c2ee324-3ac6-45de-8643-7f01f980d6be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
