INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21804, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "画面或照片中位于远处的景物，如远山、房屋等。", "primary_collocate": null, "pronunciation": "bèi jǐng", "ipa": "pei˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张照片的背景是一座山。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的背景有很多小房子。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在海边，照片的背景很漂亮。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，画的背景里有一棵大树。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画的背景是蓝色的。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片的背景太黑了，我看不清楚。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片的背景换成了白色。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里背景上的山很远，也很小。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这幅画的背景。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在前面玩，照片的背景是一片草地。", "target_word": "背景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "背景音乐", "label": "复合"}, {"form": "背景图", "label": "复合"}], "register": "中性", "sense_fingerprint": "画面或照片中位于远处的景物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd55c2c29-17cd-4734-b3f1-6a6d294a15a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21804, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "背景", "is_correct": true, "explanation": "正确。bèi jǐng，指画面或照片中远处的景物。"}, {"text": "北京", "is_correct": false, "explanation": "bèi（第四声）与 běi（第三声）、jǐng（第三声）与 jīng（第一声）声调都不同，意思是中国首都。"}, {"text": "背影", "is_correct": false, "explanation": "jǐng 与 yǐng 声母不同（j 与 y），意思是人的后背形象。"}, {"text": "北境", "is_correct": false, "explanation": "bèi 与 běi 声调不同，jǐng 与 jìng 声调也不同，意思是北方的边境。"}], "explanations": {"背景": "正确。bèi jǐng，指画面或照片中远处的景物。", "北京": "bèi（第四声）与 běi（第三声）、jǐng（第三声）与 jīng（第一声）声调都不同，意思是中国首都。", "背影": "jǐng 与 yǐng 声母不同（j 与 y），意思是人的后背形象。", "北境": "bèi 与 běi 声调不同，jǐng 与 jìng 声调也不同，意思是北方的边境。"}, "sentence_index": null, "correct_answer": "背景"}, "level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "正确。背景指照片中远处的景物，这里说照片里远处是一座山。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」指色彩，不能说一座山是照片的颜色。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」一般只用于人或动物，不能说照片的年龄。"}, {"text": "作者", "is_correct": false, "explanation": "语义：「作者」指创作的人，山不能是照片的作者。"}], "explanations": {"背景": "正确。背景指照片中远处的景物，这里说照片里远处是一座山。", "颜色": "语义：「颜色」指色彩，不能说一座山是照片的颜色。", "年龄": "搭配：「年龄」一般只用于人或动物，不能说照片的年龄。", "作者": "语义：「作者」指创作的人，山不能是照片的作者。"}, "sentence_index": 0, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只看见她的背景，看不清脸。", "explanation": "这里应该用〈背影〉。背景指画面或照片中远处的景物，人的后背形象要说背影。"}, {"text": "这座城市的背景很大。", "explanation": "这里应该用〈面积〉。背景指画面或照片中远处的景物，不能用来说城市的大小；城市的大小要说面积。"}, {"text": "我们明天坐火车去背景旅游。", "explanation": "这里应该用〈北京〉。背景指画面或照片中远处的景物，不是地名；中国的首都要说北京。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背景", "is_correct": true, "explanation": "正确。这里指照片中的背景，换成白色就是换掉远处的景物。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」指发出的音响，照片里的声音不能换成白色。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」只用于人或动物，照片不说体重。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：「尺寸」指大小，不能被换成白色。"}], "explanations": {"背景": "正确。这里指照片中的背景，换成白色就是换掉远处的景物。", "声音": "语义：「声音」指发出的音响，照片里的声音不能换成白色。", "体重": "搭配：「体重」只用于人或动物，照片不说体重。", "尺寸": "语义：「尺寸」指大小，不能被换成白色。"}, "sentence_index": 6, "correct_answer": "背景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他背着一个大背景去上学。", "explanation": "这里应该用〈背包〉。背景指画面或照片中远处的景物，背在身上的包要说背包。"}, {"text": "这个菜的背景很辣。", "explanation": "这里应该用〈味道〉。背景指画面或照片中远处的景物，不能形容菜的辣味；菜的味道要说味道。"}, {"text": "请把电视的背景开大一点，我听不见。", "explanation": "这里应该用〈声音〉。背景指画面或照片中远处的景物，不能开大开小；听不见要把声音开大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画有一把红色的背景。", "corrected_sentence": "这幅画有一个红色的背景。", "error_description": "错误在量词：「背景」应该用「个」，「把」用于有把手的东西，不能用来数背景。正确说法是「一个红色的背景」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片有一只绿色的背景。", "corrected_sentence": "这张照片有一个绿色的背景。", "error_description": "错误在量词：「只」用于动物等，不能用来数背景；「背景」应该用「个」。正确说法是「一个绿色的背景」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2512b206-61b6-47f3-a7d1-2353d2b9f1df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。"}, {"text": "出发", "is_correct": false, "explanation": "出发与“持续”没有反义关系，它表示动作的开始，不是“不间断”的对立面。"}, {"text": "参加", "is_correct": false, "explanation": "参加与“持续”没有反义关系，二者不在同一语义维度上对立。"}, {"text": "相信", "is_correct": false, "explanation": "相信与“持续”没有反义关系，它表示心理态度，与时间的连续性无关。"}], "correct_answer": "间断", "explanations": {"间断": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。", "出发": "出发与“持续”没有反义关系，它表示动作的开始，不是“不间断”的对立面。", "参加": "参加与“持续”没有反义关系，二者不在同一语义维度上对立。", "相信": "相信与“持续”没有反义关系，它表示心理态度，与时间的连续性无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。"}, {"text": "购买", "is_correct": false, "explanation": "购买与“持续”没有反义关系，它表示取得物品的行为。"}, {"text": "参观", "is_correct": false, "explanation": "参观与“持续”没有反义关系，它表示去某地看一看。"}, {"text": "批评", "is_correct": false, "explanation": "批评与“持续”没有反义关系，它表示指出缺点或错误。"}], "correct_answer": "间断", "explanations": {"间断": "正确：“间断”与“持续”相对，指中间有停顿，是“持续”（不间断）的反义词。", "购买": "购买与“持续”没有反义关系，它表示取得物品的行为。", "参观": "参观与“持续”没有反义关系，它表示去某地看一看。", "批评": "批评与“持续”没有反义关系，它表示指出缺点或错误。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一直做，不停。", "primary_collocate": null, "pronunciation": "chí xù", "ipa": "tʂʰʅ˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "大雨持续了三天。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种好天气会持续一个星期。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头疼持续了很久。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛持续了两个小时。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议持续到晚上八点。", "target_word": "持续", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好天气不会持续太久，很快就会结束。", "target_word": "持续", "complexity_tier": "T3", "furigana": "hǎo tiān qì bú huì chí xù tài jiǔ, hěn kuài jiù huì jié shù.", "sentence_source": "generated"}, {"text": "你要持续学习，才能进步。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题已经持续很多年了。", "target_word": "持续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他持续锻炼了半年，身体越来越好。", "target_word": "持续", "complexity_tier": "T3", "furigana": "tā chí xù duàn liàn le bàn nián, shēn tǐ yuè lái yuè hǎo.", "sentence_source": "generated"}, {"text": "音乐持续了半个小时，大家都没说话。", "target_word": "持续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持续了", "label": "体标"}, {"form": "持续着", "label": "体标"}, {"form": "持续性", "label": "复合"}, {"form": "可持续", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情或动作一直进行、不间断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e886baf2-6b8e-4ba4-b9ee-b0c12fe6a1b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "持续", "is_correct": true, "explanation": "正确：“持续”表示一直进行、不间断，与“了三天”这一时间段搭配。"}, {"text": "考虑", "is_correct": false, "explanation": "语义：“考虑”需要有思维的主语，“大雨”不能考虑，句子说不通。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”的主语应是人或交通工具，不能说“大雨迟到了三天”。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”需要有意愿的主语，雨没有意愿，不能拒绝。"}], "explanations": {"持续": "正确：“持续”表示一直进行、不间断，与“了三天”这一时间段搭配。", "考虑": "语义：“考虑”需要有思维的主语，“大雨”不能考虑，句子说不通。", "迟到": "搭配：“迟到”的主语应是人或交通工具，不能说“大雨迟到了三天”。", "拒绝": "语义：“拒绝”需要有意愿的主语，雨没有意愿，不能拒绝。"}, "sentence_index": 0, "correct_answer": "持续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他休息了一会儿，又持续工作了。", "explanation": "这里应该用〈继续〉。持续指不间断地进行，句中“休息了一会儿”说明中间停过；中断后接着做应说“继续”。"}, {"text": "他每隔一个小时就持续喝一次水。", "explanation": "这里应该用〈定时〉。定时指按规定的时间进行，“每隔一个小时”说明动作是间隔重复的，不是不间断地进行。"}, {"text": "他持续着自己的看法，不肯改。", "explanation": "这里应该用〈坚持〉。坚持指始终不改变自己的看法，持续只说动作一直进行，不能带“看法”作宾语表示坚守。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "持续", "is_correct": true, "explanation": "正确：“持续”表示不间断地做，与“学习”搭配，符合“才能进步”的语境。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止学习”与句中“才能进步”的意思相悖，说不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃学习”与“才能进步”相矛盾，句子的逻辑不成立。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步学习”说不通，“散步”不能用来说明怎样学习。"}], "explanations": {"持续": "正确：“持续”表示不间断地做，与“学习”搭配，符合“才能进步”的语境。", "停止": "语义：“停止学习”与句中“才能进步”的意思相悖，说不通。", "放弃": "语义：“放弃学习”与“才能进步”相矛盾，句子的逻辑不成立。", "散步": "搭配：“散步学习”说不通，“散步”不能用来说明怎样学习。"}, "sentence_index": 6, "correct_answer": "持续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了持续生活，他每天打三份工。", "explanation": "这里应该用〈维持〉。维持指保住生计或某种状态，持续只说某事一直进行，不能直接带“生活”作宾语。"}, {"text": "我们要持续安静，不要打扰别人。", "explanation": "这里应该用〈保持〉。保持后常接“安静”“健康”等状态词，持续强调时间上的不间断，不能与“安静”这类状态搭配。"}, {"text": "他努力持续公司的名誉。", "explanation": "这里应该用〈维护〉。维护指保护使之不受损害，持续不能带“名誉”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演出很持续了一个多小时。", "corrected_sentence": "这场演出持续了一个多小时。", "error_description": "错误：“很持续”。“持续”是动词，不能受程度副词“很”修饰；应去掉“很”，说“持续了一个多小时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种情况还在持续了着。", "corrected_sentence": "这种情况还在持续着。", "error_description": "错误：“持续了着”。“了”和“着”不能同时用在同一动词后；表示动作正在进行只用“着”，应说“持续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0907cc3e-97e8-4e3a-ba50-cdd19a567979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
