INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21808, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "伦理就是告诉人们什么是对的，什么是错的道理。", "primary_collocate": null, "pronunciation": "lún lǐ", "ipa": "lu̯ən˧˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师说，做人要讲伦理，不能只想着自己。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做违反了伦理，大家都不同意。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家做实验时，也要考虑伦理问题。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家庭里，孩子要尊敬父母，这也是一种伦理。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法没有错，但是有伦理上的争议。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人觉得年轻人不懂伦理，见了长辈也不问好。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一节课，讨论网络上的伦理问题。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伦理告诉我们，欺骗别人是不对的。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能为了赚钱而不顾伦理。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的故事让人想到很多伦理的问题。", "target_word": "伦理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倫理", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "人与人相处时判断对错的道德准则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616a40b2-ff1d-4894-b98c-a82aa79ff0f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21808, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伦理", "is_correct": true, "explanation": "「伦理」指做人应遵守的道理，与「做人要讲」相合。"}, {"text": "数学", "is_correct": false, "explanation": "语义：「数学」是学科，做人的道理不能用它来说，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「讲」不与「颜色」搭配，不能说讲颜色。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」与做人的道理毫无关系。"}], "explanations": {"伦理": "「伦理」指做人应遵守的道理，与「做人要讲」相合。", "数学": "语义：「数学」是学科，做人的道理不能用它来说，句意不通。", "颜色": "搭配：「讲」不与「颜色」搭配，不能说讲颜色。", "天气": "语义：「天气」与做人的道理毫无关系。"}, "sentence_index": 0, "correct_answer": "伦理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的伦理太复杂，维修员看了半天也没弄明白。", "explanation": "这里应该用〈结构〉。伦理指道德准则，机器的构造要用结构。"}, {"text": "游戏的伦理很简单，一看就懂。", "explanation": "这里应该用〈规则〉。「伦理」是道德准则，游戏里的玩法要用规则。"}, {"text": "他有早睡早起的伦理。", "explanation": "这里应该用〈习惯〉。「伦理」指道德准则，个人的生活作息要用习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21808, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伦理", "is_correct": true, "explanation": "「伦理」指道德准则，与「讨论网络上的……问题」相合。"}, {"text": "地形", "is_correct": false, "explanation": "语义：「地形」指地表的形状，与网络上的问题无关。"}, {"text": "木材", "is_correct": false, "explanation": "语义：「木材」是建材，与网络上的问题无关。"}, {"text": "盐分", "is_correct": false, "explanation": "搭配：「盐分」与「网络上的」搭配不通，此处讲不通。"}], "explanations": {"伦理": "「伦理」指道德准则，与「讨论网络上的……问题」相合。", "地形": "语义：「地形」指地表的形状，与网络上的问题无关。", "木材": "语义：「木材」是建材，与网络上的问题无关。", "盐分": "搭配：「盐分」与「网络上的」搭配不通，此处讲不通。"}, "sentence_index": 6, "correct_answer": "伦理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的伦理很好，每次考试都得满分。", "explanation": "这里应该用〈成绩〉。「伦理」是道德准则，不能用来形容考试成绩。"}, {"text": "他的伦理很急，一点小事就发火。", "explanation": "这里应该用〈脾气〉。「伦理」指道德准则，不能用来形容性情。"}, {"text": "这个房间的伦理很大，能放两张床。", "explanation": "这里应该用〈面积〉。「伦理」是道德准则，房间的大小要用面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21808, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项制度体现了一座伦理。", "corrected_sentence": "这项制度体现了一种伦理。", "error_description": "「伦理」是抽象名词，量词应用「种」，「座」多用于山、桥等大型物体，不能说「一座伦理」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21808, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的做法引起了伦理上地争议。", "corrected_sentence": "他的做法引起了伦理上的争议。", "error_description": "「伦理上的争议」中修饰名词「争议」要用「的」，「地」用于修饰动词，不能说「伦理上地争议」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e6f69f0-eb3d-442c-b60c-16570c7f1216') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
