INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21810, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人一起下棋，想办法赢对方。", "primary_collocate": null, "pronunciation": "bó yì", "ipa": "po˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "两个人在棋盘上展开了一场博弈。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场博弈从早上一直进行到晚上。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷和老王的博弈很精彩，大家都在看。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢研究棋局，每次博弈都想很久。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋是一场很长时间的博弈。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这场博弈中，他先走错了一步。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博弈的两个人都不说话。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李和哥哥的象棋博弈，最后哥哥赢了。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场博弈很难，两个人都想赢。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有两位老人正在博弈。", "target_word": "博弈", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "博弈论", "label": "复合"}], "register": "书面", "sense_fingerprint": "名词：两人下棋，想办法赢对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "博弈", "is_correct": true, "explanation": "正确：“博弈”指双方斗智较量，与“在棋盘上展开”的语境相符。"}, {"text": "棋谱", "is_correct": false, "explanation": "语义：“棋谱”是记录棋局的书，不能被“展开”。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：“演讲”是对听众发表讲话，不能在棋盘上进行。"}, {"text": "讲座", "is_correct": false, "explanation": "搭配：“讲座”多指由人讲授的活动，不能在棋盘上“展开”。"}], "explanations": {"博弈": "正确：“博弈”指双方斗智较量，与“在棋盘上展开”的语境相符。", "棋谱": "语义：“棋谱”是记录棋局的书，不能被“展开”。", "演讲": "语义：“演讲”是对听众发表讲话，不能在棋盘上进行。", "讲座": "搭配：“讲座”多指由人讲授的活动，不能在棋盘上“展开”。"}, "sentence_index": 0, "correct_answer": "博弈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天在课堂上博弈，讲了三个小时的课。", "explanation": "这里应该用〈授课〉。“博弈”指两人斗智较量，老师单方面讲课不能说“博弈”，应说“授课”。"}, {"text": "他每天早上在公园里博弈，跑了十公里。", "explanation": "这里应该用〈锻炼〉。“博弈”指两人斗智较量，早晨跑步是个人活动，应说“锻炼”，不能说“博弈”。"}, {"text": "他一个人在房间里博弈，没有对手。", "explanation": "这里应该用〈摆棋〉。“博弈”需要双方对抗、想办法赢对方，一个人独自摆棋研究不能说“博弈”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "博弈", "is_correct": true, "explanation": "正确：“博弈”指进行较量的双方的活动，与“两个人”的主语相符。"}, {"text": "胜负", "is_correct": false, "explanation": "语义：“胜负”指输赢的结果，不能指进行比赛的两个人。"}, {"text": "棋子", "is_correct": false, "explanation": "语义：“棋子”是棋类游戏中的棋，不能指两个人。"}, {"text": "棋盘", "is_correct": false, "explanation": "搭配：“棋盘”是物件，不能作为两个人的动作主体。"}], "explanations": {"博弈": "正确：“博弈”指进行较量的双方的活动，与“两个人”的主语相符。", "胜负": "语义：“胜负”指输赢的结果，不能指进行比赛的两个人。", "棋子": "语义：“棋子”是棋类游戏中的棋，不能指两个人。", "棋盘": "搭配：“棋盘”是物件，不能作为两个人的动作主体。"}, "sentence_index": 6, "correct_answer": "博弈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在图书馆博弈，看了三本书。", "explanation": "这里应该用〈读书〉。“博弈”指两人斗智较量，个人读书不能说“博弈”。"}, {"text": "他在舞台上博弈，唱了一首歌。", "explanation": "这里应该用〈表演〉。“博弈”指双方对抗，唱歌是单方面的表演，不能说“博弈”。"}, {"text": "两位老人在博弈，互相帮忙。", "explanation": "这里应该用〈下棋〉。“博弈”指双方想办法赢对方，与“互相帮忙”相矛盾；只是一起下棋、不分输赢时要用“下棋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "双方进行了一张博弈，持续了整整一个下午。", "corrected_sentence": "双方进行了一场博弈，持续了整整一个下午。", "error_description": "量词错误：“博弈”的量词应为“场”，不能用“张”。正确为“一场博弈”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两人正在进行一场激烈得博弈。", "corrected_sentence": "两人正在进行一场激烈的博弈。", "error_description": "助词错误：“激烈”修饰名词“博弈”时应用“的”，不能用“得”；“得”用于动词或形容词之后引出补语。正确为“激烈的博弈”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
