INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人或事物之间的连接。", "primary_collocate": null, "pronunciation": "guān xì", "ipa": "kwan˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "我和同事的关系很好。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事和你没有关系。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子的关系很重要。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气和心情有什么关系？", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是朋友关系，不是家人。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的关系越来越近。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃得太多和生病有关系。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和邻居搞好关系。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生的关系像朋友。", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道他们两个是什么关系吗？", "target_word": "关系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种关系", "label": "量词"}, {"form": "人际关系", "label": "复合"}], "register": "中性", "sense_fingerprint": "人与人、事物与事物之间的联系或相互关联", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系", "is_correct": true, "explanation": "正确：「关系」指人与人之间的联系，与「很好」搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」是自然现象，不指人际状况，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」指身体的重量，不能用「很好」形容同事之间的状况。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」指色彩，不能说与同事的颜色很好。"}], "explanations": {"关系": "正确：「关系」指人与人之间的联系，与「很好」搭配，符合句意。", "天气": "语义：「天气」是自然现象，不指人际状况，与句意不符。", "体重": "搭配：「体重」指身体的重量，不能用「很好」形容同事之间的状况。", "颜色": "搭配：「颜色」指色彩，不能说与同事的颜色很好。"}, "sentence_index": 0, "correct_answer": "关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每个星期都通过电话关系，聊得很开心。", "explanation": "这里应该用〈联系〉。关系是名词，表示人或事物之间的关系，不能作动词表示保持联系。"}, {"text": "妈妈很关系我的身体，每天都问我吃饭了没有。", "explanation": "这里应该用〈关心〉。关系作动词只用于「关系到……」的结构，不能直接带人作宾语表示在意。"}, {"text": "我和他之间有一座关系，朋友都知道。", "explanation": "这里应该用〈段〉。关系用「一种关系」或「一段关系」计量，「座」用于建筑、山等，不能用来计量关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系", "is_correct": true, "explanation": "正确：「吃得太多和生病有关系」，表示两者相关，符合常识。"}, {"text": "秘密", "is_correct": false, "explanation": "语义：「秘密」指不让人知道的事，与句子说的常识性因果无关。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「有味道」不能用来说吃得太多与生病之间的关系。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：「性格」指人的个性，不能与「生病」搭配成「有性格」。"}], "explanations": {"关系": "正确：「吃得太多和生病有关系」，表示两者相关，符合常识。", "秘密": "语义：「秘密」指不让人知道的事，与句子说的常识性因果无关。", "味道": "搭配：「有味道」不能用来说吃得太多与生病之间的关系。", "性格": "搭配：「性格」指人的个性，不能与「生病」搭配成「有性格」。"}, "sentence_index": 6, "correct_answer": "关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事很关系，大家都要认真对待。", "explanation": "这里应该用〈关键〉。关系不作形容词，不能说「很关系」来表示重要。"}, {"text": "我关系他很多年了，他是我的老朋友。", "explanation": "这里应该用〈认识〉。关系不能直接带人作宾语表示认识。"}, {"text": "见到老师要关系。", "explanation": "这里应该用〈打招呼〉。关系是名词，不能作动词表示问候。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和父母地关系一直很好。", "corrected_sentence": "我和父母的关系一直很好。", "error_description": "错误：修饰语「的」用成了「地」。「地」用于修饰动词、形容词，「关系」是名词，修饰它要用「的」。正确说法：我和父母的关系一直很好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们之间曾经有一座很长的关系。", "corrected_sentence": "他们之间曾经有一段很长的关系。", "error_description": "错误：量词「座」用错。「座」用于建筑、山等，不能计量关系；应改为「段」，说「一段很长的关系」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
