INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "道德是告诉人们什么行为是好的、什么行为是不好的规则。", "primary_collocate": null, "pronunciation": "dào dé", "ipa": "tau̯˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要讲道德。", "target_word": "道德", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是一个有道德的人。", "target_word": "道德", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子要从小学习道德。", "target_word": "道德", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师常常教我们要有道德。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诚实是一种重要的道德。", "target_word": "道德", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意也要讲道德，不能骗人。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的行为没有道德，大家都不喜欢他。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管有没有钱，每个人都要讲道德。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事跟法律没关系，只是道德问题。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都不讲道德，社会会很乱。", "target_word": "道德", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "道德观", "label": "复合"}, {"form": "不道德", "label": "复合"}], "register": "中性", "sense_fingerprint": "判断行为好坏的社会规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道德", "is_correct": true, "explanation": "正确：“我们要讲道德”中，“讲”后面接“道德”最自然。"}, {"text": "便宜", "is_correct": false, "explanation": "词性：“便宜”是形容词，不能作“讲”的宾语，“我们要讲便宜”不成句。"}, {"text": "很累", "is_correct": false, "explanation": "语法：“很累”是形容词短语，不能放在“讲”后面作宾语。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：“讲”可以接“道德、礼貌、卫生”等规范，不说“讲高兴”。"}], "explanations": {"道德": "正确：“我们要讲道德”中，“讲”后面接“道德”最自然。", "便宜": "词性：“便宜”是形容词，不能作“讲”的宾语，“我们要讲便宜”不成句。", "很累": "语法：“很累”是形容词短语，不能放在“讲”后面作宾语。", "高兴": "搭配：“讲”可以接“道德、礼貌、卫生”等规范，不说“讲高兴”。"}, "sentence_index": 0, "correct_answer": "道德"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "诚实是一只道德。", "explanation": "这里量词用错。“一只”用于小动物或小件物品，道德是抽象概念，应说“一种道德”。"}, {"text": "这首歌很道德，大家都爱唱。", "explanation": "这里应该用〈好听〉。“道德”指判断善恶的准则，形容歌曲应说“好听”。"}, {"text": "这把椅子很道德。", "explanation": "这里应该用〈结实〉。“道德”指判断善恶的准则，形容椅子牢固要用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道德", "is_correct": true, "explanation": "正确：“他的行为没有道德”指行为不符合善恶的准则，“道德”最合适。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体所占空间的大小，不能用来说行为。"}, {"text": "电量", "is_correct": false, "explanation": "语义：“电量”指电的多少，与行为的好坏无关，不能用来说行为。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，与行为的好坏无关。"}], "explanations": {"道德": "正确：“他的行为没有道德”指行为不符合善恶的准则，“道德”最合适。", "体积": "语义：“体积”指物体所占空间的大小，不能用来说行为。", "电量": "语义：“电量”指电的多少，与行为的好坏无关，不能用来说行为。", "面积": "语义：“面积”指平面的大小，与行为的好坏无关。"}, "sentence_index": 6, "correct_answer": "道德"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本道德。", "explanation": "这里量词用错。“一本”用于书籍，道德是抽象概念，不能用“本”。"}, {"text": "我们在道德里学习科学。", "explanation": "这里应该用〈学校〉。“道德”是抽象概念，不能指处所，应说在学校里学习科学。"}, {"text": "这么长的道德，我们走了很久。", "explanation": "这里应该用〈道路〉。“道德”指判断善恶的准则，说路的长短要用“道路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师很讲了道德。", "corrected_sentence": "这位老师很讲道德。", "error_description": "错误在“了”：“很”修饰的是性质或状态，不能与表示完成的“了”同用，应去掉“了”，说“这位老师很讲道德”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个人没有一个道德，所以很少有朋友。", "corrected_sentence": "这个人没有道德，所以很少有朋友。", "error_description": "错误形式：“一个道德”。正确形式：“道德”。“道德”是抽象概念，不能用量词“个”计量，应去掉量词，说“没有道德”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
