INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21816, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家要一起讨论的事情。", "primary_collocate": null, "pronunciation": "yì tí", "ipa": "i˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "今天会议的第一个议题是新产品的价格。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个议题很重要，大家都要发言。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在会上提出了一个新议题。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议只有两个议题，一小时就开完了。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这个议题写在黑板上，让大家讨论。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下次开会的议题是什么？", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次小组讨论的议题是环境保护。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议题太多，会议开了很久。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这个议题有不同的看法。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们讨论了三个议题，最后一个最难。", "target_word": "议题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "热门议题", "label": "复合"}], "register": "正式", "sense_fingerprint": "会议或讨论中要大家一起谈的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议题", "is_correct": true, "explanation": "正确。听到的是 yì tí，意思是大家要一起讨论的事情。"}, {"text": "例题", "is_correct": false, "explanation": "声母不同：lì 的声母是 l，yì 没有辅音声母。“例题”意思是练习用的例子题目。"}, {"text": "一体", "is_correct": false, "explanation": "声调不同：一体读 yītǐ，yī（第一声）与 yì（第四声）、tǐ（第三声）与 tí（第二声）都不同。意思是整体、融为一体。"}, {"text": "意图", "is_correct": false, "explanation": "第二个音节 tú 与 tí 韵母不同（u 与 i），意思是打算要达到的目的。"}], "explanations": {"议题": "正确。听到的是 yì tí，意思是大家要一起讨论的事情。", "例题": "声母不同：lì 的声母是 l，yì 没有辅音声母。“例题”意思是练习用的例子题目。", "一体": "声调不同：一体读 yītǐ，yī（第一声）与 yì（第四声）、tǐ（第三声）与 tí（第二声）都不同。意思是整体、融为一体。", "意图": "第二个音节 tú 与 tí 韵母不同（u 与 i），意思是打算要达到的目的。"}, "sentence_index": null, "correct_answer": "议题"}, "level_3": {"options": [{"text": "议题", "is_correct": true, "explanation": "正确。“议题”指大家要一起讨论的事项，这里指会议第一个要讨论的内容。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能是会议上要讨论的事项。"}, {"text": "地点", "is_correct": false, "explanation": "语义：地点指位置，不能是会议上要讨论的内容。"}, {"text": "口号", "is_correct": false, "explanation": "搭配：“口号”是喊出来或用来宣传的标语，会议的第一项内容不说“口号”。"}], "explanations": {"议题": "正确。“议题”指大家要一起讨论的事项，这里指会议第一个要讨论的内容。", "桌子": "语义：桌子是家具，不能是会议上要讨论的事项。", "地点": "语义：地点指位置，不能是会议上要讨论的内容。", "口号": "搭配：“口号”是喊出来或用来宣传的标语，会议的第一项内容不说“口号”。"}, "sentence_index": 0, "correct_answer": "议题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一个议题送给朋友。", "explanation": "这里应该用〈礼物〉。议题是待讨论的事项，不是可以买来送人的东西，买东西要说〈礼物〉。"}, {"text": "这次议题开了两个小时。", "explanation": "这里应该用〈会议〉。议题是要讨论的事项，不能说“开”，开的是会议。"}, {"text": "会议作出了一项议题。", "explanation": "这里应该用〈决议〉。作出的是决议，议题是待讨论的事项，不能说“作出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "议题", "is_correct": true, "explanation": "正确。“议题”指讨论的事项，这次小组讨论的事项是环境保护。"}, {"text": "服装", "is_correct": false, "explanation": "语义：服装是衣物，不能是小组讨论的事项。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”不是讨论的内容，不能与“讨论的……是环境保护”搭配。"}, {"text": "方式", "is_correct": false, "explanation": "语义：方式指做事的方法，环境保护是事项，不能等同于方式。"}], "explanations": {"议题": "正确。“议题”指讨论的事项，这次小组讨论的事项是环境保护。", "服装": "语义：服装是衣物，不能是小组讨论的事项。", "声音": "搭配：“声音”不是讨论的内容，不能与“讨论的……是环境保护”搭配。", "方式": "语义：方式指做事的方法，环境保护是事项，不能等同于方式。"}, "sentence_index": 6, "correct_answer": "议题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们进行了一场激烈的议题。", "explanation": "这里应该用〈辩论〉。议题是待讨论的事项，本身不是一场活动，不能说“进行”。"}, {"text": "校长做了一场精彩的议题。", "explanation": "这里应该用〈演讲〉。议题不是可以做出来的发言，做出精彩内容要说〈演讲〉。"}, {"text": "大家都很喜欢这个议题的味道。", "explanation": "这里应该用〈菜〉。议题是待讨论的事项，不能说有味道，说菜肴的味道要用〈菜〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议有几个议题们需要讨论。", "corrected_sentence": "这次会议有几个议题需要讨论。", "error_description": "错误：“议题”后面加了“们”。“们”只用于指人，议题是事物，不能加“们”表示复数；说“几个议题”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议有三本议题，我们先讨论第一个。", "corrected_sentence": "这次会议有三个议题，我们先讨论第一个。", "error_description": "错误：“议题”的量词用了“本”。“本”多用于书册，“议题”要用“个”，应说“三个议题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
