INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21820, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来代表别的东西的记号，比如加号、减号。", "primary_collocate": null, "pronunciation": "fú hào", "ipa": "fu˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "加号是一个简单的数学符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学课上，我们学了新的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减号是一个小小的横线符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在算式里，这个符号表示相乘。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑板上有加号、减号和等号这些符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把算式里的符号写错了。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明分不清加号和减号这两个符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学书里用符号代表不同的元素。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在计算器上，每个符号都对应一个按键。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算式里没有符号，我们就不知道要加还是要减。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "数学、化学等中代表数量、运算或事物的记号，如加号、减号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3242d957-0d44-43bf-84d5-365f64ae4fa4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：数学中代表运算的记号，加号是一种数学符号。"}, {"text": "数字", "is_correct": false, "explanation": "语义：加号不是数字，“数学数字”与加号的定义相矛盾。"}, {"text": "答案", "is_correct": false, "explanation": "语义：加号是运算的记号，不是答案，与“简单的数学答案”不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“数学”不能修饰“颜色”，这一搭配不成立。"}], "explanations": {"符号": "符号：数学中代表运算的记号，加号是一种数学符号。", "数字": "语义：加号不是数字，“数学数字”与加号的定义相矛盾。", "答案": "语义：加号是运算的记号，不是答案，与“简单的数学答案”不符。", "颜色": "搭配：“数学”不能修饰“颜色”，这一搭配不成立。"}, "sentence_index": 0, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的符号很好听。", "explanation": "这里应该用〈名字〉。符号是用来代表别的东西的记号，不能用来形容人的名字好不好听。"}, {"text": "这盘菜的符号很咸，我吃不下。", "explanation": "这里应该用〈味道〉。符号是用来代表别的东西的记号，不能用来形容菜的咸淡。"}, {"text": "他算出来的符号是十五。", "explanation": "这里应该用〈数值〉。符号是表示运算的记号，不能表示一个具体的数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：表示加号、减号等运算的记号，“分不清这两个符号”指的就是这个。"}, {"text": "数量", "is_correct": false, "explanation": "语义：加号和减号是记号，不是数量，“分不清这两个数量”不成立。"}, {"text": "声音", "is_correct": false, "explanation": "语义：加号和减号是书写的记号，不是声音。"}, {"text": "手指", "is_correct": false, "explanation": "搭配：“这两个手指”与“分不清加号和减号”之间没有合理的搭配关系。"}], "explanations": {"符号": "符号：表示加号、减号等运算的记号，“分不清这两个符号”指的就是这个。", "数量": "语义：加号和减号是记号，不是数量，“分不清这两个数量”不成立。", "声音": "语义：加号和减号是书写的记号，不是声音。", "手指": "搭配：“这两个手指”与“分不清加号和减号”之间没有合理的搭配关系。"}, "sentence_index": 6, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的符号在第三排。", "explanation": "这里应该用〈座位〉。符号是用来代表别的东西的记号，不能用来说明人坐在哪里。"}, {"text": "他一笑，符号就很温暖。", "explanation": "这里应该用〈表情〉。符号是用来代表别的东西的记号，不能用来形容笑起来的神情。"}, {"text": "这道题的符号是十二。", "explanation": "这里应该用〈答案〉。符号是运算的记号，不能作为题目的答案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数学书上有一条符号。", "corrected_sentence": "数学书上有一个符号。", "error_description": "量词错误：“符号”应该用量词“个”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "算式里有一条符号写错了。", "corrected_sentence": "算式里有一个符号写错了。", "error_description": "量词错误：“符号”应该用量词“个”，不能用“条”。“条”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcc60ecd-01d6-4c42-a474-f71206ff99a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
