INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21822, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用笔在纸上做出线条或图形。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "他在纸上画了一只猫。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹喜欢画花和小鸟。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个圆。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能给我画一张地图吗？", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在用铅笔画自己的家。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画得很好，大家都喜欢。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用红笔画一条线。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸教我怎么画树。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都去公园画风景。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这座山画下来。", "target_word": "画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "画了", "label": "体标"}, {"form": "画过", "label": "体标"}, {"form": "画画", "label": "重叠"}, {"form": "画家", "label": "复合"}, {"form": "画笔", "label": "复合"}], "register": "中性", "sense_fingerprint": "用笔画出线条或图形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21822, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "画", "is_correct": true, "explanation": "画（huà，第四声）：用笔在纸上做出线条或图形，即本题目标词。"}, {"text": "花", "is_correct": false, "explanation": "花（huā，第一声）与 huà（第四声）声调不同，意思是花朵。"}, {"text": "华", "is_correct": false, "explanation": "华（huá，第二声）与 huà 声调不同，意思是中华、光彩。"}, {"text": "挂", "is_correct": false, "explanation": "挂（guà）与 huà 声母不同（g 与 h），意思是悬挂。"}, {"text": "换", "is_correct": false, "explanation": "换（huàn）比 huà 多一个韵尾 n，意思是交换。"}], "explanations": {"画": "画（huà，第四声）：用笔在纸上做出线条或图形，即本题目标词。", "花": "花（huā，第一声）与 huà（第四声）声调不同，意思是花朵。", "华": "华（huá，第二声）与 huà 声调不同，意思是中华、光彩。", "挂": "挂（guà）与 huà 声母不同（g 与 h），意思是悬挂。", "换": "换（huàn）比 huà 多一个韵尾 n，意思是交换。"}, "sentence_index": null, "correct_answer": "画"}, "level_3": {"options": [{"text": "画", "is_correct": true, "explanation": "正确：“画”指用笔描绘，与“纸上”和“一只猫”搭配。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”接文字，不接“猫”。"}, {"text": "养", "is_correct": false, "explanation": "语义：“养”指饲养，与“在纸上”的地点矛盾。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”需要交易和商店，在纸上买猫说不通。"}], "explanations": {"画": "正确：“画”指用笔描绘，与“纸上”和“一只猫”搭配。", "写": "搭配：“写”接文字，不接“猫”。", "养": "语义：“养”指饲养，与“在纸上”的地点矛盾。", "买": "语义：“买”需要交易和商店，在纸上买猫说不通。"}, "sentence_index": 0, "correct_answer": "画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给朋友画了一封长信。", "explanation": "这里应该用〈写〉。写信用“写”，“画”指用笔描绘线条或图形，不能用于信件。"}, {"text": "天冷了，妈妈用毛线给我画了一件毛衣。", "explanation": "这里应该用〈织〉。用毛线做毛衣要用“织”，“画”指用笔描绘线条或图形，不能用于编织。"}, {"text": "妈妈用针线把被子画好了。", "explanation": "这里应该用〈缝〉。用针线做被子要用“缝”，“画”指用笔描绘线条或图形，不能用于缝制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21822, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "画", "is_correct": true, "explanation": "画（huà，第四声）：用笔在纸上做出线条或图形，即本题目标词。"}, {"text": "滑", "is_correct": false, "explanation": "滑（huá，第二声）与 huà 声调不同，意思是光滑。"}, {"text": "划", "is_correct": false, "explanation": "划（huá，第二声）与 huà 声调不同，意思是划船、划分。"}, {"text": "晃", "is_correct": false, "explanation": "晃（huàng）比 huà 多一个韵尾 ng，意思是晃动。"}, {"text": "跨", "is_correct": false, "explanation": "跨（kuà）与 huà 声母不同（k 与 h），意思是跨越。"}], "explanations": {"画": "画（huà，第四声）：用笔在纸上做出线条或图形，即本题目标词。", "滑": "滑（huá，第二声）与 huà 声调不同，意思是光滑。", "划": "划（huá，第二声）与 huà 声调不同，意思是划船、划分。", "晃": "晃（huàng）比 huà 多一个韵尾 ng，意思是晃动。", "跨": "跨（kuà）与 huà 声母不同（k 与 h），意思是跨越。"}, "sentence_index": null, "correct_answer": "画"}, "level_3": {"options": [{"text": "画", "is_correct": true, "explanation": "正确：“画”指用笔画出线条，与“红笔”和“一条线”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去，与“用红笔”画线的动作不符。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”要用剪刀，不能用红笔完成。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只接食物，不接“线”。"}], "explanations": {"画": "正确：“画”指用笔画出线条，与“红笔”和“一条线”搭配。", "擦": "语义：“擦”指抹去，与“用红笔”画线的动作不符。", "剪": "语义：“剪”要用剪刀，不能用红笔完成。", "吃": "搭配：“吃”只接食物，不接“线”。"}, "sentence_index": 6, "correct_answer": "画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都要画一个小时的歌。", "explanation": "这里应该用〈唱〉。唱歌要用“唱”，“画”指用笔描绘线条或图形，不能用于歌曲。"}, {"text": "我在厨房用小火画了一锅汤。", "explanation": "这里应该用〈熬〉。用小火做汤要用“熬”，“画”指用笔描绘线条或图形，不能用于烹饪。"}, {"text": "他把衣服画进了箱子里。", "explanation": "这里应该用〈放〉。把衣服放进箱子要用“放”，“画”指用笔描绘线条或图形，不能用于装放物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟画很好。", "corrected_sentence": "我弟弟画得很好。", "error_description": "“画”后要用“得”引出补语：应说“画得很好”，不能说“画很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈以前过画一幅肖像画。", "corrected_sentence": "妈妈以前画过一幅肖像画。", "error_description": "“过”表示经历，应紧跟在动词后：说“画过一幅肖像画”，不能说“过画一幅肖像画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
