INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写音乐的人。", "primary_collocate": null, "pronunciation": "zuò qǔ jiā", "ipa": "tswɔ˥˩ tɕʰy˨˩˦ tɕja˥", "syllable_count": 3, "sentences": [{"text": "他是一位有名的作曲家。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爷爷是作曲家。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作曲家写过很多好听的歌。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位作曲家住在一个小城市。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲家正在钢琴前写新歌。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就想当作曲家。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "莫扎特是很有名的作曲家。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是一位年轻的作曲家写的。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作曲家给这部电影写了音乐。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位中国作曲家。", "target_word": "作曲家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "作曲", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，专门创作音乐作品的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作曲家", "is_correct": true, "explanation": "正确：“作曲家”指写音乐的人，与“他是一位有名的……”相符。"}, {"text": "女歌手", "is_correct": false, "explanation": "语义：“女”与前文的“他”性别不符，“他是一位有名的女歌手”不通。"}, {"text": "老奶奶", "is_correct": false, "explanation": "体貌：“老奶奶”的年龄与性别都与“他”不符。"}, {"text": "女演员", "is_correct": false, "explanation": "语义：“女”与前文的“他”性别不符，“他是一位有名的女演员”不通。"}], "explanations": {"作曲家": "正确：“作曲家”指写音乐的人，与“他是一位有名的……”相符。", "女歌手": "语义：“女”与前文的“他”性别不符，“他是一位有名的女歌手”不通。", "老奶奶": "体貌：“老奶奶”的年龄与性别都与“他”不符。", "女演员": "语义：“女”与前文的“他”性别不符，“他是一位有名的女演员”不通。"}, "sentence_index": 0, "correct_answer": "作曲家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位作曲家在医院里给病人看病。", "explanation": "这里应该用〈医生〉。作曲家是写音乐的人，给病人看病要用〈医生〉。"}, {"text": "那位作曲家设计了这座大楼。", "explanation": "这里应该用〈设计师〉。作曲家是写音乐的人，设计大楼要用〈设计师〉。"}, {"text": "那位作曲家在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。作曲家是写音乐的人，在法庭上为被告辩护要用〈律师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作曲家", "is_correct": true, "explanation": "正确：“作曲家”指写音乐的人，与“莫扎特”的身份相符。"}, {"text": "女钢琴家", "is_correct": false, "explanation": "语义：“女”与“莫扎特”的男性身份不符。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：“小学生”的身份与“莫扎特”作为著名音乐家的身份不符。"}, {"text": "售货员", "is_correct": false, "explanation": "身份：莫扎特是作曲家，“售货员”与其身份不符，句意不通。"}], "explanations": {"作曲家": "正确：“作曲家”指写音乐的人，与“莫扎特”的身份相符。", "女钢琴家": "语义：“女”与“莫扎特”的男性身份不符。", "小学生": "语义：“小学生”的身份与“莫扎特”作为著名音乐家的身份不符。", "售货员": "身份：莫扎特是作曲家，“售货员”与其身份不符，句意不通。"}, "sentence_index": 6, "correct_answer": "作曲家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位作曲家冲进火场救出了一个孩子。", "explanation": "这里应该用〈消防员〉。作曲家是写音乐的人，冲进火场救人要用〈消防员〉。"}, {"text": "那位作曲家在足球场上吹哨判罚。", "explanation": "这里应该用〈裁判〉。作曲家是写音乐的人，在球场上吹哨判罚要用〈裁判〉。"}, {"text": "那位作曲家每天给病人打针。", "explanation": "这里应该用〈护士〉。作曲家写的是乐曲，给病人打针要用〈护士〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只年轻的作曲家刚写完一首新歌。", "corrected_sentence": "这位年轻的作曲家刚写完一首新歌。", "error_description": "错误：“只”是用于动物等的量词，修饰人要用“位”。正确：“这位年轻的作曲家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一位很有才华的作曲家们。", "corrected_sentence": "她是一位很有才华的作曲家。", "error_description": "错误：“们”表示复数，不能与数量词“一位”同用，应去掉“们”。正确：“她是一位很有才华的作曲家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
