INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想要写", "primary_collocate": null, "pronunciation": "xiǎng xiě", "ipa": "ɕjɑŋ˨˩ ɕjɛ˨˩", "syllable_count": 2, "sentences": [{"text": "他想写一篇短文，可是没有时间。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想写毛笔字还是铅笔字？", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想写一张生日卡片给姐姐。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师想写一本给孩子看的书。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想写爸爸的故事。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我不想写日记。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想写自己的名字。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想写字吗？我这里有笔。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写信告诉妈妈这个好消息。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想写一首关于春天的歌。", "target_word": "想写", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不想写", "label": "否定"}, {"form": "想写了", "label": "体标"}], "register": "中性", "sense_fingerprint": "想要动笔写", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想写", "is_correct": true, "explanation": "正确：“想写”表示想要动笔写，与后句“可是没有时间”形成转折。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，不能用于“短文”。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”用于衣物，不能说缝补“短文”。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”指给植物浇水，与“短文”无关。"}], "explanations": {"想写": "正确：“想写”表示想要动笔写，与后句“可是没有时间”形成转折。", "煮": "语义：“煮”指加热食物，不能用于“短文”。", "缝补": "搭配：“缝补”用于衣物，不能说缝补“短文”。", "浇灌": "语义：“浇灌”指给植物浇水，与“短文”无关。"}, "sentence_index": 0, "correct_answer": "想写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷想写一碗面条当午饭。", "explanation": "这里应该用〈吃〉。“想写”的宾语是文字内容，面条当午饭应说想吃。"}, {"text": "她想写个热水澡。", "explanation": "这里应该用〈洗〉。“想写”不能接“澡”，洗澡应说想洗。"}, {"text": "孩子们都想写牛奶。", "explanation": "这里应该用〈喝〉。“想写”的宾语是文字，“牛奶”不能被写，应说想喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想写", "is_correct": true, "explanation": "正确：“想写”表示想要动笔写，此处指孩子们想动笔写下自己的名字。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于衣物、身体，不能说洗“名字”。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”用于把物体分开，不能用于“名字”。"}, {"text": "抬", "is_correct": false, "explanation": "语义：“抬”指用手或肩托起重物，与“名字”无关。"}], "explanations": {"想写": "正确：“想写”表示想要动笔写，此处指孩子们想动笔写下自己的名字。", "洗": "搭配：“洗”用于衣物、身体，不能说洗“名字”。", "切": "搭配：“切”用于把物体分开，不能用于“名字”。", "抬": "语义：“抬”指用手或肩托起重物，与“名字”无关。"}, "sentence_index": 6, "correct_answer": "想写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想写自行车去公园。", "explanation": "这里应该用〈骑〉。“想写”的宾语必须是文字内容，“自行车”不能被写，应说想骑。"}, {"text": "我想写一双新鞋。", "explanation": "这里应该用〈买〉。“想写”不能接“鞋”这类物品，想要物品应说想买。"}, {"text": "他很想写一杯咖啡。", "explanation": "这里应该用〈喝〉。“想写”的宾语应是文字内容，“一杯咖啡”不能被写，想喝饮料应说想喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想写一封短文给老师看。", "corrected_sentence": "他想写一篇短文给老师看。", "error_description": "量词错误：“短文”的量词应为“篇”，“封”只用于信件，不能用于短文。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她想写一封童年的故事。", "corrected_sentence": "她想写一段童年的故事。", "error_description": "量词错误：“故事”的量词应为“段”，“封”只用于信件，不能用于故事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
