INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写歌就是做一首歌。", "primary_collocate": null, "pronunciation": "xiě gē", "ipa": "ɕjɛ˨˩ kɤ˥", "syllable_count": 2, "sentences": [{"text": "他在雨天写歌，很久才把旋律谱完。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想写歌送给女朋友，歌词已经想好。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥学会弹琴以后，开始自己写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想在家写歌，还要找人编曲。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边听海浪声，一边找灵感写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写歌的时候，他常常用手机录下旋律。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老作曲家年纪大了，还在写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们社团的同学爱唱歌，也想自己写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旋律记在本子上，晚上再写歌。", "target_word": "写歌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说我的词写得好，让我也写歌。", "target_word": "写歌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "写了歌", "label": "体标"}, {"form": "写过歌", "label": "体标"}, {"form": "寫歌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己动手做一首歌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "写歌", "is_correct": true, "explanation": "写歌：动手做歌，“谱完旋律”说明是在创作。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫与谱写旋律无关，不能“谱完旋律”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与谱写旋律无关，“在雨天游泳”后谱完旋律说不通。"}, {"text": "修车", "is_correct": false, "explanation": "搭配：“修车”的宾语是车辆，不能与“旋律”搭配。"}], "explanations": {"写歌": "写歌：动手做歌，“谱完旋律”说明是在创作。", "打扫": "语义：打扫与谱写旋律无关，不能“谱完旋律”。", "游泳": "语义：游泳与谱写旋律无关，“在雨天游泳”后谱完旋律说不通。", "修车": "搭配：“修车”的宾语是车辆，不能与“旋律”搭配。"}, "sentence_index": 0, "correct_answer": "写歌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "观众在台下一边写歌，一边大声鼓掌。", "explanation": "这里应该用〈唱歌〉。写歌是做歌；台下观众跟着唱、鼓掌说的是现场演唱。"}, {"text": "他在演唱会上一边写歌，一边大声叫好。", "explanation": "这里应该用〈听歌〉。写歌是动手做歌；台下观众听完大声叫好说的是欣赏。"}, {"text": "他在酒吧里写歌，一口气点了五首。", "explanation": "这里应该用〈点歌〉。写歌是创作；一口气点了五首说的是点歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "写歌", "is_correct": true, "explanation": "写歌：动手做歌，符合“老作曲家”的身份。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”描述身体变化，与“年纪大了”的语境不合，不能说“还在长高”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生只发生一次，与“年纪大了，还在”的持续语义矛盾。"}, {"text": "换牙", "is_correct": false, "explanation": "语义：换牙是儿童时期的事，与“年纪大了，还在”矛盾，句意不通。"}], "explanations": {"写歌": "写歌：动手做歌，符合“老作曲家”的身份。", "长高": "体貌：“长高”描述身体变化，与“年纪大了”的语境不合，不能说“还在长高”。", "出生": "语义：出生只发生一次，与“年纪大了，还在”的持续语义矛盾。", "换牙": "语义：换牙是儿童时期的事，与“年纪大了，还在”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "写歌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友在录音棚帮我写歌，录了三遍才过。", "explanation": "这里应该用〈录歌〉。写歌是做歌；录了三遍才过说的是录制，要用录歌。"}, {"text": "她每天在教室里写歌，声音大得全班都听见了。", "explanation": "这里应该用〈唱歌〉。写歌是创作，不发声；声音大得全班都听见说的是唱歌。"}, {"text": "她每天在琴房写歌，练的是音阶和指法。", "explanation": "这里应该用〈练琴〉。写歌是创作；练音阶和指法说的是练琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上个月写歌过，给朋友听。", "corrected_sentence": "我上个月写过歌，给朋友听。", "error_description": "体标错误：「过」须紧跟动词，应说「写过歌」，不能说「写歌过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很写歌，每首都很好听。", "corrected_sentence": "他经常写歌，每首都很好听。", "error_description": "副词错误：“很”不能直接修饰动词“写歌”，表示频率应改用“经常”。错误形式是“他很写歌”，正确形式是“他经常写歌”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
