INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学校教学生知识的人。", "primary_collocate": null, "pronunciation": "lǎo shī", "ipa": "lau˨˩ ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "我的老师是一位女士。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了几个字。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很喜欢新来的老师。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，请问这个字怎么读？", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天老师带我们去公园。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想长大以后当老师。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的老师住在学校旁边。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说明天不用带书。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位很好的老师。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业发给了同学们。", "target_word": "老师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位老师", "label": "量词（位）"}, {"form": "一个老师", "label": "量词（个）"}, {"form": "老师们", "label": "复数"}, {"form": "老師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在学校教学生知识的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3e7fa8c-7e28-4a9f-9f73-de782ccd99f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老师", "is_correct": true, "explanation": "“老师”指教书的人，与“一位女士”搭配，句意通顺。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，不能说“一位女士”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能用“一位女士”来指称。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不是人，不能说“是一位女士”。"}], "explanations": {"老师": "“老师”指教书的人，与“一位女士”搭配，句意通顺。", "房子": "语义：“房子”不是人，不能说“一位女士”。", "天气": "语义：“天气”不是人，不能用“一位女士”来指称。", "汽车": "语义：“汽车”不是人，不能说“是一位女士”。"}, "sentence_index": 0, "correct_answer": "老师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一只新老师。", "explanation": "这里应该用〈位〉。老师指人，要用“位”或“个”，“只”多用于动物。"}, {"text": "他是一台很好的老师。", "explanation": "这里应该用〈位〉。老师指人，“台”多用于机器，不能用来计量老师。"}, {"text": "学校请来了一条新老师。", "explanation": "这里应该用〈位〉。老师指人，“条”用于细长的东西，不能用来计量老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老师", "is_correct": true, "explanation": "“老师”指在学校教学生的人，与“住在学校旁边”的人相符，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不会住在学校旁边。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“住”的主语一般是人或动物，“树”不能说“住在学校旁边”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”是食物，不能住在学校旁边。"}], "explanations": {"老师": "“老师”指在学校教学生的人，与“住在学校旁边”的人相符，句意通顺。", "桌子": "语义：“桌子”是家具，不会住在学校旁边。", "树": "搭配：“住”的主语一般是人或动物，“树”不能说“住在学校旁边”。", "饭": "语义：“饭”是食物，不能住在学校旁边。"}, "sentence_index": 6, "correct_answer": "老师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班新来了一把老师，大家都很喜欢。", "explanation": "这里应该用〈位〉。老师指人，“把”用于有柄的工具，不能用来计量老师。"}, {"text": "学校请来了一支老师。", "explanation": "这里应该用〈位〉。老师指人，“支”多用于笔、队伍等，不能用来计量老师。"}, {"text": "我家附近有一颗老师。", "explanation": "这里应该用〈位〉。老师指人，“颗”用于粒状的小东西，不能用来计量老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校来了一辆新老师。", "corrected_sentence": "我们学校来了一位新老师。", "error_description": "错误在量词“辆”。“辆”用于车辆，“老师”指人，应该用“位”（或“个”）。正确形式是“一位新老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一位很有耐心老师。", "corrected_sentence": "她是一位很有耐心的老师。", "error_description": "错误在缺少定语标记“的”。形容词修饰名词时要用“形容词+的+名词”，正确形式是“很有耐心的老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd632a329-b534-4525-a8bb-ae74d7677d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实践", "is_correct": true, "explanation": "“理论”与“实践”相对，一个是系统的道理，一个是动手去做，是一对反义词。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指大气的状况，与“理论”没有反义关系。"}, {"text": "颜色", "is_correct": false, "explanation": "“颜色”指物体呈现的样子，与“理论”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是家具，与“理论”没有反义关系。"}], "correct_answer": "实践", "explanations": {"实践": "“理论”与“实践”相对，一个是系统的道理，一个是动手去做，是一对反义词。", "天气": "“天气”指大气的状况，与“理论”没有反义关系。", "颜色": "“颜色”指物体呈现的样子，与“理论”没有反义关系。", "桌子": "“桌子”是家具，与“理论”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实践", "is_correct": true, "explanation": "“理论”与“实践”相对，是一对反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是房屋的构件，与“理论”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”指水流的自然地理事物，与“理论”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”是一种矿物，与“理论”没有反义关系。"}], "correct_answer": "实践", "explanations": {"实践": "“理论”与“实践”相对，是一对反义词。", "窗户": "“窗户”是房屋的构件，与“理论”没有反义关系。", "河流": "“河流”指水流的自然地理事物，与“理论”没有反义关系。", "石头": "“石头”是一种矿物，与“理论”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "理论就是人们想出来的解释事情为什么会发生的道理。", "primary_collocate": null, "pronunciation": "lǐ lùn", "ipa": "li˨˩ lwən˥˩", "syllable_count": 2, "sentences": [{"text": "这个理论解释了为什么天会下雨。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个新的理论。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，理论要和做事结合起来。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种理论很难懂，我看了三遍。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用理论解释星星为什么会亮。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的理论我都懂，可是不会做。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的理论没有人相信，因为没有证据。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "达尔文的理论改变了人们对生命的看法。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先学理论，再做实验。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个理论说明了人为什么会做梦。", "target_word": "理论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "理论家", "label": "复合"}, {"form": "基础理论", "label": "复合"}, {"form": "理论知识", "label": "复合"}], "register": "书面语", "sense_fingerprint": "解释事情原因的系统道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能解释为什么天会下雨，句子读不通。"}, {"text": "理论", "is_correct": true, "explanation": "“理论”指解释事情原因的系统道理，正好可以“解释为什么天会下雨”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”本身就是下雨这类现象，不能作为解释原因的主语，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“解释”的主语多是理论、理由、原因之类，不说“颜色”解释什么。"}], "explanations": {"桌子": "语义：“桌子”是家具，不能解释为什么天会下雨，句子读不通。", "理论": "“理论”指解释事情原因的系统道理，正好可以“解释为什么天会下雨”。", "天气": "语义：“天气”本身就是下雨这类现象，不能作为解释原因的主语，句意不通。", "颜色": "搭配：“解释”的主语多是理论、理由、原因之类，不说“颜色”解释什么。"}, "sentence_index": 0, "correct_answer": "理论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去书店买了一本理论。", "explanation": "这里应该用〈书〉。“理论”是抽象的道理，不是可以买到的实物，应说“买了一本书”。"}, {"text": "他做这份工作有十年的理论。", "explanation": "这里应该用〈经验〉。理论是系统的道理，靠亲身做事积累的应该说“经验”。"}, {"text": "这次旅行是我最难忘的理论。", "explanation": "这里应该用〈经历〉。“理论”指解释事情的道理，亲身遇到的事情要用“经历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是留在地上的痕迹，不能被人相信，句意不通。"}, {"text": "理论", "is_correct": true, "explanation": "“理论”是系统的道理，可以被人相信或怀疑，与“没有证据”前后呼应。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“相信”多带“说法、消息”之类的宾语，“名声”不能被“相信”，句子读不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不能被人相信，与“没有证据”也不搭配。"}], "explanations": {"脚印": "语义：“脚印”是留在地上的痕迹，不能被人相信，句意不通。", "理论": "“理论”是系统的道理，可以被人相信或怀疑，与“没有证据”前后呼应。", "名声": "搭配：“相信”多带“说法、消息”之类的宾语，“名声”不能被“相信”，句子读不通。", "椅子": "语义：“椅子”是家具，不能被人相信，与“没有证据”也不搭配。"}, "sentence_index": 6, "correct_answer": "理论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的理论已经定下来了，下周开始实施。", "explanation": "这里应该用〈计划〉。“理论”指解释事情原因的系统道理，要说已经定下来、准备实施的安排，应该用“计划”。"}, {"text": "他修车的理论非常熟练。", "explanation": "这里应该用〈技能〉。理论是系统的道理，说“熟练”的应该是靠练习掌握的技能。"}, {"text": "他有一手好理论，修什么机器都行。", "explanation": "这里应该用〈本事〉。“理论”指系统的道理，靠动手练出来的能力要用“本事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把理论已经被很多科学家接受了。", "corrected_sentence": "这个理论已经被很多科学家接受了。", "error_description": "“理论”的量词应用“个”或“套”，不能用“把”。“把”用于有柄的东西，应说“这个理论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支理论已经被很多学者认可了。", "corrected_sentence": "这个理论已经被很多学者认可了。", "error_description": "量词误用：“理论”不能用量词“支”。“支”常用于笔、歌、队伍等，应说“这个理论”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
