INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "给人用的。", "primary_collocate": null, "pronunciation": "rén yòng", "ipa": "ɻən˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这种药是人用的，不是兽用的。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶药是人用的，小狗不能吃。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药膏是人用的，不能涂在马身上。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牙膏是人用的，狗不能用。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗发水是人用的，不能给小狗洗澡。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别把人用的药给宠物吃。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是人用的体温计，不是动物用的。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种消毒液是人用的，小猫不能碰。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这瓶是人用的，马不能用。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个是人用的药，动物用的药在那边。", "target_word": "人用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "供人使用的，区别于兽用、动物用的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96644a94-d766-4004-bc27-ec755acabdc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食用", "is_correct": false, "explanation": "搭配：“食用”只说可以吃的东西，药品不能说“食用的”。"}, {"text": "人用", "is_correct": true, "explanation": "“人用”指供人使用，与后半句“不是兽用的”形成对照，填入正确。"}, {"text": "野生", "is_correct": false, "explanation": "语义：“野生”说明天然生长，不表示用途，与“兽用”的用途对照不合。"}, {"text": "易燃", "is_correct": false, "explanation": "语义：“易燃”说明物质性质，不能说明这种药供谁使用，与“兽用”对照不合。"}], "explanations": {"食用": "搭配：“食用”只说可以吃的东西，药品不能说“食用的”。", "人用": "“人用”指供人使用，与后半句“不是兽用的”形成对照，填入正确。", "野生": "语义：“野生”说明天然生长，不表示用途，与“兽用”的用途对照不合。", "易燃": "语义：“易燃”说明物质性质，不能说明这种药供谁使用，与“兽用”对照不合。"}, "sentence_index": 0, "correct_answer": "人用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只猫是人用的，每天陪主人玩。", "explanation": "这里不能用〈人用〉。“人用”只修饰供人使用的物品，猫是动物，不能说它是人用的。"}, {"text": "这位医生是人用的，专门给病人看病。", "explanation": "这里不能用〈人用〉。“人用”只修饰供人使用的物品，不能用来形容医生这样的人。"}, {"text": "这匹马是人用的，今天在草地上吃草。", "explanation": "这里不能用〈人用〉。“人用”只修饰供人使用的物品，马是动物，不能说它是人用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”描述天气或温度，不能说明体温计供谁使用，与“不是动物用的”的用途对照不合。"}, {"text": "人用", "is_correct": true, "explanation": "“人用”指供人使用，与“不是动物用的”形成对照，填入正确。"}, {"text": "有毒", "is_correct": false, "explanation": "语义：“有毒”说明性质，不表示使用对象，句中要求的是用途对照，因此不合。"}, {"text": "兽用", "is_correct": false, "explanation": "语义：“兽用”与“不是动物用的”意思相反，句中自相矛盾。"}], "explanations": {"炎热": "语义：“炎热”描述天气或温度，不能说明体温计供谁使用，与“不是动物用的”的用途对照不合。", "人用": "“人用”指供人使用，与“不是动物用的”形成对照，填入正确。", "有毒": "语义：“有毒”说明性质，不表示使用对象，句中要求的是用途对照，因此不合。", "兽用": "语义：“兽用”与“不是动物用的”意思相反，句中自相矛盾。"}, "sentence_index": 6, "correct_answer": "人用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药是人用的，给猫吃。", "explanation": "这里应该用〈兽用〉。“人用”指供人使用，给猫吃的药要说兽用。"}, {"text": "这些饲料是人用的，给牛吃。", "explanation": "这里不能用〈人用〉。饲料供牛吃，“人用”的对象是人，应说〈兽用〉。"}, {"text": "这只羊是人用的，每天在山坡上吃草。", "explanation": "这里不能用〈人用〉。“人用”指供人使用的物品，羊是动物，不能说它是人用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种药很人用的，狗不能吃。", "corrected_sentence": "这种药是人用的，狗不能吃。", "error_description": "错误：很人用的。正确：是人用的。“人用”不能被“很”修饰，应用“是……的”来表示。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种剪刀是人用了的，猫不能碰。", "corrected_sentence": "这种剪刀是人用的，猫不能碰。", "error_description": "助词错误：“人用”后面不能加“了”，正确的说法是“人用的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88b10bc5-365c-4b4a-ba4f-220876422222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "学", "is_correct": true, "explanation": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。"}, {"text": "吃", "is_correct": false, "explanation": "无关：“吃”与“教”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "无关：“跑”与“教”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "无关：“睡”与“教”没有反义关系。"}], "correct_answer": "学", "explanations": {"学": "反义：“教”是让人学会，“学”是跟着别人学，二者相对。", "吃": "无关：“吃”与“教”没有反义关系。", "跑": "无关：“跑”与“教”没有反义关系。", "睡": "无关：“睡”与“教”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
