INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人跟着你的样子做事情。", "primary_collocate": null, "pronunciation": "jiāo", "ipa": "tɕiɑʊ̯˥", "syllable_count": 1, "sentences": [{"text": "爸爸教我骑自行车。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你教我怎么用这个手机。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶教孙女包饺子。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐教我做西红柿炒蛋。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他教了我一个简单的办法。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们写汉字。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想教小狗坐下。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友教我怎么泡茶。", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我把衣服叠好。", "target_word": "教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁教你这样做的？", "target_word": "教", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "教了", "label": "体标（了）"}, {"form": "教过", "label": "体标（过）"}, {"form": "教教", "label": "重叠"}], "register": "中性", "sense_fingerprint": "教：做给别人看，让别人学会做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3299c7cb-711f-45ac-8e59-3053bcf7ff57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教", "is_correct": true, "explanation": "jiāo（第一声）意思是教，即让别人跟着你的样子学会做事。"}, {"text": "叫", "is_correct": false, "explanation": "jiào（第四声）与 jiāo（第一声）声调不同，意思是呼喊。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是脚。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo 与 jiāo 声母不同，意思是敲打。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 jiāo 声母不同，意思是消失或消除。"}, {"text": "江", "is_correct": false, "explanation": "jiāng 与 jiāo 韵母不同，意思是江河。"}], "explanations": {"教": "jiāo（第一声）意思是教，即让别人跟着你的样子学会做事。", "叫": "jiào（第四声）与 jiāo（第一声）声调不同，意思是呼喊。", "脚": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是脚。", "敲": "qiāo 与 jiāo 声母不同，意思是敲打。", "消": "xiāo 与 jiāo 声母不同，意思是消失或消除。", "江": "jiāng 与 jiāo 韵母不同，意思是江河。"}, "sentence_index": null, "correct_answer": "教"}, "level_3": {"options": [{"text": "教", "is_correct": true, "explanation": "教：让人学会骑车，与“爸爸教我”的句意相符。"}, {"text": "追", "is_correct": false, "explanation": "语义：追是追赶，“爸爸追我骑自行车”说的不是教人骑车。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：吃的宾语应是食物，不能与“骑自行车”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：擦的宾语是物件表面，“擦我骑自行车”不成立。"}], "explanations": {"教": "教：让人学会骑车，与“爸爸教我”的句意相符。", "追": "语义：追是追赶，“爸爸追我骑自行车”说的不是教人骑车。", "吃": "搭配：吃的宾语应是食物，不能与“骑自行车”搭配。", "擦": "搭配：擦的宾语是物件表面，“擦我骑自行车”不成立。"}, "sentence_index": 0, "correct_answer": "教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他教我明天的会议取消了。", "explanation": "这里应该用〈告诉〉。“教”指让人学会某种做法，传达会议取消的消息要用〈告诉〉。"}, {"text": "学校教我们下周放假。", "explanation": "这里应该用〈通知〉。“教”是让人学会某事，宣布放假这类消息要用〈通知〉。"}, {"text": "周末我教朋友去公园散步。", "explanation": "这里应该用〈陪〉。“教”是让人学会做事，陪同朋友外出散步要用〈陪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教", "is_correct": true, "explanation": "jiāo（第一声）意思是教，即让别人学会做某件事。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是角落或角度。"}, {"text": "较", "is_correct": false, "explanation": "jiào（第四声）与 jiāo（第一声）声调不同，意思是比较。"}, {"text": "家", "is_correct": false, "explanation": "jiā 与 jiāo 韵母不同，意思是家庭。"}, {"text": "嚼", "is_correct": false, "explanation": "jiáo（第二声）与 jiāo（第一声）声调不同，意思是咀嚼。"}], "explanations": {"教": "jiāo（第一声）意思是教，即让别人学会做某件事。", "角": "jiǎo（第三声）与 jiāo（第一声）声调不同，意思是角落或角度。", "较": "jiào（第四声）与 jiāo（第一声）声调不同，意思是比较。", "家": "jiā 与 jiāo 韵母不同，意思是家庭。", "嚼": "jiáo（第二声）与 jiāo（第一声）声调不同，意思是咀嚼。"}, "sentence_index": null, "correct_answer": "教"}, "level_3": {"options": [{"text": "教", "is_correct": true, "explanation": "教：训练小狗听从指令坐下，与“我想教小狗坐下”的句意相符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：喂的对象是吃的东西，“喂小狗坐下”不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿的宾语是衣物，不能用于让小狗坐下。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷，“扔小狗坐下”与句意不符。"}], "explanations": {"教": "教：训练小狗听从指令坐下，与“我想教小狗坐下”的句意相符。", "喂": "搭配：喂的对象是吃的东西，“喂小狗坐下”不通。", "穿": "搭配：穿的宾语是衣物，不能用于让小狗坐下。", "扔": "语义：扔是抛掷，“扔小狗坐下”与句意不符。"}, "sentence_index": 6, "correct_answer": "教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全家人在门口教爷爷。", "explanation": "这里应该用〈迎接〉。“教”用于让人学会做事，在门口招呼来访的人要用〈迎接〉。"}, {"text": "爸爸教好了自行车。", "explanation": "这里应该用〈修〉。“教”不用于修理器物，把自行车修好要用〈修〉。"}, {"text": "我每天教房间。", "explanation": "这里应该用〈打扫〉。“教”的对象是人，清理房间要用〈打扫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷明天教了我写毛笔字。", "corrected_sentence": "爷爷明天教我写毛笔字。", "error_description": "错误：“教了”，正确：“教”。“明天”指将来，动作还没有发生，动词后不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我教了会弟弟骑自行车。", "corrected_sentence": "我教会了弟弟骑自行车。", "error_description": "错误：“教了会”，正确：“教会了”。结果补语“会”要紧跟动词“教”，“了”放在“教会”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
