INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反复做一件事，让自己更熟悉。", "primary_collocate": null, "pronunciation": "liàn xí", "ipa": "ljɛn˥˩ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "要学好游泳，就得天天练习。", "target_word": "练习", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个动作很难，我要再练习几遍。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想说好英语，你必须多练习。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天练习打字，现在打得很快。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车前，我先在空地上练习了半天。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了演好这个角色，练习了很久。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不练习的话，你很快就会忘记。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟练习骑自行车，摔了好几次。", "target_word": "练习", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们练习过很多遍，所以一点儿也不紧张。", "target_word": "练习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对着镜子练习说话，想让自己更自信。", "target_word": "练习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "练习了", "label": "体标"}, {"form": "练习过", "label": "体标"}, {"form": "练习着", "label": "体标"}, {"form": "练习练习", "label": "重叠"}, {"form": "練習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "练习|反复做一件事使自己更熟悉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "练习", "is_correct": true, "explanation": "目标词：练习（liàn xí）。"}, {"text": "联系", "is_correct": false, "explanation": "联系（lián xì）与练习两个音节的声调都不同，意思是联系。"}, {"text": "怜惜", "is_correct": false, "explanation": "怜惜（lián xī）与练习两个音节的声调都不同，意思是怜惜。"}, {"text": "利息", "is_correct": false, "explanation": "利息（lì xī）第一音节少了 an 韵尾，第二音节声调也不同，意思是利息。"}], "explanations": {"练习": "目标词：练习（liàn xí）。", "联系": "联系（lián xì）与练习两个音节的声调都不同，意思是联系。", "怜惜": "怜惜（lián xī）与练习两个音节的声调都不同，意思是怜惜。", "利息": "利息（lì xī）第一音节少了 an 韵尾，第二音节声调也不同，意思是利息。"}, "sentence_index": null, "correct_answer": "练习"}, "level_3": {"options": [{"text": "练习", "is_correct": true, "explanation": "指反复做以熟悉，与“学好游泳”的要求相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“学好游泳”无关，句子不通。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“学好”的目的相反，不能填入。"}, {"text": "休息", "is_correct": false, "explanation": "语义：天天休息与“学好游泳”的要求相反，句意不通。"}], "explanations": {"练习": "指反复做以熟悉，与“学好游泳”的要求相符。", "唱歌": "语义：唱歌与“学好游泳”无关，句子不通。", "忘记": "语义：“忘记”与“学好”的目的相反，不能填入。", "休息": "语义：天天休息与“学好游泳”的要求相反，句意不通。"}, "sentence_index": 0, "correct_answer": "练习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天练习汽车，现在修得很快。", "explanation": "这里应该用〈修理〉。“练习”指反复做以熟悉，不能直接以汽车为对象。"}, {"text": "她每天练习房间。", "explanation": "这里应该用〈整理〉。“练习”的对象是动作或技能，不是房间。"}, {"text": "他昨晚练习了一个梦。", "explanation": "这里应该用〈梦见〉。“练习”是反复做事，不能用来表示做梦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "练习", "is_correct": true, "explanation": "指反复做以熟悉，与“很快就会忘记”的因果相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”与“很快就会忘记”没有因果关系，句子不通。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”与“很快就会忘记”没有因果关系，句子不通。"}, {"text": "嘀咕", "is_correct": false, "explanation": "语域：“嘀咕”口语化，与书面的劝告语气不合。"}], "explanations": {"练习": "指反复做以熟悉，与“很快就会忘记”的因果相符。", "打扫": "语义：“打扫”与“很快就会忘记”没有因果关系，句子不通。", "旅行": "语义：“旅行”与“很快就会忘记”没有因果关系，句子不通。", "嘀咕": "语域：“嘀咕”口语化，与书面的劝告语气不合。"}, "sentence_index": 6, "correct_answer": "练习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天练习桌子。", "explanation": "这里应该用〈擦〉。“练习”不能用于清洁物品。"}, {"text": "妈妈在厨房练习了饭。", "explanation": "这里应该用〈煮〉。“练习”不能用于做饭，应说“煮饭”。"}, {"text": "我练习了一封信。", "explanation": "这里应该用〈收到〉。“练习”不能用于收取信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他练习着很多次。", "corrected_sentence": "他练习过很多次。", "error_description": "“着”表示持续，与表示经历的“很多次”不搭，应为“他练习过很多次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个动作我练习了三根。", "corrected_sentence": "这个动作我练习了三遍。", "error_description": "错误在于动作次数的量词：“练习”的次数应用“遍”或“次”，不能用“根”（根用于条状物），应为“这个动作我练习了三遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
