INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学校里上课学习的人。", "primary_collocate": null, "pronunciation": "xué shēng", "ipa": "ɕɥe˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这个班有二十个学生。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在教室里认真听课。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请学生打开书。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位学生每天走路去学校。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生下课后在操场上踢球。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学生写字写得很漂亮。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的学生坐在我旁边。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业发给了每个学生。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候，学生不能看手机。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有很多学生在等公共汽车。", "target_word": "学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "小学生", "label": "复合"}, {"form": "留学生", "label": "复合"}, {"form": "學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在学校里上课学习的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 下课 (Zipf 3.46), 操场 (Zipf 3.58), 踢球 (Zipf 3.68)','sentence 5 above tier T1: 3 words above tier T1 (max 2): 写字 (Zipf 3.59), 写得 (Zipf 3.22), 很漂亮 (Zipf 3.82)']::text[], '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": true, "explanation": "正确。“这个班有二十个学生”中，“学生”指班里的人，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：班里不可能有二十个月亮，句意荒谬。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能用“个”计数，不能说“二十个空气”。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不是班级的成员，说班里有二十个老虎，句意荒谬。"}], "explanations": {"学生": "正确。“这个班有二十个学生”中，“学生”指班里的人，符合句意。", "月亮": "语义：班里不可能有二十个月亮，句意荒谬。", "空气": "搭配：“空气”是不可数名词，不能用“个”计数，不能说“二十个空气”。", "老虎": "语义：老虎不是班级的成员，说班里有二十个老虎，句意荒谬。"}, "sentence_index": 0, "correct_answer": "学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位学生是我们公司的经理，负责销售。", "explanation": "这里应该用〈经理〉。学生指在学校学习的人，不指公司的管理者。"}, {"text": "那位学生是我们医院的护士，每天照顾病人。", "explanation": "这里应该用〈护士〉。学生指在学校学习的人，不指在医院照顾病人的工作人员。"}, {"text": "那位学生是一名司机，每天开公交车。", "explanation": "这里应该用〈司机〉。学生指在学校学习的人，不指驾驶公交车的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": true, "explanation": "正确。“新来的学生坐在我旁边”中，“学生”指新来的学习者，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“坐”的主语应是人或动物，汽车不能“坐在”旁边。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会坐，也不是新来的人，句子意思不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能坐在我旁边，句子荒谬。"}], "explanations": {"学生": "正确。“新来的学生坐在我旁边”中，“学生”指新来的学习者，符合句意。", "汽车": "搭配：“坐”的主语应是人或动物，汽车不能“坐在”旁边。", "石头": "语义：石头不会坐，也不是新来的人，句子意思不通。", "月亮": "语义：月亮不能坐在我旁边，句子荒谬。"}, "sentence_index": 6, "correct_answer": "学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗是学生，每天在校门口等我。", "explanation": "这里应该用〈小狗〉。学生指人，不能用来称呼动物。"}, {"text": "这个学生每天在医院给病人做手术。", "explanation": "这里应该用〈医生〉。学生指在学校学习的人，不指给病人做手术的医生。"}, {"text": "这个学生是我们小区的保安，每天晚上巡逻。", "explanation": "这里应该用〈保安〉。学生指在学校学习的人，不指小区里巡逻的保安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里有很多只学生在看书。", "corrected_sentence": "图书馆里有很多学生在看书。", "error_description": "量词错误：“学生”指人，不能用量词“只”（只用于动物），应去掉“只”，说“很多学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "操场上有五张学生在踢足球。", "corrected_sentence": "操场上有五个学生在踢足球。", "error_description": "量词错误：“学生”指人，应该用量词“个”，不能用“张”（用于纸、桌子等平面物体），应说“五个学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘掉", "is_correct": true, "explanation": "忘掉：不再记得，与“记住”构成反义。"}, {"text": "参观", "is_correct": false, "explanation": "参观指去看展览或场所，与“记住”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指到外地去游览，与“记住”没有反义关系。"}, {"text": "咨询", "is_correct": false, "explanation": "咨询指向别人请教或询问，与“记住”没有反义关系。"}], "correct_answer": "忘掉", "explanations": {"忘掉": "忘掉：不再记得，与“记住”构成反义。", "参观": "参观指去看展览或场所，与“记住”没有反义关系。", "旅行": "旅行指到外地去游览，与“记住”没有反义关系。", "咨询": "咨询指向别人请教或询问，与“记住”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
