INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西留在心里，不会忘掉。", "primary_collocate": null, "pronunciation": "jì zhù", "ipa": "/tɕi˥˩ ʈʂu˥˩/", "syllable_count": 2, "sentences": [{"text": "请记住我的名字。", "target_word": "记住", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个词我记住了。", "target_word": "记住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要记住回家的路。", "target_word": "记住", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说的话，你们都记住了吗？", "target_word": "记住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把他的电话号码记住了。", "target_word": "记住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站很多，我只记住了一个。", "target_word": "记住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很聪明，看一遍就能记住十个词。", "target_word": "记住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时要记住别人的名字，这很有礼貌。", "target_word": "记住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说的那句话，我记住了。", "target_word": "记住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事我会永远记住。", "target_word": "记住", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "记住了", "label": "体标"}, {"form": "没记住", "label": "否定"}], "register": "中性", "sense_fingerprint": "动词：把人、事、话牢牢留在心里，不忘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记住", "is_correct": true, "explanation": "正确答案：记住（jìzhù），把人、事、话牢牢留在心里，不忘。"}, {"text": "机主", "is_correct": false, "explanation": "jī（第一声）与 jì、zhǔ（第三声）与 zhù 的声调都不同，意思是手机的主人。"}, {"text": "技术", "is_correct": false, "explanation": "shù 与 zhù 的声母不同（sh 与 zh），意思是技术。"}, {"text": "继续", "is_correct": false, "explanation": "xù 与 zhù 的声母不同（x 与 zh），意思是接着做下去。"}], "explanations": {"记住": "正确答案：记住（jìzhù），把人、事、话牢牢留在心里，不忘。", "机主": "jī（第一声）与 jì、zhǔ（第三声）与 zhù 的声调都不同，意思是手机的主人。", "技术": "shù 与 zhù 的声母不同（sh 与 zh），意思是技术。", "继续": "xù 与 zhù 的声母不同（x 与 zh），意思是接着做下去。"}, "sentence_index": null, "correct_answer": "记住"}, "level_3": {"options": [{"text": "记住", "is_correct": true, "explanation": "记住：把事情留在心里，符合“请___我的名字”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“名字”，“吃我的名字”不成立。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”针对场所或物品，不能接“名字”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能带“名字”作宾语。"}], "explanations": {"记住": "记住：把事情留在心里，符合“请___我的名字”的语境。", "吃": "搭配：“吃”的宾语是食物，不能接“名字”，“吃我的名字”不成立。", "打扫": "搭配：“打扫”针对场所或物品，不能接“名字”。", "散步": "配价：“散步”是不及物动词，后面不能带“名字”作宾语。"}, "sentence_index": 0, "correct_answer": "记住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天早上都把窗户记住。", "explanation": "这里应该用〈关〉。“记住”指把内容留在心里，不能用来说关窗户这样的动作。"}, {"text": "他用湿布把黑板记住了。", "explanation": "这里应该用〈擦〉。“记住”指把内容留在脑中，不能用来说擦黑板。"}, {"text": "他把纸巾记住了，然后扔进了垃圾桶。", "explanation": "这里应该用〈丢〉。“记住”指把内容留在心里，不能用来说把纸巾丢掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记住", "is_correct": true, "explanation": "记住：把内容留在脑中，符合“看一遍就能___十个词”的语境。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“跳”不能和“词”搭配，“跳十个词”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象不是词语，不能说“洗十个词”。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”与“他很聪明，看一遍就能”的意思相反，句意矛盾。"}], "explanations": {"记住": "记住：把内容留在脑中，符合“看一遍就能___十个词”的语境。", "跳": "搭配：“跳”不能和“词”搭配，“跳十个词”不成立。", "洗": "搭配：“洗”的对象不是词语，不能说“洗十个词”。", "忘": "语义：“忘”与“他很聪明，看一遍就能”的意思相反，句意矛盾。"}, "sentence_index": 6, "correct_answer": "记住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一进门就把灯记住了。", "explanation": "这里应该用〈打开〉。“记住”指把内容留在脑中，不能用来说开灯。"}, {"text": "这家商店每天都记住很多水果。", "explanation": "这里应该用〈卖〉。“记住”不能用来说商店卖水果。"}, {"text": "他把桌子记住了，然后放进了卧室。", "explanation": "这里应该用〈搬〉。“记住”指把内容留在心里，不能用来说搬桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我记住不这个新单词。", "corrected_sentence": "我记不住这个新单词。", "error_description": "否定词“不”要放在“记”和“住”之间，表示记不下来，应说“记不住”，“记住不”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天没记住了这个词。", "corrected_sentence": "我昨天没记住这个词。", "error_description": "用“没”否定“记住”时，句末不能再加“了”。应去掉“了”，说成“没记住这个词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
