INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用声音表达感情的艺术，如歌曲和乐曲。", "primary_collocate": null, "pronunciation": "yīn yuè", "ipa": "/in˥ ɥe˥˩/", "syllable_count": 2, "sentences": [{"text": "我喜欢听音乐。", "target_word": "音乐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个音乐很好听。", "target_word": "音乐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天晚上都听音乐。", "target_word": "音乐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈做饭的时候喜欢放音乐。", "target_word": "音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌的音乐很安静，我常在睡前听。", "target_word": "音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学过三年音乐，会弹钢琴。", "target_word": "音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听着音乐写作业。", "target_word": "音乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，他爱听快一点的音乐。", "target_word": "音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有音乐，这个电影就不好看了。", "target_word": "音乐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们跟着音乐跳舞，玩得很开心。", "target_word": "音乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "音乐会", "label": "复合"}, {"form": "音乐家", "label": "复合"}, {"form": "段", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：用声音表达感情的艺术，如歌声、琴声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21854, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "音乐", "is_correct": true, "explanation": "正确答案：音乐（yīnyuè），好听的声音，如歌声或琴声。"}, {"text": "音域", "is_correct": false, "explanation": "yīnyù 的第二个音节 yù 与 yuè 读音相近但不同，意思是声音的高低范围。"}, {"text": "隐约", "is_correct": false, "explanation": "yǐnyuē 两个音节的声调都与 yīnyuè 不同，意思是模糊、不清楚。"}, {"text": "音韵", "is_correct": false, "explanation": "yùn 与 yuè 读音相近但韵母不同，意思是字音的声、韵、调。"}], "explanations": {"音乐": "正确答案：音乐（yīnyuè），好听的声音，如歌声或琴声。", "音域": "yīnyù 的第二个音节 yù 与 yuè 读音相近但不同，意思是声音的高低范围。", "隐约": "yǐnyuē 两个音节的声调都与 yīnyuè 不同，意思是模糊、不清楚。", "音韵": "yùn 与 yuè 读音相近但韵母不同，意思是字音的声、韵、调。"}, "sentence_index": null, "correct_answer": "音乐"}, "level_3": {"options": [{"text": "音乐", "is_correct": true, "explanation": "音乐：好听的声音，可以听，符合“我喜欢听___”的语境。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“听”不能和“桌子”搭配，“听桌子”不成立。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色是用眼睛看的，不能说“听颜色”。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：香味是用鼻子闻的，不能用“听”。"}], "explanations": {"音乐": "音乐：好听的声音，可以听，符合“我喜欢听___”的语境。", "桌子": "搭配：“听”不能和“桌子”搭配，“听桌子”不成立。", "颜色": "搭配：颜色是用眼睛看的，不能说“听颜色”。", "香味": "搭配：香味是用鼻子闻的，不能用“听”。"}, "sentence_index": 0, "correct_answer": "音乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把音乐放在桌子上，然后拿去还给了朋友。", "explanation": "这里应该用〈唱片〉。“音乐”指好听的声音，不是实物，不能放在桌子上。"}, {"text": "钢琴是一种音乐，很多人都喜欢学。", "explanation": "这里应该用〈乐器〉。钢琴是用来演奏音乐的工具，“音乐”不能指乐器。"}, {"text": "妈妈弹了一只音乐，声音很好听。", "explanation": "这里应该用〈段〉。音乐通常用“段”计量，“只”不用来计量音乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐", "is_correct": true, "explanation": "音乐：好听的声音，可以一边听一边做事，符合“听着___写作业”的语境。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“听”不能和“眼睛”搭配，“听着眼睛”不成立。"}, {"text": "地图", "is_correct": false, "explanation": "搭配：地图是用来看的，不能说“听着地图”。"}, {"text": "思想", "is_correct": false, "explanation": "语义：“思想”不发出声音，无法被“听”，与句中的情境不合。"}], "explanations": {"音乐": "音乐：好听的声音，可以一边听一边做事，符合“听着___写作业”的语境。", "眼睛": "搭配：“听”不能和“眼睛”搭配，“听着眼睛”不成立。", "地图": "搭配：地图是用来看的，不能说“听着地图”。", "思想": "语义：“思想”不发出声音，无法被“听”，与句中的情境不合。"}, "sentence_index": 6, "correct_answer": "音乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长的音乐很长，大家都听累了。", "explanation": "这里应该用〈讲话〉。“音乐”指好听的声音，不能用来说讲话的长短。"}, {"text": "这个音乐有五个成员，都很年轻。", "explanation": "这里应该用〈乐队〉。“音乐”是艺术形式，不能指有成员的团体。"}, {"text": "这个音乐有很多格子，可以装东西。", "explanation": "这里应该用〈柜子〉。“音乐”是好听的声音，不是家具，不能有格子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下班后喜欢听一只音乐。", "corrected_sentence": "我下班后喜欢听音乐。", "error_description": "“音乐”不能用量词“只”计量。应去掉“一只”，说成“喜欢听音乐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一首很好听音乐。", "corrected_sentence": "她有一首很好听的音乐。", "error_description": "“很好听”修饰名词“音乐”时要加“的”，应说“很好听的音乐”，漏掉“的”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
