INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手按或拨动琴上的弦或键，让琴发出声音。", "primary_collocate": null, "pronunciation": "tán qín", "ipa": "tʰan˧˥ tɕʰin˧˥", "syllable_count": 2, "sentences": [{"text": "他坐在钢琴前弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明每个周末都去学校弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年轻时在家弹琴给我们听。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹琴的时候，手指很轻。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上十点以后请不要弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弹琴时，两只手要放松。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弹琴弹得很好。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里有人弹琴，很多人在听。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在音乐教室里练习弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，每天上午都弹琴。", "target_word": "弹琴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹弹琴", "label": "重叠"}, {"form": "彈琴", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手指按键或拨弦使琴发声的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3108ec33-339a-4478-bb81-96f499e82975') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「弹琴」与「他坐在钢琴前」相合，指坐着演奏钢琴。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：坐着不能跑步，与「坐在钢琴前」矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：钢琴前不是洗澡的地方，“坐在钢琴前洗澡”说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐在钢琴前不能游泳，句意不通。"}], "explanations": {"弹琴": "正确：「弹琴」与「他坐在钢琴前」相合，指坐着演奏钢琴。", "跑步": "语义：坐着不能跑步，与「坐在钢琴前」矛盾。", "洗澡": "语义：钢琴前不是洗澡的地方，“坐在钢琴前洗澡”说不通。", "游泳": "语义：坐在钢琴前不能游泳，句意不通。"}, "sentence_index": 0, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上在操场弹琴，一口气跑了五圈。", "explanation": "这里应该用〈跑步〉。弹琴是用手让琴发声；跑了五圈说的是跑步。"}, {"text": "她在厨房弹琴，做了一桌好菜。", "explanation": "这里应该用〈做饭〉。弹琴是演奏乐器；做了一桌菜说的是做饭。"}, {"text": "他用嘴弹琴，吹出好听的声音。", "explanation": "这里应该用〈吹口琴〉。弹琴要用手按键或拨弦；用嘴吹出声音说的是吹奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹琴", "is_correct": true, "explanation": "正确：「他弹琴弹得很好」中，前一个「弹琴」是主要动作，与句意相合。"}, {"text": "洗碗", "is_correct": false, "explanation": "语义：洗碗与「弹得很好」搭不上，句意不通。"}, {"text": "叫醒", "is_correct": false, "explanation": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。"}, {"text": "切菜", "is_correct": false, "explanation": "语义：切菜与「弹得很好」无关，句意不通。"}], "explanations": {"弹琴": "正确：「他弹琴弹得很好」中，前一个「弹琴」是主要动作，与句意相合。", "洗碗": "语义：洗碗与「弹得很好」搭不上，句意不通。", "叫醒": "配价：「叫醒」需要被叫醒的人作宾语，句中缺宾语。", "切菜": "语义：切菜与「弹得很好」无关，句意不通。"}, "sentence_index": 6, "correct_answer": "弹琴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天弹琴去上班，骑得很快。", "explanation": "这里应该用〈骑车〉。弹琴是演奏乐器；骑得很快说的是骑车。"}, {"text": "她在游泳池里弹琴，游了一个小时。", "explanation": "这里应该用〈游泳〉。弹琴是用手让琴发声；游了一个小时说的是游泳。"}, {"text": "他在合唱团弹琴，用嗓子唱高音。", "explanation": "这里应该用〈唱歌〉。弹琴靠手指演奏；用嗓子唱说的是唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他弹琴了两个小时。", "corrected_sentence": "他弹琴弹了两个小时。", "error_description": "离合词错误：「弹琴」是离合词，后面不能直接加「了」和时量成分。要重复动词，说「弹琴弹了两个小时」，不能说「弹琴了两个小时」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟弹琴得很慢。", "corrected_sentence": "我弟弟弹琴弹得很慢。", "error_description": "补语结构错误：「弹琴弹得很慢」中需重复动词「弹」，不能说「弹琴得很慢」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd951c2e-fe87-454e-9bcd-b9c931db3176') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
