INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "告诉就是把事情说给别人听。", "primary_collocate": null, "pronunciation": "gào su", "ipa": "kɑʊ⁵¹ su", "syllable_count": 2, "sentences": [{"text": "请你告诉我他的名字。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈告诉我明天要下雨。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有告诉老师这件事。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我告诉过你,别忘了带书。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能告诉我车站在哪儿吗?", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉大家明天考试。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这个好消息告诉了朋友。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁告诉你她今天不来?", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他告诉我,他很喜欢这里。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉他要多休息。", "target_word": "告诉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "告诉了", "label": "体标"}, {"form": "告诉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事情说给别人知道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d9ab088-f832-4c2b-8bdc-c6dfd9f23bbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "告诉", "is_correct": true, "explanation": "“告诉”表示把事情说给对方知道，“告诉我他的名字”成立。"}, {"text": "问", "is_correct": false, "explanation": "语义：“问”是询问，句子要的是把名字告诉对方，意思相反。"}, {"text": "教", "is_correct": false, "explanation": "搭配：“教”教的是知识或技能，名字不能“教”。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”是把东西交给别人，名字不是可以送出的物品。"}], "explanations": {"告诉": "“告诉”表示把事情说给对方知道，“告诉我他的名字”成立。", "问": "语义：“问”是询问，句子要的是把名字告诉对方，意思相反。", "教": "搭配：“教”教的是知识或技能，名字不能“教”。", "送": "语义：“送”是把东西交给别人，名字不是可以送出的物品。"}, "sentence_index": 0, "correct_answer": "告诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他告诉了老师一杯酒。", "explanation": "这里应该用〈敬〉。敬酒要用“敬”；“告诉”后接的是信息内容，不能接“一杯酒”。"}, {"text": "妈妈告诉了我的画。", "explanation": "这里应该用〈称赞〉。称赞别人的作品用“称赞”；“告诉”的宾语应是信息，不能接“画”。"}, {"text": "他告诉了一句谢谢。", "explanation": "这里应该用〈说〉。说谢谢用“说”；“告诉”要接受话人和具体的内容，不能接“谢谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "告诉", "is_correct": true, "explanation": "“告诉”表示把好消息说给朋友知道，“把这个好消息告诉了朋友”成立。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人或成就，不能说“把好消息祝贺了朋友”。"}, {"text": "消灭", "is_correct": false, "explanation": "搭配：“消灭”用于敌人、害虫等，不能用于好消息，句意不通。"}, {"text": "骗", "is_correct": false, "explanation": "语义：“骗”是欺骗，句中是如实告诉朋友好消息，不是欺骗，句意不符。"}], "explanations": {"告诉": "“告诉”表示把好消息说给朋友知道，“把这个好消息告诉了朋友”成立。", "祝贺": "搭配：“祝贺”的对象是人或成就，不能说“把好消息祝贺了朋友”。", "消灭": "搭配：“消灭”用于敌人、害虫等，不能用于好消息，句意不通。", "骗": "语义：“骗”是欺骗，句中是如实告诉朋友好消息，不是欺骗，句意不符。"}, "sentence_index": 6, "correct_answer": "告诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他告诉了那辆旧自行车。", "explanation": "这里应该用〈修理〉。修理东西要用“修理”；“告诉”的宾语是信息，不能接“自行车”。"}, {"text": "他告诉了那件新衣服。", "explanation": "这里应该用〈穿〉。穿衣服要用“穿”；“告诉”的宾语是信息，不能接“衣服”。"}, {"text": "她告诉了我一束花。", "explanation": "这里应该用〈送〉。把花交给别人用“送”；“告诉”后接的是信息，不能接具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天告诉着朋友这件事。", "corrected_sentence": "我昨天告诉了朋友这件事。", "error_description": "错误：“着”表示动作持续，“告诉”是一次性完成的动作，且句子说“昨天”，应用表示动作完成的“了”。正确应为“告诉了朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经告诉他过了。", "corrected_sentence": "我已经告诉过他了。", "error_description": "错误：“过”放错了位置。体标“过”要紧跟在动词“告诉”后面，再接宾语“他”。正确应为“告诉过他了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3484fb66-38f4-4cf2-b5b7-6b7a6ee609d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "“复杂”是“简单”（不难、不繁琐）的反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与事情的难易无关，不是反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”形容排列有序，与“简单”的难易义没有反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”形容味道，与“简单”没有反义关系。"}], "correct_answer": "复杂", "explanations": {"复杂": "“复杂”是“简单”（不难、不繁琐）的反义词。", "高兴": "“高兴”形容心情，与事情的难易无关，不是反义关系。", "整齐": "“整齐”形容排列有序，与“简单”的难易义没有反义关系。", "甜": "“甜”形容味道，与“简单”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "复杂", "is_correct": true, "explanation": "“复杂”是“简单”（不难、不繁琐）的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线，与事情的难易无关，不是反义关系。"}, {"text": "辣", "is_correct": false, "explanation": "“辣”形容味道，与“简单”没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”形容东西坚固，与“简单”的难易义没有反义关系。"}], "correct_answer": "复杂", "explanations": {"复杂": "“复杂”是“简单”（不难、不繁琐）的反义词。", "明亮": "“明亮”形容光线，与事情的难易无关，不是反义关系。", "辣": "“辣”形容味道，与“简单”没有反义关系。", "结实": "“结实”形容东西坚固，与“简单”的难易义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不难，很容易明白或做到。", "primary_collocate": null, "pronunciation": "jiǎn dān", "ipa": "tɕjɛn˨˩ tan˥", "syllable_count": 2, "sentences": [{"text": "这道题很简单。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的操作方法很简单，新手也能用。", "target_word": "简单", "complexity_tier": "T3", "furigana": "zhè ge ruǎn jiàn de cāo zuò fāng fǎ hěn jiǎn dān, xīn shǒu yě néng yòng。", "sentence_source": "generated"}, {"text": "用这个手机很简单，你一学就会。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事说起来简单，做起来难。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试不会太简单。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜做法简单，十分钟就好了。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这个游戏很简单。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些中文句子都很简单，我能看懂。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办这张卡的手续很简单。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法简单又有用。", "target_word": "简单", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "简简单单", "label": "重叠"}, {"form": "簡單", "label": "繁体"}], "register": "中性", "sense_fingerprint": "简单：形容事情、问题不难、不复杂，容易明白或做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "简单", "is_correct": true, "explanation": "“这道题很简单”说题目不难，符合语境。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，题目不能是甜的。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”用于场面、气氛，不能用来形容一道题。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，题目本身不会聪明。"}], "explanations": {"简单": "“这道题很简单”说题目不难，符合语境。", "甜": "语义：“甜”形容味道，题目不能是甜的。", "热闹": "搭配：“热闹”用于场面、气氛，不能用来形容一道题。", "聪明": "语义：“聪明”指人的智力，题目本身不会聪明。"}, "sentence_index": 0, "correct_answer": "简单"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的长相很简单，没有什么特点。", "explanation": "这里应该用〈普通〉。“简单”说事情不复杂，不用来形容长相；长相平常要说“普通”。"}, {"text": "这个房子的价格很简单，你可以考虑一下。", "explanation": "这里应该用〈便宜〉。“简单”说事情不复杂，不用来说价格高低，价格低要说“便宜”。"}, {"text": "这台冰箱的温度很简单，零下二十度。", "explanation": "这里应该用〈低〉。“简单”不用来描述温度，温度低要说“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简单", "is_correct": true, "explanation": "“这个游戏很简单”说游戏不难，符合句意。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度，游戏没有高矮，不能说“游戏很矮”。"}, {"text": "懒", "is_correct": false, "explanation": "语义：“懒”形容人的做事态度，游戏不会懒。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”说人的生理感受，不能用来形容游戏。"}], "explanations": {"简单": "“这个游戏很简单”说游戏不难，符合句意。", "矮": "体貌：“矮”形容高度，游戏没有高矮，不能说“游戏很矮”。", "懒": "语义：“懒”形容人的做事态度，游戏不会懒。", "饿": "语义：“饿”说人的生理感受，不能用来形容游戏。"}, "sentence_index": 6, "correct_answer": "简单"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的亮度很简单，只有一点点。", "explanation": "这里应该用〈低〉。“简单”说事情不复杂，不用来描述亮度；亮度弱要说“低”。"}, {"text": "他的成绩很简单，考了全班第一。", "explanation": "这里应该用〈优秀〉。“简单”说事情不复杂，不用来评价成绩好坏，成绩好要说“优秀”。"}, {"text": "这个家庭的收入很简单，每个月只有三千元。", "explanation": "这里应该用〈少〉。“简单”不用来说收入多少，收入少要说“少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏的规则是简单。", "corrected_sentence": "这个游戏的规则很简单。", "error_description": "“是”后直接接形容词“简单”不通，应说“很简单”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书了简单，适合初学者。", "corrected_sentence": "这本书很简单，适合初学者。", "error_description": "错误：“这本书了简单”。正确：“这本书很简单”。“了”不能放在形容词“简单”前作程度修饰，应用“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
