INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21865, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "时间很长。", "primary_collocate": null, "pronunciation": "jiǔ", "ipa": "tɕjoʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你在这里等了很久吗？", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们认识很久了。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了很久，还没有停。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书放得太久，都旧了。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很久没见到老同学了。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口站了很久。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间太久，我忘了他的名字。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋穿得太久，已经破了。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让你等得太久。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了很久，才说出一句话。", "target_word": "久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "久久", "label": "重叠"}, {"form": "长久", "label": "复合"}, {"form": "永久", "label": "复合"}], "register": "中性", "sense_fingerprint": "时间长、持续得长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "久", "is_correct": true, "explanation": "久，jiǔ，指时间长。"}, {"text": "旧", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是旧的、用过的。"}, {"text": "就", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”，表示立即或接着。"}, {"text": "纠", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是纠正、纠缠。"}, {"text": "救", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是拯救、帮助脱离危险。"}], "explanations": {"久": "久，jiǔ，指时间长。", "旧": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是旧的、用过的。", "就": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是“就”，表示立即或接着。", "纠": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是纠正、纠缠。", "救": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是拯救、帮助脱离危险。"}, "sentence_index": null, "correct_answer": "久"}, "level_3": {"options": [{"text": "久", "is_correct": true, "explanation": "久指时间长，与“等了”相合。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”说距离，不说等待的时长。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“快”形容速度，“等了很快”不成立。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”形容深度，与等待的时间无关。"}], "explanations": {"久": "久指时间长，与“等了”相合。", "远": "语义：“远”说距离，不说等待的时长。", "快": "搭配：“快”形容速度，“等了很快”不成立。", "深": "语义：“深”形容深度，与等待的时间无关。"}, "sentence_index": 0, "correct_answer": "久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路很久，我走了一个多小时。", "explanation": "这里应该用〈长〉。久指时间长，形容路线的长度要用〈长〉。"}, {"text": "我家离学校很久，每天要坐公交。", "explanation": "这里应该用〈远〉。久只说时间，距离的远近要用〈远〉。"}, {"text": "这间屋子很久，住三个人正好。", "explanation": "这里应该用〈大〉。久只形容时间，不能形容空间的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21865, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "久", "is_correct": true, "explanation": "久，jiǔ，指时间长。"}, {"text": "究", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是研究、追究。"}, {"text": "揪", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是抓、拽。"}, {"text": "舅", "is_correct": false, "explanation": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是舅舅。"}, {"text": "鸠", "is_correct": false, "explanation": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是斑鸠等鸟类。"}], "explanations": {"久": "久，jiǔ，指时间长。", "究": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是研究、追究。", "揪": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是抓、拽。", "舅": "jiù（第四声）与 jiǔ（第三声）声调不同，意思是舅舅。", "鸠": "jiū（第一声）与 jiǔ（第三声）声调不同，意思是斑鸠等鸟类。"}, "sentence_index": null, "correct_answer": "久"}, "level_3": {"options": [{"text": "久", "is_correct": true, "explanation": "久指时间长，与“时间太”“忘了”相合。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”形容杂乱，不用来说时间的长短。"}, {"text": "大", "is_correct": false, "explanation": "语义：“大”形容体积或程度，不说“时间太大”。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”形容分量，“时间太重”不搭配。"}], "explanations": {"久": "久指时间长，与“时间太”“忘了”相合。", "乱": "语义：“乱”形容杂乱，不用来说时间的长短。", "大": "语义：“大”形容体积或程度，不说“时间太大”。", "重": "搭配：“重”形容分量，“时间太重”不搭配。"}, "sentence_index": 6, "correct_answer": "久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很久，站在楼下看不到顶。", "explanation": "这里应该用〈高〉。久指时间，形容楼的高度要用〈高〉。"}, {"text": "这条河很久，两岸离得很远。", "explanation": "这里应该用〈宽〉。久不表示宽窄，河面的宽度要用〈宽〉。"}, {"text": "这个箱子很久，我一个人抬不动。", "explanation": "这里应该用〈重〉。久不表示轻重，箱子的分量要用〈重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我久很没吃到家乡的菜了。", "corrected_sentence": "我很久没吃到家乡的菜了。", "error_description": "语序错误：程度副词“很”须放在“久”之前，应为“很久没”，不能说“久很没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
